#!/bin/bash
# Jormungandr Bootstrap Build System
# Compiles all self-hosted Sigil modules to a native executable

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PARSER_DIR="$SCRIPT_DIR/../parser"
SRC_DIR="$SCRIPT_DIR/src"
BUILD_DIR="$SCRIPT_DIR/build"
OUT_DIR="$BUILD_DIR/c"

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
NC='\033[0m' # No Color

echo -e "${YELLOW}=== Jormungandr Bootstrap Build ===${NC}"
echo ""

# Create build directories
mkdir -p "$OUT_DIR"

# Module compilation order (dependencies first)
MODULES=(
    "span"
    "token"
    "ast"
    "lib"
    "lexer"
    "parser"
    "typeck"
    "ir"
    "lower"
    "interp"
    "runtime"
    "codegen"
    "driver"
)

# Step 1: Compile each module to C using the Rust interpreter
echo -e "${YELLOW}Step 1: Compiling Sigil modules to C...${NC}"
cd "$PARSER_DIR"

for module in "${MODULES[@]}"; do
    echo -n "  Compiling $module.sg... "
    if cargo run --release -- run-dir ../self-hosted/src -- compile "$SRC_DIR/$module.sg" 2>/dev/null > "$OUT_DIR/$module.c"; then
        echo -e "${GREEN}OK${NC}"
    else
        echo -e "${RED}FAILED${NC}"
        exit 1
    fi
done

echo ""
echo -e "${YELLOW}Step 2: Creating unified source...${NC}"

# Create a unified C file that includes all modules
export UNIFIED="$BUILD_DIR/sigil_bootstrap.c"
cat > "$UNIFIED" << 'HEADER'
/* Sigil Bootstrap Compiler - Unified Build
 * Generated by Jormungandr Build System
 *
 * This file combines all self-hosted compiler modules into a single
 * compilation unit for GCC.
 */

/* Suppress duplicate definition warnings */
#define SIGIL_UNIFIED_BUILD 1

/* Include stddef.h for offsetof used by array header */
#include <stddef.h>

/* Forward declaration of sigil_arr_len (defined in runtime below) */
/* Note: Don't define SIGIL_ARR_LEN_DEFINED here - let the first definition win */
struct SigilValue;
typedef struct SigilValue SigilValue;
size_t sigil_arr_len(SigilValue v);

#ifndef SIGIL_ARRAY_HEADER_DEFINED
#define SIGIL_ARRAY_HEADER_DEFINED
/* Array header for shared length tracking
 * The header is placed at the beginning of the allocation, followed by the data.
 * Layout: [SigilArrayHeader][SigilValue data[0]][SigilValue data[1]]...
 */
typedef struct SigilArrayHeader {
    size_t len;
    size_t cap;
    /* data follows immediately after this struct */
} SigilArrayHeader;

/* Get header from array data pointer - data is right after the header */
#define SIGIL_ARRAY_DATA_OFFSET (sizeof(SigilArrayHeader))
static inline SigilArrayHeader* sigil_get_array_header(void* arr_data) {
    return (SigilArrayHeader*)((char*)arr_data - SIGIL_ARRAY_DATA_OFFSET);
}
/* Get data pointer from header */
static inline void* sigil_array_data(SigilArrayHeader* h) {
    return (void*)((char*)h + SIGIL_ARRAY_DATA_OFFSET);
}
#endif /* SIGIL_ARRAY_HEADER_DEFINED */

/* Result type helpers - tags for sigil_Ok/Err */
/* NOTE: These must NOT conflict with TAG_ENUM (14) from the runtime */
#define TAG_RESULT_OK 17
#define TAG_RESULT_ERR 18

HEADER

# Include each module
for module in "${MODULES[@]}"; do
    echo "/* === Module: $module === */" >> "$UNIFIED"
    echo "" >> "$UNIFIED"
    # Skip the common headers after the first module
    if [ "$module" != "span" ]; then
        # Remove duplicate header includes
        sed -e '/^#include <std/d' \
            -e '/^\/\* Generated by Sigil/d' \
            -e '/^\/\* Jormungandr Bootstrap/d' \
            -e '/^#define SIGIL_KNOWN/d' \
            -e '/^#define SIGIL_UNCERTAIN/d' \
            -e '/^#define SIGIL_REPORTED/d' \
            -e '/^#define SIGIL_PARADOX/d' \
            -e '/^#define TAG_/d' \
            -e '/^typedef struct SigilValue/,/^} SigilValue;/d' \
            -e '/^static inline SigilValue sigil_unit/,/^}/d' \
            -e '/^static inline SigilValue sigil_bool/,/^}/d' \
            -e '/^static inline SigilValue sigil_int/,/^}/d' \
            -e '/^static inline SigilValue sigil_float/,/^}/d' \
            -e '/^static inline SigilValue sigil_char/,/^}/d' \
            -e '/^static inline SigilValue sigil_string/,/^}/d' \
            "$OUT_DIR/$module.c" >> "$UNIFIED"
    else
        cat "$OUT_DIR/$module.c" >> "$UNIFIED"
        # Add Result helpers after span.c (which has the builtins)
        cat >> "$UNIFIED" << 'RESULT_HELPERS'

/* Wildcard placeholder - used in pattern matching */
static const SigilValue _ = { .tag = TAG_UNIT, .evidence = SIGIL_KNOWN };

/* Result type helpers - sigil_Ok and sigil_Err */
static inline SigilValue sigil_Ok(SigilValue v) {
    SigilValue* inner = (SigilValue*)malloc(sizeof(SigilValue));
    *inner = v;
    return (SigilValue){ .tag = TAG_RESULT_OK, .evidence = SIGIL_KNOWN, .v.ptr = inner };
}

static inline SigilValue sigil_Err(SigilValue v) {
    SigilValue* inner = (SigilValue*)malloc(sizeof(SigilValue));
    *inner = v;
    return (SigilValue){ .tag = TAG_RESULT_ERR, .evidence = SIGIL_KNOWN, .v.ptr = inner };
}

SigilValue sigil_Result____Ok(SigilValue v) { return sigil_Ok(v); }
SigilValue sigil_Result____Err(SigilValue v) { return sigil_Err(v); }

/* Result::ok - extract inner value from Result::Ok (accessor method, lowercase) */
SigilValue sigil_Result____ok(SigilValue v) {
    if (v.tag == TAG_RESULT_OK && v.v.ptr != NULL) {
        return *(SigilValue*)v.v.ptr;
    }
    return sigil_null();
}

static inline bool sigil_is_ok(SigilValue v) {
    return v.tag == TAG_RESULT_OK;
}

static inline bool sigil_is_err(SigilValue v) {
    return v.tag == TAG_RESULT_ERR;
}

static inline SigilValue sigil_unwrap_result(SigilValue v) {
    if (v.tag == TAG_RESULT_OK || v.tag == TAG_RESULT_ERR) {
        if (v.v.ptr != NULL) {
            return *(SigilValue*)v.v.ptr;
        }
        return sigil_unit();
    }
    return v;
}

/* Extract data from enum variant - handles both TAG_ENUM and Result types.
 * Result types use .v.ptr, regular enums use .v.e.data[0]
 */
static inline SigilValue sigil_enum_data(SigilValue v) {
    /* Handle Result types - they store inner value in .v.ptr */
    if (v.tag == TAG_RESULT_OK || v.tag == TAG_RESULT_ERR) {
        return sigil_unwrap_result(v);
    }
    /* Handle regular enum variants - they use .v.e.data array */
    if (v.tag == TAG_ENUM && v.v.e.field_count > 0 && v.v.e.data != NULL) {
        return v.v.e.data[0];
    }
    /* For non-enum or invalid enum, return as-is */
    return v;
}

/* char::from_u32 - Convert u32 to char, returns Result<char, Error> */
static inline SigilValue sigil_char____from_u32(SigilValue codepoint) {
    if (codepoint.tag != TAG_INT) {
        return sigil_Err(sigil_string("invalid codepoint type"));
    }
    int64_t cp = codepoint.v.i;
    /* Valid Unicode codepoints: 0x0000-0xD7FF and 0xE000-0x10FFFF */
    if (cp >= 0 && (cp <= 0xD7FF || (cp >= 0xE000 && cp <= 0x10FFFF))) {
        return sigil_Ok(sigil_char((char)cp));
    }
    return sigil_Err(sigil_string("invalid Unicode codepoint"));
}

/* map_err - Transform error value in Result */
static inline SigilValue sigil_map_err(SigilValue result, SigilValue closure) {
    if (result.tag == TAG_RESULT_ERR) {
        SigilValue err = *(SigilValue*)result.v.ptr;
        /* Apply closure to error - closure is a function pointer */
        typedef SigilValue (*ClosureFn)(SigilValue);
        ClosureFn fn = (ClosureFn)closure.v.ptr;
        SigilValue new_err = fn(err);
        return sigil_Err(new_err);
    }
    return result;
}

/* Iterator helpers - stubs for pipe operations */
#define SIGIL_ITER_DEFINED  /* Prevent codegen.sg from redefining these */
#define SIGIL_JOIN_DEFINED  /* Prevent codegen.sg from redefining sigil_join */
static inline SigilValue sigil_collect(SigilValue v) { return v; }
static inline SigilValue sigil_iter(SigilValue v) { return v; }
/* sigil_enumerate - wrap each element in (index, value) tuple */
static inline SigilValue sigil_enumerate(SigilValue v) {
    if (v.tag != TAG_ARRAY) return sigil_array(0);
    SigilValue result = sigil_array(v.v.arr.len);
    for (size_t i = 0; i < v.v.arr.len; i++) {
        /* Create a tuple of (index, element) */
        SigilValue* fields = (SigilValue*)malloc(2 * sizeof(SigilValue));
        fields[0] = sigil_int((long long)i);
        fields[1] = v.v.arr.data[i];
        result.v.arr.data[i] = (SigilValue){
            .tag = TAG_TUPLE,
            .evidence = SIGIL_KNOWN,
            .v.tup = { .fields = fields, .count = 2 }
        };
    }
    return result;
}
/* sigil_cloned - deep clone a value, especially for structs */
static inline SigilValue sigil_cloned(SigilValue v) {
    if (v.tag == TAG_STRUCT && v.v.ptr != NULL) {
        SigilStruct* src = (SigilStruct*)v.v.ptr;
        SigilStruct* dst = (SigilStruct*)malloc(sizeof(SigilStruct));
        dst->name = src->name ? strdup(src->name) : NULL;
        dst->num_fields = src->num_fields;
        dst->field_names = (char**)malloc(src->num_fields * sizeof(char*));
        dst->field_values = (SigilValue*)malloc(src->num_fields * sizeof(SigilValue));
        for (size_t i = 0; i < src->num_fields; i++) {
            dst->field_names[i] = src->field_names[i] ? strdup(src->field_names[i]) : NULL;
            dst->field_values[i] = sigil_cloned(src->field_values[i]); /* recursive clone */
        }
        return (SigilValue){ .tag = TAG_STRUCT, .evidence = v.evidence, .v.ptr = dst };
    }
    return v; /* For non-structs, return as-is (primitives are value types) */
}
/* sigil_clone is now generated by codegen.sg, not defined here */
/* sigil_all - check if all elements satisfy predicate */
static inline SigilValue sigil_all(SigilValue arr, SigilValue closure) {
    if (arr.tag != TAG_ARRAY) return sigil_bool(true);
    typedef SigilValue (*ClosureFn)(SigilValue);
    ClosureFn fn = (ClosureFn)closure.v.ptr;
    for (size_t i = 0; i < arr.v.arr.len; i++) {
        SigilValue result = fn(arr.v.arr.data[i]);
        if (!sigil_truthy(result)) return sigil_bool(false);
    }
    return sigil_bool(true);
}
/* sigil_any - check if any element satisfies predicate */
static inline SigilValue sigil_any(SigilValue arr, SigilValue closure) {
    if (arr.tag != TAG_ARRAY) return sigil_bool(false);
    typedef SigilValue (*ClosureFn)(SigilValue);
    ClosureFn fn = (ClosureFn)closure.v.ptr;
    for (size_t i = 0; i < arr.v.arr.len; i++) {
        SigilValue result = fn(arr.v.arr.data[i]);
        if (sigil_truthy(result)) return sigil_bool(true);
    }
    return sigil_bool(false);
}
static inline SigilValue sigil_skip(SigilValue v, SigilValue n) { return v; }
static inline SigilValue sigil_nth(SigilValue v, SigilValue n) {
    if (v.tag == TAG_ARRAY && n.v.i < v.v.arr.len) {
        return v.v.arr.data[n.v.i];
    }
    return sigil_null();
}
static inline SigilValue sigil_next(SigilValue v) { return sigil_nth(v, sigil_int(0)); }
#ifndef SIGIL_JOIN_DEFINED
static inline SigilValue sigil_join(SigilValue v, SigilValue sep) { return sigil_string(""); }
#endif
static inline SigilValue sigil_collect_results(SigilValue v) { return sigil_Ok(v); }

/* Zip iterator - sigil__122ip (122 = 'z' ASCII, ip = "ip" from "zip") */
static inline SigilValue sigil__122ip(SigilValue a, SigilValue b) {
    if (a.tag != TAG_ARRAY || b.tag != TAG_ARRAY) return sigil_array(0);
    size_t len = a.v.arr.len < b.v.arr.len ? a.v.arr.len : b.v.arr.len;
    SigilValue result = sigil_array(len);
    for (size_t i = 0; i < len; i++) {
        /* Create a tuple of (a[i], b[i]) */
        SigilValue* fields = (SigilValue*)malloc(2 * sizeof(SigilValue));
        fields[0] = a.v.arr.data[i];
        fields[1] = b.v.arr.data[i];
        result.v.arr.data[i] = (SigilValue){
            .tag = TAG_TUPLE,
            .evidence = SIGIL_KNOWN,
            .v.tup = { .fields = fields, .count = 2 }
        };
    }
    return result;
}

/* Also add sigil_zip as an alias */
static inline SigilValue sigil_zip(SigilValue a, SigilValue b) { return sigil__122ip(a, b); }

/* Additional method stubs */
static inline SigilValue sigil_is_truthy(SigilValue v) { return sigil_bool(sigil_truthy(v)); }
static inline SigilValue sigil_is_uppercase(SigilValue c) {
    return sigil_bool(c.tag == TAG_CHAR && c.v.c >= 'A' && c.v.c <= 'Z');
}
static inline SigilValue sigil_powf(SigilValue base, SigilValue exp) { return sigil_pow(base, exp); }
static inline SigilValue sigil_set(SigilValue arr, SigilValue idx, SigilValue val) {
    if (arr.tag == TAG_ARRAY && idx.v.i < arr.v.arr.len) {
        arr.v.arr.data[idx.v.i] = val;
    }
    return sigil_unit();
}
static inline SigilValue sigil_name(SigilValue v) { return sigil_string(""); }
static inline SigilValue sigil_tuple_field(SigilValue v, int idx) {
    if (v.tag == TAG_TUPLE && idx < v.v.tup.count) {
        return v.v.tup.fields[idx];
    }
    return sigil_null();
}
static inline SigilValue sigil_ok(SigilValue v) { return sigil_Ok(v); }
static inline SigilValue sigil_b(SigilValue v) { return v; }
static inline SigilValue sigil_evidentiality(SigilValue v) { return sigil_int(v.evidence); }
static inline SigilValue sigil_to_json(SigilValue v, SigilValue opts) { (void)opts; return sigil_display(v); }
static inline SigilValue sigil_kind_name(SigilValue v) {
    switch (v.tag) {
        case TAG_UNIT: return sigil_string("unit");
        case TAG_BOOL: return sigil_string("bool");
        case TAG_INT: return sigil_string("int");
        case TAG_FLOAT: return sigil_string("float");
        case TAG_CHAR: return sigil_string("char");
        case TAG_STRING: return sigil_string("string");
        case TAG_ARRAY: return sigil_string("array");
        case TAG_TUPLE: return sigil_string("tuple");
        case TAG_STRUCT: return sigil_string("struct");
        case TAG_NULL: return sigil_string("null");
        case TAG_RESULT_OK: return sigil_string("Ok");
        case TAG_RESULT_ERR: return sigil_string("Err");
        default: return sigil_string("unknown");
    }
}
static inline SigilValue sigil_rank(SigilValue v) { return sigil_int(v.evidence); }
static inline SigilValue sigil_with_file(SigilValue e, SigilValue f) { return e; }
static inline SigilValue sigil_with_span(SigilValue e, SigilValue s) { return e; }
static inline SigilValue sigil_with_note(SigilValue e, SigilValue n) { return e; }

/* String method stubs - NOT static because codegen.sg generates forward declarations */
SigilValue sigil_String____is_empty(SigilValue s) {
    return sigil_bool(s.tag != TAG_STRING || s.v.s == NULL || s.v.s[0] == '\0');
}
SigilValue sigil_String____len(SigilValue s) {
    return s.tag == TAG_STRING && s.v.s ? sigil_int(strlen(s.v.s)) : sigil_int(0);
}
SigilValue sigil_String____from(SigilValue v) { return sigil_display(v); }
SigilValue sigil_String____starts_with(SigilValue s, SigilValue prefix) {
    if (s.tag != TAG_STRING || prefix.tag != TAG_STRING) return sigil_bool(false);
    return sigil_bool(strncmp(s.v.s, prefix.v.s, strlen(prefix.v.s)) == 0);
}
SigilValue sigil_String____ends_with(SigilValue s, SigilValue suffix) {
    if (s.tag != TAG_STRING || suffix.tag != TAG_STRING) return sigil_bool(false);
    size_t slen = strlen(s.v.s);
    size_t suflen = strlen(suffix.v.s);
    if (suflen > slen) return sigil_bool(false);
    return sigil_bool(strcmp(s.v.s + slen - suflen, suffix.v.s) == 0);
}
SigilValue sigil_String____chars(SigilValue s) {
    if (s.tag != TAG_STRING || !s.v.s) return sigil_array(0);
    size_t len = strlen(s.v.s);
    SigilValue arr = sigil_array(len);
    for (size_t i = 0; i < len; i++) {
        arr.v.arr.data[i] = sigil_char(s.v.s[i]);
    }
    return arr;
}
SigilValue sigil_String____contains(SigilValue s, SigilValue sub) {
    if (s.tag != TAG_STRING || sub.tag != TAG_STRING) return sigil_bool(false);
    return sigil_bool(strstr(s.v.s, sub.v.s) != NULL);
}
SigilValue sigil_String____split(SigilValue s, SigilValue delim) {
    if (s.tag != TAG_STRING || !s.v.s || delim.tag != TAG_STRING || !delim.v.s) {
        SigilValue result = sigil_array(1);
        result.v.arr.data[0] = s;
        return result;
    }

    const char* str = s.v.s;
    const char* sep = delim.v.s;
    size_t sep_len = strlen(sep);

    if (sep_len == 0) {
        /* Empty delimiter: return single element */
        SigilValue result = sigil_array(1);
        result.v.arr.data[0] = s;
        return result;
    }

    /* Count occurrences first */
    size_t count = 1;
    const char* p = str;
    while ((p = strstr(p, sep)) != NULL) {
        count++;
        p += sep_len;
    }

    /* Allocate result array */
    SigilValue result = sigil_array(count);

    /* Split the string */
    p = str;
    size_t i = 0;
    const char* next;
    while ((next = strstr(p, sep)) != NULL && i < count - 1) {
        size_t part_len = next - p;
        char* part = (char*)malloc(part_len + 1);
        memcpy(part, p, part_len);
        part[part_len] = '\0';
        result.v.arr.data[i++] = sigil_string(part);
        free(part);
        p = next + sep_len;
    }
    /* Last part */
    result.v.arr.data[i] = sigil_string(p);

    return result;
}

/* Map methods - implemented with __entries array */
/* Helper to safely get array length, handling both header and plain arrays */
static inline size_t sigil_map_entries_len(SigilValue entries) {
    if (entries.tag != TAG_ARRAY || !entries.v.arr.data) return 0;
    /* Try header approach first, fall back to direct len */
    SigilArrayHeader* header = sigil_get_array_header(entries.v.arr.data);
    /* Sanity check: cap should be >= len and both should be reasonable */
    if (header && header->cap >= header->len && header->cap < 100000000) {
        return header->len;
    }
    /* Fall back to direct len field */
    return entries.v.arr.len;
}

SigilValue sigil_Map____get(SigilValue m, SigilValue key) {
    if (m.tag != TAG_STRUCT) {
        return sigil_null();
    }
    SigilValue entries = sigil_struct_field(m, "__entries");
    if (entries.tag != TAG_ARRAY) {
        return sigil_null();
    }
    if (!entries.v.arr.data) {
        return sigil_null();
    }

    size_t len = sigil_map_entries_len(entries);
    SigilValue* data = entries.v.arr.data;

    for (size_t i = 0; i < len; i++) {
        SigilValue entry = data[i];
        // Entry is a tuple (key, value)
        if (entry.tag == TAG_TUPLE && entry.v.tup.count >= 2) {
            if (sigil_eq(entry.v.tup.fields[0], key)) {
                return entry.v.tup.fields[1];
            }
        }
        // Entry could also be a struct with "0" and "1" fields
        if (entry.tag == TAG_STRUCT) {
            SigilValue entry_key = sigil_struct_field(entry, "0");
            if (sigil_eq(entry_key, key)) {
                return sigil_struct_field(entry, "1");
            }
        }
    }
    return sigil_null();
}
SigilValue sigil_Map____contains_key(SigilValue m, SigilValue key) {
    SigilValue result = sigil_Map____get(m, key);
    return sigil_bool(result.tag != TAG_NULL);
}
SigilValue sigil_Map____insert(SigilValue m, SigilValue key, SigilValue value) {
    if (m.tag != TAG_STRUCT) return sigil_unit();
    SigilValue entries = sigil_struct_field(m, "__entries");
    if (entries.tag != TAG_ARRAY || !entries.v.arr.data) return sigil_unit();

    SigilArrayHeader* header = sigil_get_array_header(entries.v.arr.data);
    /* Sanity check for header validity */
    if (!header || header->cap < header->len || header->cap >= 100000000) {
        /* Fallback: array wasn't created with header format - just return */
        return sigil_unit();
    }
    size_t len = header->len;

    // Check if key already exists - update in place
    SigilValue* data = entries.v.arr.data;
    for (size_t i = 0; i < len; i++) {
        SigilValue entry = data[i];
        if (entry.tag == TAG_TUPLE && entry.v.tup.count >= 2) {
            if (sigil_eq(entry.v.tup.fields[0], key)) {
                entry.v.tup.fields[1] = value;
                data[i] = entry;
                return sigil_unit();
            }
        }
        if (entry.tag == TAG_STRUCT) {
            SigilValue entry_key = sigil_struct_field(entry, "0");
            if (sigil_eq(entry_key, key)) {
                sigil_struct_set_field(&entry, "1", value);
                data[i] = entry;
                return sigil_unit();
            }
        }
    }

    // Key not found - add new entry using Vec::push pattern
    if (len >= header->cap) {
        size_t new_cap = header->cap == 0 ? 4 : header->cap * 2;
        SigilArrayHeader* new_header = (SigilArrayHeader*)realloc(header, SIGIL_ARRAY_DATA_OFFSET + new_cap * sizeof(SigilValue));
        if (!new_header) return sigil_unit();
        new_header->cap = new_cap;
        header = new_header;
        data = (SigilValue*)sigil_array_data(header);

        // CRITICAL: Update the entries array in the Map struct to point to new memory!
        entries.v.arr.data = data;
        entries.v.arr.len = len;  // Will be incremented below
        sigil_struct_set_field(&m, "__entries", entries);
    }

    // Create new entry tuple
    SigilValue* fields = (SigilValue*)malloc(2 * sizeof(SigilValue));
    fields[0] = key;
    fields[1] = value;
    SigilValue new_entry = { .tag = TAG_TUPLE, .evidence = SIGIL_KNOWN };
    new_entry.v.tup.fields = fields;
    new_entry.v.tup.count = 2;

    data[len] = new_entry;
    header->len = len + 1;

    // Also update entries.v.arr.len and store back
    entries.v.arr.len = len + 1;
    sigil_struct_set_field(&m, "__entries", entries);

    return sigil_unit();
}
SigilValue sigil_Map____entries(SigilValue m) {
    if (m.tag != TAG_STRUCT) return sigil_array(0);
    return sigil_struct_field(m, "__entries");
}

/* Option method stubs */
static inline SigilValue sigil_Option____unwrap(SigilValue opt) {
    if (opt.tag == TAG_VARIANT && opt.v.ptr) {
        return *(SigilValue*)opt.v.ptr;
    }
    return opt;
}
static inline SigilValue sigil_Option____is_some(SigilValue opt) {
    return sigil_bool(opt.tag != TAG_NULL);
}
static inline SigilValue sigil_Option____is_none(SigilValue opt) {
    return sigil_bool(opt.tag == TAG_NULL);
}

/* Parser methods - forward declarations only (implementations in parser.sg) */
SigilValue sigil_Parser____new(SigilValue source);
SigilValue sigil_Parser____parse_file(SigilValue* self);

/* Forward declarations for functions called before they're defined */
SigilValue sigil_Interpreter____register_builtins(SigilValue* self);
