/* Vec/Array - SigilArrayHeader is defined in the header section above */

/* Helper to create an array with header */
static inline SigilValue sigil_array_with_header(size_t initial_cap) {
    if (initial_cap < 4) initial_cap = 4;
    SigilArrayHeader* header = (SigilArrayHeader*)malloc(SIGIL_ARRAY_DATA_OFFSET + initial_cap * sizeof(SigilValue));
    header->len = 0;
    header->cap = initial_cap;
    SigilValue* data_ptr = (SigilValue*)sigil_array_data(header);
    return (SigilValue){
        .tag = TAG_ARRAY,
        .evidence = SIGIL_KNOWN,
        .v.arr = { data_ptr, 0, initial_cap }  /* For compatibility with old code */
    };
}

/* Get real array length from header (if available) */
/* Note: SIGIL_ARR_LEN_DEFINED is defined early in the header to suppress codegen's simple version */
size_t sigil_arr_len(SigilValue v) {
    if (v.tag == TAG_ARRAY && v.v.arr.data) {
        SigilArrayHeader* header = sigil_get_array_header(v.v.arr.data);
        return header->len;
    }
    return v.v.arr.len;  /* fallback */
}

/* Vec method stubs - using shared header for proper mutation */
SigilValue sigil_Vec____new(void) { return sigil_array_with_header(4); }
#ifndef SIGIL_VEC_PUSH_DEFINED
#define SIGIL_VEC_PUSH_DEFINED
SigilValue sigil_Vec____push(SigilValue v, SigilValue item) {
    if (v.tag == TAG_ARRAY && v.v.arr.data) {
        SigilArrayHeader* header = sigil_get_array_header(v.v.arr.data);
        /* Safety check: skip push if header looks invalid (array not created with header format) */
        if (header->cap == 0 || header->cap > 1000000 || header->len > header->cap) {
            return v;  /* Return unchanged to avoid crash on non-header arrays */
        }
        if (header->len >= header->cap) {
            size_t new_cap = header->cap == 0 ? 4 : header->cap * 2;
            SigilArrayHeader* new_header = (SigilArrayHeader*)realloc(header, SIGIL_ARRAY_DATA_OFFSET + new_cap * sizeof(SigilValue));
            new_header->cap = new_cap;
            header = new_header;
            /* Update the data pointer in v to reflect reallocation */
            v.v.arr.data = (SigilValue*)sigil_array_data(header);
            v.v.arr.cap = new_cap;
        }
        ((SigilValue*)sigil_array_data(header))[header->len++] = item;
        /* Update local copy's len for compatibility */
        v.v.arr.len = header->len;
    }
    return v;  /* Return modified array */
}
#endif /* SIGIL_VEC_PUSH_DEFINED */

/* In-place push that modifies through pointer - no return value needed */
void sigil_Vec____push_inplace(SigilValue* v, SigilValue item) {
    if (v->tag == TAG_ARRAY && v->v.arr.data) {
        SigilArrayHeader* header = sigil_get_array_header(v->v.arr.data);
        if (header->len >= header->cap) {
            size_t new_cap = header->cap == 0 ? 4 : header->cap * 2;
            SigilArrayHeader* new_header = (SigilArrayHeader*)realloc(header, SIGIL_ARRAY_DATA_OFFSET + new_cap * sizeof(SigilValue));
            new_header->cap = new_cap;
            header = new_header;
            /* Update the data pointer through the pointer to reflect reallocation */
            v->v.arr.data = (SigilValue*)sigil_array_data(header);
            v->v.arr.cap = new_cap;
        }
        ((SigilValue*)sigil_array_data(header))[header->len++] = item;
        /* Update len through pointer */
        v->v.arr.len = header->len;
    }
}

SigilValue sigil_Vec____pop(SigilValue v) {
    if (v.tag == TAG_ARRAY && v.v.arr.len > 0) {
        return v.v.arr.data[--v.v.arr.len];
    }
    return sigil_null();
}
static inline SigilValue sigil_Vec____first(SigilValue v) {
    if (v.tag == TAG_ARRAY && v.v.arr.len > 0) {
        return v.v.arr.data[0];
    }
    return sigil_null();
}
static inline SigilValue sigil_Vec____last(SigilValue v) {
    if (v.tag == TAG_ARRAY && v.v.arr.len > 0) {
        return v.v.arr.data[v.v.arr.len - 1];
    }
    return sigil_null();
}

/* TypeEnv define with 3 args (uses Known evidence by default) */
/* This is a workaround for interp.sg using a different signature */
#define sigil_TypeEnv____define_3(self, name, value) \
    sigil_Map____insert(sigil_struct_field(self, "bindings"), name, value)

/* Ambiguous method dispatch stubs */
/* sigil_define_4 - TypeEnv::define (4 args: env, name, ty, evidence) */
static inline SigilValue sigil_define_4(SigilValue env, SigilValue name, SigilValue ty, SigilValue evidence) {
    /* TypeEnv::define inserts into bindings map */
    if (name.tag == TAG_STRING && name.v.s) {
        fprintf(stderr, "[DEBUG define_4] name=%s, env.tag=%d\\n", name.v.s, env.tag);
    }
    SigilValue bindings = sigil_struct_field(env, "bindings");
    fprintf(stderr, "[DEBUG define_4] bindings.tag=%d\\n", bindings.tag);
    SigilValue* data = (SigilValue*)malloc(2 * sizeof(SigilValue));
    data[0] = ty;
    data[1] = evidence;
    SigilValue tuple = { .tag = TAG_TUPLE, .evidence = SIGIL_KNOWN };
    tuple.v.tup.fields = data;
    tuple.v.tup.count = 2;
    sigil_Map____insert(bindings, name, tuple);
    fprintf(stderr, "[DEBUG define_4] inserted\\n");
    return sigil_unit();
}

/* sigil_define_3 - Environment::define (3 args: env, name, value) */
static inline SigilValue sigil_define_3(SigilValue env, SigilValue name, SigilValue value) {
    /* Environment::define inserts into bindings map */
    SigilValue bindings = sigil_struct_field(env, "bindings");
    sigil_Map____insert(bindings, name, value);
    return sigil_unit();
}

/* sigil_contains - check if a collection contains an element */
#ifndef SIGIL_CONTAINS_DEFINED
#define SIGIL_CONTAINS_DEFINED
static inline SigilValue sigil_contains(SigilValue collection, SigilValue element) {
    /* Dereference TAG_REF for collection */
    while (collection.tag == TAG_REF && collection.v.ptr) {
        collection = *((SigilValue*)collection.v.ptr);
    }
    /* Dereference TAG_REF for element */
    while (element.tag == TAG_REF && element.v.ptr) {
        element = *((SigilValue*)element.v.ptr);
    }
    if (collection.tag == TAG_ARRAY) {
        for (size_t i = 0; i < collection.v.arr.len; i++) {
            SigilValue item = collection.v.arr.data[i];
            /* Also dereference array items if they are refs */
            while (item.tag == TAG_REF && item.v.ptr) {
                item = *((SigilValue*)item.v.ptr);
            }
            if (sigil_eq(item, element)) return sigil_bool(true);
        }
    } else if (collection.tag == TAG_STRUCT) {
        /* Map is a struct - check using Map get */
        SigilValue result = sigil_Map____get(collection, element);
        return sigil_bool(result.tag != TAG_NULL);
    }
    return sigil_bool(false);
}
#endif /* SIGIL_CONTAINS_DEFINED */

