/* Vec clear - returns unit */
static inline SigilValue sigil_Vec____clear(SigilValue v) {
    if (v.tag == TAG_ARRAY) {
        v.v.arr.len = 0;
    }
    return sigil_unit();
}

/* Vec extend - append all elements from other Vec */
static inline SigilValue sigil_Vec____extend(SigilValue v, SigilValue other) {
    if (v.tag != TAG_ARRAY || other.tag != TAG_ARRAY) return v;
    for (size_t i = 0; i < other.v.arr.len; i++) {
        v = sigil_Vec____push(v, other.v.arr.data[i]);
    }
    return v;
}

/* Error reporting function - takes ctx and error message */
static inline SigilValue sigil_error(SigilValue ctx, SigilValue err) {
    /* err is typically a LowerError or similar struct with a message field */
    SigilValue msg = sigil_struct_field(err, "message");
    if (msg.tag == TAG_STRING) {
        fprintf(stderr, "Error: %s\n", msg.v.s);
    } else if (err.tag == TAG_STRING) {
        fprintf(stderr, "Error: %s\n", err.v.s);
    } else {
        fprintf(stderr, "Error: (non-string error)\n");
    }
    return sigil_unit();
}

