/* String strip_prefix - returns Option<String> (the string or null) */
static inline SigilValue sigil_String____strip_prefix(SigilValue s, SigilValue prefix) {
    if (s.tag != TAG_STRING || prefix.tag != TAG_STRING) return sigil_null();
    size_t plen = strlen(prefix.v.s);
    if (strncmp(s.v.s, prefix.v.s, plen) == 0) {
        return sigil_string(s.v.s + plen);
    }
    return sigil_null();
}

/* Hex format for char - used in name mangling */
static inline SigilValue sigil_char_hex(SigilValue c) {
    char buf[32];
    if (c.tag == TAG_CHAR) {
        snprintf(buf, sizeof(buf), "_%02x", (unsigned char)c.v.c);
    } else if (c.tag == TAG_INT) {
        snprintf(buf, sizeof(buf), "_%02x", (unsigned int)(c.v.i & 0xFF));
    } else {
        snprintf(buf, sizeof(buf), "_00");
    }
    return sigil_string(strdup(buf));
}

/* Dynamic string builder - header stored before the data pointer
 * Layout: [len: size_t][cap: size_t][data: char*]
 * The SigilValue.v.s points to the data portion
 */
typedef struct {
    size_t len;
    size_t cap;
    char data[];  /* Flexible array member */
} SigilStringBuilder;

#define SB_INITIAL_CAP 256
#define SB_HEADER_SIZE (sizeof(size_t) * 2)

/* Get builder header from string pointer */
static inline SigilStringBuilder* get_builder(char* s) {
    return (SigilStringBuilder*)((char*)s - SB_HEADER_SIZE);
}

/* Check if a string is a SigilStringBuilder based on allocation pattern */
/* We use a magic marker approach: valid builders have cap > 0 */
static inline bool is_string_builder(char* s) {
    if (!s) return false;
    SigilStringBuilder* sb = get_builder(s);
    /* Heuristic: cap must be reasonable and len <= cap */
    return (sb->cap >= SB_INITIAL_CAP && sb->cap <= 1024*1024*100 && sb->len <= sb->cap);
}

SigilValue sigil_String____new(void) {
    SigilStringBuilder* sb = (SigilStringBuilder*)malloc(SB_HEADER_SIZE + SB_INITIAL_CAP);
    sb->len = 0;
    sb->cap = SB_INITIAL_CAP;
    sb->data[0] = '\0';
    return (SigilValue){ .tag = TAG_STRING, .evidence = SIGIL_KNOWN, .v.s = sb->data };
}

/* Grow builder if needed, returns potentially new pointer */
static inline SigilStringBuilder* ensure_capacity(SigilStringBuilder* sb, size_t needed) {
    if (sb->len + needed < sb->cap) return sb;

    size_t new_cap = sb->cap * 2;
    while (sb->len + needed >= new_cap) new_cap *= 2;

    SigilStringBuilder* new_sb = (SigilStringBuilder*)realloc(sb, SB_HEADER_SIZE + new_cap);
    new_sb->cap = new_cap;
    return new_sb;
}

SigilValue sigil_String____push(SigilValue s, SigilValue c) {
    if (s.tag != TAG_STRING || !s.v.s) return s;

    char ch = '?';
    if (c.tag == TAG_CHAR) ch = c.v.c;
    else if (c.tag == TAG_INT) ch = (char)c.v.i;

    if (is_string_builder(s.v.s)) {
        /* It's a string builder, modify in place (may reallocate) */
        SigilStringBuilder* sb = get_builder(s.v.s);
        sb = ensure_capacity(sb, 1);
        sb->data[sb->len++] = ch;
        sb->data[sb->len] = '\0';
        s.v.s = sb->data;
    } else {
        /* It's a regular string literal - create new builder with content */
        size_t len = strlen(s.v.s);
        size_t new_cap = (len + 2 < SB_INITIAL_CAP) ? SB_INITIAL_CAP : (len + 2) * 2;
        SigilStringBuilder* sb = (SigilStringBuilder*)malloc(SB_HEADER_SIZE + new_cap);
        sb->len = len + 1;
        sb->cap = new_cap;
        memcpy(sb->data, s.v.s, len);
        sb->data[len] = ch;
        sb->data[len + 1] = '\0';
        s.v.s = sb->data;
    }
    return s;
}

SigilValue sigil_String____push_str(SigilValue s, SigilValue other) {
    if (s.tag != TAG_STRING || other.tag != TAG_STRING || !other.v.s) return s;
    size_t len2 = strlen(other.v.s);
    if (len2 == 0) return s;

    if (is_string_builder(s.v.s)) {
        SigilStringBuilder* sb = get_builder(s.v.s);
        sb = ensure_capacity(sb, len2);
        memcpy(sb->data + sb->len, other.v.s, len2);
        sb->len += len2;
        sb->data[sb->len] = '\0';
        s.v.s = sb->data;
    } else if (s.v.s) {
        size_t len1 = strlen(s.v.s);
        size_t new_cap = (len1 + len2 + 1 < SB_INITIAL_CAP) ? SB_INITIAL_CAP : (len1 + len2 + 1) * 2;
        SigilStringBuilder* sb = (SigilStringBuilder*)malloc(SB_HEADER_SIZE + new_cap);
        sb->len = len1 + len2;
        sb->cap = new_cap;
        memcpy(sb->data, s.v.s, len1);
        memcpy(sb->data + len1, other.v.s, len2);
        sb->data[sb->len] = '\0';
        s.v.s = sb->data;
    }
    return s;
}

SigilValue sigil_String____as_str(SigilValue s) {
    return s; /* String is already a string */
}

/* Create String from raw parts - for FFI */
SigilValue sigil_String____from_raw_parts(SigilValue ptr, SigilValue len, SigilValue cap) {
    if (ptr.tag != TAG_REF || ptr.v.ptr == NULL) {
        return sigil_null();
    }
    /* Create a copy of the data (to own it) */
    size_t length = (size_t)len.v.i;
    char* data = (char*)malloc(length + 1);
    if (data == NULL) return sigil_null();
    memcpy(data, ptr.v.ptr, length);
    data[length] = '\0';
    return sigil_string(data);
}

