/* Runtime utility functions */
SigilValue sigil_as_mut_ptr(SigilValue v) { return v; }
SigilValue sigil_add(SigilValue a, SigilValue b) {
    if (a.tag == TAG_INT && b.tag == TAG_INT) return sigil_int(a.v.i + b.v.i);
    if (a.tag == TAG_FLOAT || b.tag == TAG_FLOAT) {
        double fa = (a.tag == TAG_INT) ? (double)a.v.i : a.v.f;
        double fb = (b.tag == TAG_INT) ? (double)b.v.i : b.v.f;
        return sigil_float(fa + fb);
    }
    return sigil_int(0);
}
SigilValue sigil_max(SigilValue a, SigilValue b) {
    int64_t va = (a.tag == TAG_INT) ? a.v.i : (int64_t)a.v.f;
    int64_t vb = (b.tag == TAG_INT) ? b.v.i : (int64_t)b.v.f;
    return sigil_int(va > vb ? va : vb);
}
SigilValue sigil_Vec____with_capacity(SigilValue cap) {
    size_t c = (cap.tag == TAG_INT) ? (size_t)cap.v.i : 16;
    SigilValue arr;
    arr.tag = TAG_ARRAY;
    arr.evidence = SIGIL_KNOWN;
    arr.v.arr.data = (SigilValue*)calloc(c, sizeof(SigilValue));
    arr.v.arr.len = 0;
    arr.v.arr.cap = c;
    return arr;
}
SigilValue sigil_Vec____len(SigilValue v) {
    if (v.tag == TAG_ARRAY) return sigil_int((int64_t)v.v.arr.len);
    return sigil_int(0);
}
SigilValue sigil_Box____new(SigilValue v) {
    SigilValue* ptr = (SigilValue*)malloc(sizeof(SigilValue));
    *ptr = v;
    SigilValue box;
    /* Use TAG_REF for Box - TAG_STRUCT expects SigilStruct with field_names */
    box.tag = TAG_REF;
    box.evidence = SIGIL_KNOWN;
    box.v.ptr = ptr;
    return box;
}
SigilValue sigil_Box____into_raw(SigilValue box) {
    return sigil_int((int64_t)(uintptr_t)box.v.ptr);
}

/* Create Box from raw pointer - for FFI */
SigilValue sigil_Box____from_raw(SigilValue ptr) {
    /* Takes a raw pointer and wraps it in a Box (owned heap allocation) */
    if (ptr.tag == TAG_REF) {
        return (SigilValue){ .tag = TAG_REF, .evidence = SIGIL_KNOWN, .v.ptr = ptr.v.ptr };
    }
    if (ptr.tag == TAG_INT) {
        /* Integer interpreted as pointer address */
        return (SigilValue){ .tag = TAG_REF, .evidence = SIGIL_KNOWN, .v.ptr = (void*)(uintptr_t)ptr.v.i };
    }
    return sigil_null();
}

