SigilValue sigil_drop(SigilValue v) {
    /* For now, just return unit - actual memory cleanup happens via GC or RAII */
    /* In a full implementation, this would free heap-allocated memory */
    if (v.tag == TAG_REF && v.v.ptr != NULL) {
        /* Don't actually free - let the runtime handle it */
        /* free(v.v.ptr); */
    }
    return sigil_unit();
}

/* More runtime functions */
SigilValue sigil_len_utf8(SigilValue s) {
    /* Handle char - return UTF-8 byte length for this Unicode codepoint */
    if (s.tag == TAG_CHAR) {
        /* v.c now contains the full Unicode codepoint (int32_t), not a byte */
        int32_t codepoint = s.v.c;
        if (codepoint < 0x80) return sigil_int(1);          /* U+0000 to U+007F: 1 byte */
        else if (codepoint < 0x800) return sigil_int(2);    /* U+0080 to U+07FF: 2 bytes */
        else if (codepoint < 0x10000) return sigil_int(3);  /* U+0800 to U+FFFF: 3 bytes */
        else return sigil_int(4);                           /* U+10000 to U+10FFFF: 4 bytes */
    }
    if (s.tag != TAG_STRING) return sigil_int(0);
    /* For simplicity, just count bytes (not true UTF-8 codepoints) */
    return sigil_int((int64_t)strlen(s.v.s));
}

SigilValue sigil_char_at(SigilValue s, SigilValue idx) {
    if (s.tag != TAG_STRING) return sigil_null();
    size_t byte_pos = (idx.tag == TAG_INT) ? (size_t)idx.v.i : 0;
    size_t len = strlen(s.v.s);
    if (byte_pos >= len) return sigil_null();

    /* Decode UTF-8 to Unicode codepoint */
    unsigned char first = (unsigned char)s.v.s[byte_pos];
    uint32_t codepoint;

    if (first < 0x80) {
        /* ASCII (1 byte) */
        codepoint = first;
    } else if ((first & 0xE0) == 0xC0) {
        /* 2-byte sequence (110xxxxx 10xxxxxx) */
        if (byte_pos + 1 >= len) return sigil_null();
        unsigned char second = (unsigned char)s.v.s[byte_pos + 1];
        codepoint = ((first & 0x1F) << 6) | (second & 0x3F);
    } else if ((first & 0xF0) == 0xE0) {
        /* 3-byte sequence (1110xxxx 10xxxxxx 10xxxxxx) */
        if (byte_pos + 2 >= len) return sigil_null();
        unsigned char second = (unsigned char)s.v.s[byte_pos + 1];
        unsigned char third = (unsigned char)s.v.s[byte_pos + 2];
        codepoint = ((first & 0x0F) << 12) | ((second & 0x3F) << 6) | (third & 0x3F);
    } else if ((first & 0xF8) == 0xF0) {
        /* 4-byte sequence (11110xxx 10xxxxxx 10xxxxxx 10xxxxxx) */
        if (byte_pos + 3 >= len) return sigil_null();
        unsigned char second = (unsigned char)s.v.s[byte_pos + 1];
        unsigned char third = (unsigned char)s.v.s[byte_pos + 2];
        unsigned char fourth = (unsigned char)s.v.s[byte_pos + 3];
        codepoint = ((first & 0x07) << 18) | ((second & 0x3F) << 12) | ((third & 0x3F) << 6) | (fourth & 0x3F);
    } else {
        /* Invalid UTF-8 - return the byte as-is */
        codepoint = first;
    }

    return (SigilValue){ .tag = TAG_CHAR, .evidence = SIGIL_KNOWN, .v.c = (int32_t)codepoint };
}

/* Get raw pointer from string - for FFI */
/* Note: sigil_len is already defined in the generated code */
SigilValue sigil_as_ptr(SigilValue v) {
    if (v.tag == TAG_STRING) {
        return (SigilValue){ .tag = TAG_REF, .evidence = SIGIL_KNOWN, .v.ptr = (void*)v.v.s };
    }
    if (v.tag == TAG_ARRAY) {
        return (SigilValue){ .tag = TAG_REF, .evidence = SIGIL_KNOWN, .v.ptr = (void*)v.v.arr.data };
    }
    return sigil_null();
}

/* Check if pointer is null - for FFI */
SigilValue sigil_is_null(SigilValue v) {
    if (v.tag == TAG_REF) {
        return sigil_bool(v.v.ptr == NULL);
    }
    if (v.tag == TAG_NULL) {
        return sigil_bool(true);
    }
    return sigil_bool(false);
}

SigilValue sigil_is_vigesimal_digit(SigilValue c) {
    char ch = (c.tag == TAG_CHAR) ? c.v.c : (char)c.v.i;
    /* Base-20 digits: 0-9, a-j (or A-J) */
    if (ch >= '0' && ch <= '9') return sigil_bool(true);
    if ((ch >= 'a' && ch <= 'j') || (ch >= 'A' && ch <= 'J')) return sigil_bool(true);
    return sigil_bool(false);
}

SigilValue sigil_is_duodecimal_digit(SigilValue c) {
    char ch = (c.tag == TAG_CHAR) ? c.v.c : (char)c.v.i;
    /* Base-12 digits: 0-9, a-b (or A-B) */
    if (ch >= '0' && ch <= '9') return sigil_bool(true);
    if ((ch >= 'a' && ch <= 'b') || (ch >= 'A' && ch <= 'B')) return sigil_bool(true);
    return sigil_bool(false);
}

/* Lexer helper functions - fixed versions to replace broken codegen */
/* The Rust codegen produces "1" for character range patterns like '0'..='9' */
SigilValue sigil_Lexer____is_digit(SigilValue c) {
    if (c.tag != TAG_CHAR) return sigil_bool(false);
    char ch = c.v.c;
    return sigil_bool(ch >= '0' && ch <= '9');
}

SigilValue sigil_Lexer____is_digit_or_underscore(SigilValue c) {
    if (c.tag != TAG_CHAR) return sigil_bool(false);
    char ch = c.v.c;
    return sigil_bool((ch >= '0' && ch <= '9') || ch == '_');
}

SigilValue sigil_Lexer____is_hex_digit(SigilValue c) {
    if (c.tag != TAG_CHAR) return sigil_bool(false);
    char ch = c.v.c;
    return sigil_bool((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F'));
}

SigilValue sigil_Lexer____is_hex_or_underscore(SigilValue c) {
    if (c.tag != TAG_CHAR) return sigil_bool(false);
    char ch = c.v.c;
    return sigil_bool((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F') || ch == '_');
}

SigilValue sigil_Lexer____is_vigesimal_or_underscore(SigilValue c) {
    if (c.tag != TAG_CHAR) return sigil_bool(false);
    char ch = c.v.c;
    return sigil_bool((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'j') || (ch >= 'A' && ch <= 'J') || ch == '_');
}

SigilValue sigil_Lexer____is_alnum_or_underscore(SigilValue c) {
    if (c.tag != TAG_CHAR) return sigil_bool(false);
    char ch = c.v.c;
    return sigil_bool((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch == '_');
}

SigilValue sigil_Lexer____is_duodecimal_or_underscore(SigilValue c) {
    if (c.tag != TAG_CHAR) return sigil_bool(false);
    char ch = c.v.c;
    return sigil_bool((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'b') || (ch >= 'A' && ch <= 'B') || ch == '_');
}

SigilValue sigil_Lexer____is_alpha(SigilValue c) {
    if (c.tag != TAG_CHAR) return sigil_bool(false);
    char ch = c.v.c;
    return sigil_bool((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z'));
}

SigilValue sigil_Lexer____is_unicode_alnum_or_underscore(SigilValue c) {
    if (c.tag != TAG_CHAR) return sigil_bool(false);
    char ch = c.v.c;
    /* For bootstrap, just handle ASCII + basic check */
    return sigil_bool((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch == '_');
}

/* Parser::parse - stub that calls parse_file */
SigilValue sigil_Parser____parse(SigilValue self) {
    /* parse() just calls parse_file() */
    extern SigilValue sigil_Parser____parse_file(SigilValue* self);
    return sigil_Parser____parse_file(&self);
}

/* CG-128: Check if name is a C keyword */
static int sigil_is_c_keyword(const char* s) {
    /* C89 keywords */
    if (strcmp(s, "auto") == 0) return 1;
    if (strcmp(s, "break") == 0) return 1;
    if (strcmp(s, "case") == 0) return 1;
    if (strcmp(s, "char") == 0) return 1;
    if (strcmp(s, "const") == 0) return 1;
    if (strcmp(s, "continue") == 0) return 1;
    if (strcmp(s, "default") == 0) return 1;
    if (strcmp(s, "do") == 0) return 1;
    if (strcmp(s, "double") == 0) return 1;
    if (strcmp(s, "else") == 0) return 1;
    if (strcmp(s, "enum") == 0) return 1;
    if (strcmp(s, "extern") == 0) return 1;
    if (strcmp(s, "float") == 0) return 1;
    if (strcmp(s, "for") == 0) return 1;
    if (strcmp(s, "goto") == 0) return 1;
    if (strcmp(s, "if") == 0) return 1;
    if (strcmp(s, "int") == 0) return 1;
    if (strcmp(s, "long") == 0) return 1;
    if (strcmp(s, "register") == 0) return 1;
    if (strcmp(s, "return") == 0) return 1;
    if (strcmp(s, "short") == 0) return 1;
    if (strcmp(s, "signed") == 0) return 1;
    if (strcmp(s, "sizeof") == 0) return 1;
    if (strcmp(s, "static") == 0) return 1;
    if (strcmp(s, "struct") == 0) return 1;
    if (strcmp(s, "switch") == 0) return 1;
    if (strcmp(s, "typedef") == 0) return 1;
    if (strcmp(s, "union") == 0) return 1;
    if (strcmp(s, "unsigned") == 0) return 1;
    if (strcmp(s, "void") == 0) return 1;
    if (strcmp(s, "volatile") == 0) return 1;
    if (strcmp(s, "while") == 0) return 1;
    /* C99 keywords */
    if (strcmp(s, "inline") == 0) return 1;
    if (strcmp(s, "restrict") == 0) return 1;
    if (strcmp(s, "_Bool") == 0) return 1;
    if (strcmp(s, "_Complex") == 0) return 1;
    if (strcmp(s, "_Imaginary") == 0) return 1;
    return 0;
}

/* Name mangling for C codegen - called as method with self */
SigilValue sigil_mangle_name(SigilValue self, SigilValue name) {
    (void)self;
    if (name.tag != TAG_STRING) {
        fprintf(stderr, "[DEBUG mangle_name] name.tag=%d (expected TAG_STRING=%d)\\n", name.tag, TAG_STRING);
        return sigil_string("_unknown");
    }
    const char* src = name.v.s;
    size_t len = strlen(src);
    /* CG-128: Check if keyword and add sg_ prefix */
    int is_keyword = sigil_is_c_keyword(src);
    char* result = (char*)malloc(len * 4 + 4);  /* +4 for potential sg_ prefix */
    size_t j = 0;
    if (is_keyword) {
        result[j++] = 's'; result[j++] = 'g'; result[j++] = '_';
    }
    /* Replace :: with ____ and - with _ */
    for (size_t i = 0; i < len; i++) {
        if (src[i] == ':' && i+1 < len && src[i+1] == ':') {
            result[j++] = '_'; result[j++] = '_'; result[j++] = '_'; result[j++] = '_';
            i++; /* skip second : */
        } else if (src[i] == '-' || src[i] == ' ') {
            result[j++] = '_';
        } else {
            result[j++] = src[i];
        }
    }
    result[j] = '\0';
    return sigil_string(result);
}

/* Evidence to C string - called as method with self */
SigilValue sigil_evidence_to_c(SigilValue self, SigilValue ev) {
    (void)self;
    if (ev.tag == TAG_INT) {
        switch (ev.v.i) {
            case SIGIL_KNOWN: return sigil_string("SIGIL_KNOWN");
            case SIGIL_UNCERTAIN: return sigil_string("SIGIL_UNCERTAIN");
            case SIGIL_REPORTED: return sigil_string("SIGIL_REPORTED");
            case SIGIL_PARADOX: return sigil_string("SIGIL_PARADOX");
        }
    }
    return sigil_string("SIGIL_KNOWN");
}

/* Escape string for C output - called as method with self */
SigilValue sigil_escape_string(SigilValue self, SigilValue s) {
    (void)self;
    if (s.tag != TAG_STRING) return sigil_string("");
    const char* src = s.v.s;
    size_t len = strlen(src);
    char* result = (char*)malloc(len * 4 + 1);
    size_t j = 0;
    for (size_t i = 0; i < len; i++) {
        switch (src[i]) {
            case '\n': result[j++] = '\\'; result[j++] = 'n'; break;
            case '\r': result[j++] = '\\'; result[j++] = 'r'; break;
            case '\t': result[j++] = '\\'; result[j++] = 't'; break;
            case '\\': result[j++] = '\\'; result[j++] = '\\'; break;
            case '"':  result[j++] = '\\'; result[j++] = '"'; break;
            default: result[j++] = src[i]; break;
        }
    }
    result[j] = '\0';
    return sigil_string(result);
}

/* Escape char for C output - called as method with self */
SigilValue sigil_escape_char(SigilValue self, SigilValue c) {
    (void)self;
    char buf[8];
    char ch = (c.tag == TAG_CHAR) ? c.v.c : (c.tag == TAG_INT) ? (char)c.v.i : '?';
    switch (ch) {
        case '\n': snprintf(buf, sizeof(buf), "\\n"); break;
        case '\r': snprintf(buf, sizeof(buf), "\\r"); break;
        case '\t': snprintf(buf, sizeof(buf), "\\t"); break;
        case '\\': snprintf(buf, sizeof(buf), "\\\\"); break;
        case '\'': snprintf(buf, sizeof(buf), "\\'"); break;
        default: snprintf(buf, sizeof(buf), "%c", ch); break;
    }
    return sigil_string(strdup(buf));
}

/* Vec capacity - returns int */
static inline SigilValue sigil_Vec____capacity(SigilValue v) {
    if (v.tag == TAG_ARRAY) {
        return sigil_int((int64_t)v.v.arr.cap);
    }
    return sigil_int(0);
}

/* Vec join - join array of strings with separator */
static inline SigilValue sigil_Vec____join(SigilValue arr, SigilValue sep) {
    if (arr.tag != TAG_ARRAY || sep.tag != TAG_STRING) {
        return sigil_string("");
    }
    size_t total_len = 0;
    const char* sep_str = sep.v.s;
    size_t sep_len = strlen(sep_str);
    /* Calculate total length */
    for (size_t i = 0; i < arr.v.arr.len; i++) {
        SigilValue item = arr.v.arr.data[i];
        if (item.tag == TAG_STRING) {
            total_len += strlen(item.v.s);
        }
        if (i > 0) total_len += sep_len;
    }
    char* result = (char*)malloc(total_len + 1);
    result[0] = '\0';
    for (size_t i = 0; i < arr.v.arr.len; i++) {
        if (i > 0) strcat(result, sep_str);
        SigilValue item = arr.v.arr.data[i];
        if (item.tag == TAG_STRING) {
            strcat(result, item.v.s);
        }
    }
    return sigil_string(result);
}

/* Print functions */
SigilValue sigil_print(SigilValue v) {
    if (v.tag == TAG_STRING) {
        printf("%s", v.v.s);
    } else {
        SigilValue s = sigil_display(v);
        if (s.tag == TAG_STRING) printf("%s", s.v.s);
    }
    fflush(stdout);
    return sigil_unit();
}

SigilValue sigil_println(SigilValue v) {
    if (v.tag == TAG_STRING) {
        printf("%s\n", v.v.s);
    } else {
        SigilValue s = sigil_display(v);
        if (s.tag == TAG_STRING) printf("%s\n", s.v.s);
    }
    fflush(stdout);
    return sigil_unit();
}

SigilValue sigil_eprint(SigilValue v) {
    if (v.tag == TAG_STRING) {
        fprintf(stderr, "%s", v.v.s);
    } else {
        SigilValue s = sigil_display(v);
        if (s.tag == TAG_STRING) fprintf(stderr, "%s", s.v.s);
    }
    fflush(stderr);
    return sigil_unit();
}

SigilValue sigil_eprintln(SigilValue v) {
    if (v.tag == TAG_STRING) {
        fprintf(stderr, "%s\n", v.v.s);
    } else {
        SigilValue s = sigil_display(v);
        if (s.tag == TAG_STRING) fprintf(stderr, "%s\n", s.v.s);
    }
    fflush(stderr);
    return sigil_unit();
}

/* File I/O functions */
static size_t last_file_len = 0;

char* sigil_read_file(const char* path, size_t len) {
    char path_buf[4096];
    if (len >= sizeof(path_buf)) len = sizeof(path_buf) - 1;
    memcpy(path_buf, path, len);
    path_buf[len] = '\0';

    FILE* f = fopen(path_buf, "rb");
    if (!f) {
        last_file_len = 0;
        return NULL;
    }
    fseek(f, 0, SEEK_END);
    last_file_len = (size_t)ftell(f);
    fseek(f, 0, SEEK_SET);
    char* content = (char*)malloc(last_file_len + 1);
    if (content) {
        size_t read = fread(content, 1, last_file_len, f);
        content[read] = '\0';
        last_file_len = read;
    }
    fclose(f);
    return content;
}

size_t sigil_file_len(void) {
    return last_file_len;
}

/* File write function */
int sigil_write_file(const char* path, size_t path_len, const char* content, size_t content_len) {
    char path_buf[4096];
    if (path_len >= sizeof(path_buf)) path_len = sizeof(path_buf) - 1;
    memcpy(path_buf, path, path_len);
    path_buf[path_len] = '\0';

    FILE* f = fopen(path_buf, "wb");
    if (!f) return 0;
    size_t written = fwrite(content, 1, content_len, f);
    fclose(f);
    return written == content_len ? 1 : 0;
}

/* SigilValue wrappers for extern functions (codegen adds sigil_ prefix) */
SigilValue sigil_sigil_read_file(SigilValue path_ptr, SigilValue len) {
    char* result = sigil_read_file((const char*)path_ptr.v.ptr, (size_t)len.v.i);
    if (result == NULL) return sigil_null();
    return (SigilValue){ .tag = TAG_REF, .evidence = SIGIL_KNOWN, .v.ptr = result };
}

SigilValue sigil_sigil_file_len(void) {
    return sigil_int((int64_t)sigil_file_len());
}

SigilValue sigil_sigil_write_file(SigilValue path_ptr, SigilValue path_len, SigilValue content_ptr, SigilValue content_len) {
    int result = sigil_write_file((const char*)path_ptr.v.ptr, (size_t)path_len.v.i,
                                  (const char*)content_ptr.v.ptr, (size_t)content_len.v.i);
    return sigil_bool(result != 0);
}

