# Transform method call patterns that were passed through raw from macros
# - ". to_string()" -> "" (sigil_format already calls sigil_display)
# - ".to_string()" -> "" (same)
# - ". name()" -> "" (field access handled by struct_field)
# - ".name()" -> "" (same)
# - ". symbol()" -> "" (same)
sed -i \
    -e 's/\. to_string()//g' \
    -e 's/\.to_string()//g' \
    -e 's/\. name()//g' \
    -e 's/\.name()//g' \
    -e 's/\. symbol()//g' \
    -e 's/\.symbol()//g' \
