# Insert missing defines (just macros) right after includes, before any C code
import_end = content.find("#include <string.h>")
if import_end > 0:
    next_line = content.find("\n", import_end + 1) + 1
    content = content[:next_line] + missing_constants + content[next_line:]

# Insert Token____Eof function after sigil_struct is defined
sigil_struct_end = content.find("SigilValue sigil_struct(")
if sigil_struct_end > 0:
    fn_end = content.find("\n}\n", sigil_struct_end) + 3
    content = content[:fn_end] + token_eof_fn + content[fn_end:]

# Insert closure capture globals after SigilValue typedef is defined
sigil_value_typedef_end = content.find("} SigilValue;")
if sigil_value_typedef_end > 0:
    insert_pos = content.find("\n", sigil_value_typedef_end) + 1
    content = content[:insert_pos] + closure_capture_globals + content[insert_pos:]

# Note: Redefinition errors are expected for now - they are caused by enum
# constructors being generated in multiple modules. The GCC will use the
# first definition and ignore the rest due to duplicate symbol handling.
# For now we just let them pass - they don't prevent compilation if we use -Wno-redundant-decls

# Fix Token____Eof() being generated with parentheses (should be a constant, not function)
# Pattern: "const SigilValue Token____Eof() = " -> "const SigilValue Token____Eof = "
content = re.sub(r'const SigilValue Token____Eof\(\) =', r'const SigilValue Token____Eof =', content)

# Find and fix 3-arg TypeEnv define calls (those using EvidentialValue as value)
pattern = r'sigil_TypeEnv____define\(([^,]+), ([^,]+), (sigil_EvidentialValue[^;]+)\);'
replacement = r'sigil_Map____insert(sigil_struct_field(\1, "bindings"), \2, \3);'
content = re.sub(pattern, replacement, content)

# Fix ambiguous sigil_define calls - dispatch based on argument count
# 4 args (env, name, ty, evidence) -> sigil_define_4 (TypeEnv::define)
# 3 args (env, name, value) -> sigil_define_3 (Environment::define)
def replace_define_calls(content):
    result = []
    i = 0
    pattern = 'sigil_define('
    while i < len(content):
        idx = content.find(pattern, i)
        if idx == -1:
            result.append(content[i:])
            break
        result.append(content[i:idx])
        # Find matching close paren
        start = idx + len(pattern)
        depth = 1
        j = start
        while j < len(content) and depth > 0:
            if content[j] == '(':
                depth += 1
            elif content[j] == ')':
                depth -= 1
            j += 1
        args = content[start:j-1]
        # Count args by counting commas at depth 0
        depth = 0
        comma_count = 0
        for ch in args:
            if ch in '([{':
                depth += 1
            elif ch in ')]}':
                depth -= 1
            elif ch == ',' and depth == 0:
                comma_count += 1
        arg_count = comma_count + 1
        if arg_count == 4:
            result.append(f'sigil_define_4({args})')
        elif arg_count == 3:
            result.append(f'sigil_define_3({args})')
        else:
            result.append(f'sigil_define({args})')
        i = j
    return ''.join(result)

content = replace_define_calls(content)

# Fix field access patterns in format args like "x. name" or "x. name. name"
# These come from macro tokens being passed through raw
# Convert "identifier. field" to "sigil_struct_field(identifier, \"field\")"
def fix_field_access(match):
    """Convert x. name to sigil_struct_field(x, "name")"""
    base = match.group(1)
    field = match.group(2).strip()
    return f'sigil_struct_field({base}, "{field}")'

# Match patterns like "word. word" where there are spaces around the dot
# Apply repeatedly for nested access
for _ in range(5):  # Handle up to 5 levels of nesting
    content = re.sub(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\.\s+([a-zA-Z_][a-zA-Z0-9_]*)\b(?!\s*\()', fix_field_access, content)
    # Also fix sigil_struct_field result chained with ". field"
    content = re.sub(r'(sigil_struct_field\([^)]+\))\.\s+([a-zA-Z_][a-zA-Z0-9_]*)\b(?!\s*\()', fix_field_access, content)

# Fix method calls like "x. len()" -> "sigil_len(x)"
def fix_method_call_no_args(match):
    receiver = match.group(1)
    method = match.group(2).strip()
    # Map common methods to sigil_ functions
    method_map = {
        'len': 'sigil_len',
        'to_uppercase': 'sigil_to_uppercase',
        'to_lowercase': 'sigil_to_lowercase',
        'join': 'sigil_join',
        'is_empty': 'sigil_is_empty',
        'chars': 'sigil_String____chars',
        'clone': '', # clone is a no-op
    }
    if method in method_map:
        fn = method_map[method]
        if fn == '':  # clone
            return receiver
        return f'{fn}({receiver})'
    return f'sigil_{method}({receiver})'

# Fix method calls with arguments like "x. method( arg)" -> "sigil_method(x, arg)"
def fix_method_call_with_args(match):
    receiver = match.group(1)
    method = match.group(2).strip()
    args = match.group(3)
    # For mangle_name and other self methods on CodeGen, use generic sigil_method
    return f'sigil_{method}({receiver}, {args})'

# Match patterns like "word. method()" with spaces (no args)
content = re.sub(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\.\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(\)', fix_method_call_no_args, content)
# Also handle sigil_struct_field results (no args)
content = re.sub(r'(sigil_struct_field\([^)]+\))\.\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(\)', fix_method_call_no_args, content)
# Match patterns like "word. method( args)" with spaces (with args) - only match simple cases
content = re.sub(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\.\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(\s*([^)]+)\)', fix_method_call_with_args, content)

# Fix tuple access patterns: pair.0, pair.1 -> sigil_tuple_get(pair, 0), sigil_tuple_get(pair, 1)
def fix_tuple_access(match):
    base = match.group(1)
    idx = match.group(2)
    return f'sigil_tuple_get({base}, {idx})'
content = re.sub(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\.\s*(\d+)\b', fix_tuple_access, content)

# Note: .len() fixes are applied inside fix_format_only below

# Fix format string arguments that have .field accesses
# ONLY apply inside sigil_format() calls to avoid breaking C union access like .v.e.enum_id
def fix_field_access_in_format_call(match):
    """Fix field accesses inside a single sigil_format() call"""
    full_call = match.group(0)
    # Fix .message, .name, .evidence access patterns (only if not preceded by .v which is C union)
    full_call = re.sub(r'(?<![\.v])\.message\b', r'.v_message_placeholder', full_call)
    full_call = re.sub(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\.v_message_placeholder',
                       r'sigil_struct_field(\1, "message")', full_call)
    # Fix .name.name (nested) - watch out for .v. patterns
    full_call = re.sub(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\.name\.name\b(?<![\.v])',
                       r'sigil_struct_field(sigil_struct_field(\1, "name"), "name")', full_call)
    return full_call

# Only fix field access inside sigil_format calls (not elsewhere in C code)
def fix_format_only(content):
    # Find sigil_format(...) calls and fix field access inside them
    result = []
    i = 0
    pattern = 'sigil_format('
    while i < len(content):
        idx = content.find(pattern, i)
        if idx == -1:
            result.append(content[i:])
            break
        result.append(content[i:idx])
        # Find matching close paren
        start = idx
        depth = 0
        j = idx + len(pattern)
        depth = 1
        while j < len(content) and depth > 0:
            if content[j] == '(':
                depth += 1
            elif content[j] == ')':
                depth -= 1
            j += 1
        format_call = content[idx:j]

        # Fix .len() calls inside this format call
        # x.field.len() -> sigil_len(sigil_struct_field(x, "field")) - nested first!
        format_call = re.sub(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\.([a-zA-Z_][a-zA-Z0-9_]*)\.len\(\)',
                             r'sigil_len(sigil_struct_field(\1, "\2"))', format_call)
        # x.len() -> sigil_len(x)
        format_call = re.sub(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\.len\(\)', r'sigil_len(\1)', format_call)

        # Fix field access inside this call only
        # .message -> sigil_struct_field(x, "message")
        format_call = re.sub(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\.message\b',
                             r'sigil_struct_field(\1, "message")', format_call)
        # .name.name -> nested struct field access
        format_call = re.sub(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\.name\.name\b',
                             r'sigil_struct_field(sigil_struct_field(\1, "name"), "name")', format_call)
        # .name -> struct field access (single level, but not before .name)
        format_call = re.sub(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\.name\b(?!\.)',
                             r'sigil_struct_field(\1, "name")', format_call)
        result.append(format_call)
        i = j
    return ''.join(result)

content = fix_format_only(content)

# Fix self.method(...) patterns - self.mangle_name(x) -> sigil_mangle_name((*self), x)
# In mut self methods, self is SigilValue* so we need to dereference
content = re.sub(r'\bself\.mangle_name\(', r'sigil_mangle_name((*self), ', content)
# Fix malformed format string patterns that resulted from partial transformations
# Pattern: self.sigil_len(sigil_struct_field(config, "input_files")) in sigil_Driver____compile
# Look for the specific broken pattern and fix it
content = re.sub(
    r'self\.sigil_len\(sigil_struct_field\(config, "input_files"\)\)',
    r'sigil_len(sigil_struct_field(sigil_struct_field((*self), "config"), "input_files"))',
    content
)
# Also fix any remaining self.sigil_len patterns (but only where self is actually defined)
# This is safer than a global replace

# Fix closures calling mut self methods - they need &self not self
# These methods expect SigilValue* but closures have self as SigilValue
mut_self_methods = [
    'sigil_TypeChecker____unify',
    'sigil_TypeChecker____error',
    'sigil_TypeChecker____check_evidence',
    'sigil_TypeChecker____push_scope',
    'sigil_TypeChecker____pop_scope',
]
for method in mut_self_methods:
    # Inside closures, fix "method(self," to "method(&self,"
    content = re.sub(rf'{method}\(self,', rf'{method}(&self,', content)

# Fix incorrect assignments that should be comparisons
# Pattern: "sigil_len(x) = sigil_len(y);" on its own line is wrong - remove it
# These lines come from buggy lowering of "x.len() != y.len()" comparisons
content = re.sub(r'\n\s*sigil_len\([^)]+\)\s*=\s*sigil_len\([^)]+\);\n', '\n', content)

# Fix "sigil_len(args) = sigil_int(N);" followed by "if (sigil_truthy(sigil_unit()))"
# This pattern comes from buggy codegen of "if args.len() != N" checks
# The fix:
# 1. Extract the N value from the assignment
# 2. Remove the broken assignment line
# 3. Replace "if (sigil_truthy(sigil_unit()))" with "if (sigil_len(args).v.i != N)"
def fix_args_len_check(match):
    """Fix broken args.len() != N codegen pattern"""
    leading_ws = match.group(1)
    n_value = match.group(2)
    temp_var = match.group(3)
    rest = match.group(4)
    # Return corrected code without the broken assignment, with proper condition
    return f"{leading_ws}SigilValue {temp_var};\n{leading_ws}if (sigil_len(args).v.i != {n_value}){rest}"

# Match: sigil_len(args) = sigil_int(NLL);\n        SigilValue _tNN;\n        if (sigil_truthy(sigil_unit())) {
content = re.sub(
    r'(\s*)sigil_len\(args\)\s*=\s*sigil_int\((\d+)LL\);\s*\n\s*SigilValue\s+(_t\d+);\s*\n\s*if\s*\(sigil_truthy\(sigil_unit\(\)\)\)\s*(\{)',
    fix_args_len_check,
    content
)

# Fix "if (sigil_truthy(sigil_unit()))" which should be "if (!sigil_eq(len1, len2))"
# This is a more complex pattern that results from the same bug
# For now, just remove the broken lines

# Fix multiline strings in C - join lines that have unescaped newlines in strings
# Pattern: sigil_format("\n... -> sigil_format("\\n...
content = re.sub(r'sigil_format\("([^"]*)\n', lambda m: 'sigil_format("' + m.group(1).replace('\n', '\\n') + '\\n', content)
# Also handle strings that span multiple lines - join them
content = re.sub(r'"\s*\n([^"]*)"', lambda m: '" "' + m.group(1).replace('\n', ' ') + '"', content)

# Note: The nested quote fix was causing more problems than it solved.
# The "expected ')' before '{'" errors are from format strings with embedded quotes.
# These need to be fixed in the Sigil codegen, not in post-processing.

# Fix closure capture issues - closures use variables from outer scope that aren't passed
# We inject local declarations at the start of each closure function that read from globals
closure_captures = {
    'self': '__closure_self',
    'f': '__closure_f',
    'parent': '__closure_parent',
    'name': '__closure_name',
    'self_type': '__closure_self_type',
    'val': '__closure_val',
    'type_name': '__closure_type_name',
    'span': '__closure_span',
    's': '__closure_s',
    'ident': '__closure_ident',
    'id': '__closure_id',
    'first': '__closure_first',
    'args': '__closure_args',
    'params': '__closure_params',
    'iter': '__closure_iter',
    'fn_ty': '__closure_fn_ty',
    'types': '__closure_types',
    'v': '__closure_v',
    'fresh': '__closure_fresh',
    'binding': '__closure_binding',
    'path': '__closure_path',
    'ty': '__closure_ty',
    'body': '__closure_body',
    'guard': '__closure_guard',
    'def_fields': '__closure_def_fields',
}

def fix_closure_captures(match):
    """Fix closure functions by adding local declarations for captured variables."""
    sig = match.group(1)  # function signature including opening brace
    body = match.group(2)  # function body until closing brace

    # Find which captured variables are used in the body
    needed = []
    for var, global_var in closure_captures.items():
        # Look for the variable used as identifier (word boundary)
        if re.search(r'\b' + var + r'\b', body):
            # Make sure it's not already declared as a parameter
            if var not in sig:
                needed.append(f'    SigilValue {var} = {global_var};')

    if needed:
        captures_code = '\n'.join(needed) + '\n'
        return sig + captures_code + body + '}'
    return match.group(0)

# Match closure functions: static SigilValue sigil_closure_N(...) { ... }
# NOTE: Disabled - codegen now properly handles closure captures via find_free_variables
# content = re.sub(
#     r'(static SigilValue sigil_closure_\d+\([^)]*\)\s*\{)\s*\n((?:[^{}]|\{[^{}]*\})*)\}',
#     fix_closure_captures,
#     content
# )

# Note: Scoped variable hoisting was attempted but caused too many issues.
# The remaining undeclared variables (f, parent, name, etc.) are codegen bugs
# that need to be fixed in the Sigil compiler itself, not post-processing.

# Fix sigil_join with string literals - wrap in sigil_string()
# Pattern: sigil_join(x, "...")  -> sigil_join(x, sigil_string("..."))
def fix_sigil_join_string(match):
    args = match.group(1)
    string_lit = match.group(2)
    return f'sigil_join({args}, sigil_string("{string_lit}"))'

content = re.sub(
    r'sigil_join\(([^,]+),\s*"([^"]+)"\)',
    fix_sigil_join_string,
    content
)

# Fix wrong method dispatch: EvidenceLevel::join called with string separator
# should be Vec::join (sigil_join) instead. This happens when calling .join("::") on string arrays.
# The code generator incorrectly resolves .join() on Vec<String> to EvidenceLevel::join.
content = re.sub(
    r'sigil_EvidenceLevel____join\((\w+),\s*sigil_string\(([^)]+)\)\)',
    r'sigil_join(\1, sigil_string(\2))',
    content
)
print("Fixed EvidenceLevel::join -> sigil_join for string array joins")

# Fix sigil_display stack overflow - add depth limit to prevent infinite recursion
# when displaying complex structs with circular references or deep nesting.
# The crash happens when TypeChecker::error tries to format error messages with path structs.
# This replaces sigil_display with a depth-limited version using a helper function pattern.

# First, add the declaration for the depth-limited helper function after the existing declaration
# Use negative lookbehind to avoid matching strings inside codegen that emit the declaration
# Match only when the declaration is at the start of a line (not inside a string)
content = re.sub(
    r'^(SigilValue sigil_display\(SigilValue v\);)$',
    r'\1\nSigilValue sigil_display_impl(SigilValue v, int depth);',
    content,
    flags=re.MULTILINE
)

# Now replace the function definition with a wrapper that calls the impl
content = re.sub(
    r'SigilValue sigil_display\(SigilValue v\) \{\n    char buf\[256\];\n    switch \(v\.tag\) \{',
    '''SigilValue sigil_display(SigilValue v) {
    return sigil_display_impl(v, 0);
}

SigilValue sigil_display_impl(SigilValue v, int depth) {
    if (depth > 10) return sigil_string("<...>");
    char buf[256];
    switch (v.tag) {''',
    content
)

# Update recursive calls to use sigil_display_impl with depth + 1
# In TAG_STRUCT case: fvs[i] = sigil_display(s->field_values[i]);
content, n = re.subn(
    r'fvs\[i\] = sigil_display\(s->field_values\[i\]\);',
    r'fvs[i] = sigil_display_impl(s->field_values[i], depth + 1);',
    content
)
print(f"Replaced {n} struct field recursive calls")
# In TAG_ARRAY case: evs[i] = sigil_display(v.v.arr.data[i]);
content = re.sub(
    r'evs\[i\] = sigil_display\(v\.v\.arr\.data\[i\]\);',
    r'evs[i] = sigil_display_impl(v.v.arr.data[i], depth + 1);',
    content
)
# In TAG_REF case: return sigil_display(*(SigilValue*)v.v.ptr);
content = re.sub(
    r'case TAG_REF: if \(v\.v\.ptr\) return sigil_display\(\*\(SigilValue\*\)v\.v\.ptr\);',
    r'case TAG_REF: if (v.v.ptr) return sigil_display_impl(*(SigilValue*)v.v.ptr, depth + 1);',
    content
)

print("Added depth limit to sigil_display to prevent stack overflow")

# Fix sigil_display with string literals - wrap in sigil_string()
# Pattern: sigil_display("...")  -> sigil_display(sigil_string("..."))
def fix_sigil_display_string(match):
    string_lit = match.group(1)
    return f'sigil_display(sigil_string("{string_lit}"))'

content = re.sub(
    r'sigil_display\("([^"]+)"\)',
    fix_sigil_display_string,
    content
)

# Fix embedded quotes in format strings
# Pattern: sigil_format("..."{}"...")  -> sigil_format("...\"{}\"...")
# This fixes the unescaped quotes inside sigil_format/sigil_string calls
# Match patterns like: sigil_format("prefix"{}"suffix"
content = re.sub(
    r'(sigil_format\("[^"]*)"(\{\})"',
    r'\1\\"\2\\"',
    content
)

# Fix broken format strings with embedded printf patterns
# Pattern: sigil_format("(printf("%s", {}), sigil_unit())", tokens);
# These have unescaped quotes that break C parsing
# Replace with a simpler format that doesn't need embedded quotes
content = re.sub(
    r'sigil_format\("\\(printf\\("%s", \\{\\}\\), sigil_unit\\(\\)\\)",\s*(\w+)\)',
    r'sigil_format("(printf(\\"%s\\", {}), sigil_unit())", \1)',
    content
)
content = re.sub(
    r'sigil_format\("\\(printf\\("%s\\n", \\{\\}\\), sigil_unit\\(\\)\\)",\s*(\w+)\)',
    r'sigil_format("(printf(\\"%s\\\\n\\", {}), sigil_unit())", \1)',
    content
)

# Also fix patterns like: sigil_string("{}") - rare case
content = re.sub(
    r'sigil_string\("\{\}"\)',
    r'sigil_string("\\"{}\\")',
    content
)

# Fix more complex embedded quote patterns in format strings
# e.g., sigil_format("sigil_struct_set_field(&{}, "{}", {});
content = re.sub(
    r'(sigil_format\("[^"]*)"(\{[^}]*\})"([^"]*"\))',
    r'\1\\"\2\\"\3',
    content
)

# Note: JSON format strings with embedded quotes are left as-is
# These are multiline strings that require codegen-level fixes

# Fix double percent modulo operator: %% -> % (in C code context, not format strings)
# The pattern ".v.i %% " or ".v.f %% " is modulo in C code that got escaped
content = content.replace('.v.i %% ', '.v.i % ')
content = content.replace('.v.f %% ', '.v.f % ')

# Fix broken pattern matching alternatives in Config::from_args
# The pattern "-o" | "--output" was compiled to else if (1) with output_file context
content = re.sub(
    r'} else if \(1\) \{\s*\n\s*/\* Pattern binding: complex = _t2 \*/\s*\n\s*i = [^;]+;\s*\n\s*SigilValue _t4;[^}]+return sigil_Result____Err\(sigil_string\("missing output file after -o"\)\)',
    r'''} else if ((_t2.tag == TAG_STRING && (strcmp(_t2.v.s, "-o") == 0 || strcmp(_t2.v.s, "--output") == 0))) {
            /* Pattern binding: -o | --output */
            i = (i.tag == TAG_INT ? sigil_int(i.v.i + 1) : sigil_int(1));
            SigilValue _t4;
            if (sigil_truthy(sigil_bool((i.tag == TAG_INT ? (double)i.v.i : i.v.f) >= (sigil_len(args).tag == TAG_INT ? (double)sigil_len(args).v.i : sigil_len(args).v.f)))) {
                return sigil_Result____Err(sigil_string("missing output file after -o"))''',
    content)

# Fix verbose flag: else if (1) with verbose field -> -v | --verbose
content = re.sub(
    r'} else if \(1\) \{\s*\n\s*/\* Pattern binding: complex = _t2 \*/\s*\n\s*sigil_struct_set_field\(&config, "verbose", sigil_bool\(true\)\)',
    r'''} else if ((_t2.tag == TAG_STRING && (strcmp(_t2.v.s, "-v") == 0 || strcmp(_t2.v.s, "--verbose") == 0))) {
            /* Pattern binding: -v | --verbose */
            sigil_struct_set_field(&config, "verbose", sigil_bool(true))''',
    content)

# Fix debug flag: else if (1) with debug field -> -g | --debug
content = re.sub(
    r'} else if \(1\) \{\s*\n\s*/\* Pattern binding: complex = _t2 \*/\s*\n\s*sigil_struct_set_field\(&config, "debug", sigil_bool\(true\)\)',
    r'''} else if ((_t2.tag == TAG_STRING && (strcmp(_t2.v.s, "-g") == 0 || strcmp(_t2.v.s, "--debug") == 0))) {
            /* Pattern binding: -g | --debug */
            sigil_struct_set_field(&config, "debug", sigil_bool(true))''',
    content)

# Fix help flag: else if (1) with help_text -> -h | --help
content = re.sub(
    r'} else if \(1\) \{\s*\n\s*/\* Pattern binding: complex = _t2 \*/\s*\n\s*return sigil_Result____Err\(sigil_Self____help_text\(\)\)',
    r'''} else if ((_t2.tag == TAG_STRING && (strcmp(_t2.v.s, "-h") == 0 || strcmp(_t2.v.s, "--help") == 0))) {
            /* Pattern binding: -h | --help */
            return sigil_Result____Err(sigil_Self____help_text())''',
    content)

# Fix catch-all pattern: else if (1) with starts_with("-") check -> just else
# And remove the orphaned else block that follows it
content = re.sub(
    r'} else if \(1\) \{\s*\n\s*SigilValue _t5;\s*\n\s*if \(sigil_truthy\(sigil_String____starts_with\(arg, sigil_string\("-"\)\)\)\)',
    r'''} else {
            SigilValue _t5;
            if (sigil_truthy(sigil_String____starts_with(arg, sigil_string("-"))))''',
    content)

# Remove orphaned else block after catch-all in Config::from_args
# Pattern: closing brace, sigil_Vec____push, closing brace, orphaned else with just _t3 = sigil_unit
content = re.sub(
    r'(_t3 = sigil_Vec____push\([^)]+\);\s*\n\s*\} else \{\s*\n\s*_t3 = sigil_unit\(\);\s*\n\s*\})',
    r'_t3 = sigil_Vec____push(_t6, arg); sigil_struct_set_field(&config, "input_files", _t3);\n        }',
    content)

# Also fix standalone Vec push without orphan (in case the regex above misses it)
content = re.sub(
    r'(SigilValue _t6 = sigil_struct_field\(config, "input_files"\);\s*\n\s*)_t3 = sigil_Vec____push\(_t6, arg\);(\s*\n\s*\})',
    r'\1_t3 = sigil_Vec____push(_t6, arg); sigil_struct_set_field(&config, "input_files", _t3);\2',
    content)

# Fix Self::help_text() to call the real Config::help_text() function
content = re.sub(
    r'sigil_Self____help_text\(\)',
    r'sigil_Config____help_text()',
    content)

# Fix Config::from_args to start at index 1 (skip program name)
content = re.sub(
    r'(SigilValue sigil_Config____from_args\(SigilValue args\) \{\s*\n\s*SigilValue config = sigil_Config____default\(\);\s*\n\s*)SigilValue i = sigil_int\(0LL\);',
    r'\1SigilValue i = sigil_int(1LL);',
    content)

# Fix Result type tag comparisons in sigil_main
# Generated code uses 0/1 for Ok/Err, but runtime uses TAG_RESULT_OK (14) / TAG_RESULT_ERR (15)
# Pattern: ((_t0.tag == 0)) for Result::Ok should be ((_t0.tag == TAG_RESULT_OK))
# Pattern: ((_t0.tag == 1)) for Result::Err should be ((_t0.tag == TAG_RESULT_ERR))
content = re.sub(
    r'\(\(_t0\.tag == 0\)\)',
    r'(sigil_is_ok(_t0))',
    content)
content = re.sub(
    r'\(\(_t0\.tag == 1\)\)',
    r'(sigil_is_err(_t0))',
    content)

# Also fix the pattern: (_tN.tag == TAG_ENUM && _tN.v.e.variant == 0) for Result::Ok
# and (_tN.tag == TAG_ENUM && _tN.v.e.variant == 1) for Result::Err
content = re.sub(
    r'\((_t[0-9]+)\.tag == TAG_ENUM && \1\.v\.e\.variant == 0\)',
    r'(sigil_is_ok(\1))',
    content)
content = re.sub(
    r'\((_t[0-9]+)\.tag == TAG_ENUM && \1\.v\.e\.variant == 1\)',
    r'(sigil_is_err(\1))',
    content)
# Fix enum data access: _tN.v.e.data[0] -> sigil_enum_data(_tN)
# This extracts the first field from enum variant data after TAG_ENUM check
content = re.sub(
    r'(_t[0-9]+)\.v\.e\.data\[0\]',
    r'sigil_enum_data(\1)',
    content)

# Same for _t2 which is used in Driver::run result
content = re.sub(
    r'\(\(_t2\.tag == 0\)\)',
    r'(sigil_is_ok(_t2))',
    content)
content = re.sub(
    r'\(\(_t2\.tag == 1\)\)',
    r'(sigil_is_err(_t2))',
    content)

# Note: DO NOT convert tuple field access .v.tup.fields[0] to sigil_unwrap_result()
# That breaks actual tuple access which is different from Result unwrapping

# Fix Vec push in Driver::compile - store result back into modules
content = re.sub(
    r'_t4 = sigil_Vec____push\(modules, ir\);',
    r'modules = sigil_Vec____push(modules, ir);',
    content)

# Fix output file writing in Driver::compile
# Pattern: if (1) { SigilValue output = _t17; sigil_null();
# Replace with: proper option check and actual file writing
content = re.sub(
    r'SigilValue _t18;\s*\n\s*if \(1\) \{\s*\n\s*SigilValue output = _t17;\s*\n\s*sigil_null\(\);',
    r'''SigilValue _t18;
    if (_t17.tag != TAG_NULL) {
        SigilValue output = _t17;
        /* Actually write the file */
        if (output.tag == TAG_STRING && output.v.s && c_code.tag == TAG_STRING && c_code.v.s) {
            FILE* f = fopen(output.v.s, "w");
            if (f) { fprintf(f, "%s", c_code.v.s); fclose(f); }
        }''',
    content)

# Fix i + 1 where i is SigilValue - wrap with sigil_int
content = re.sub(r',\s+([a-z_][a-z0-9_]*)\s+\+\s+(\d+)\)', r', sigil_int(\1.v.i + \2))', content)

# Helper function to replace broken functions with stubs
def fix_broken_function(content, name):
    """Replace a broken function with a stub that returns null/unit."""
    # Convert Sigil::method to sigil_Class____method format
    c_name = 'sigil_' + name.replace('::', '____')
    stub = f'SigilValue {c_name}(SigilValue self) {{ return sigil_null(); }}'

    # Find the function definition and replace it with stub
    # We need to handle nested braces properly
    func_start = f'SigilValue {c_name}('
    idx = content.find(func_start)
    if idx == -1:
        return content

    # Find opening brace
    brace_idx = content.find('{', idx)
    if brace_idx == -1:
        return content

    # Count braces to find end of function
    depth = 1
    end_idx = brace_idx + 1
    while depth > 0 and end_idx < len(content):
        if content[end_idx] == '{':
            depth += 1
        elif content[end_idx] == '}':
            depth -= 1
        end_idx += 1

    # Replace the function
    return content[:idx] + stub + content[end_idx:]

