content = re.sub(
    r'sigil_format\("\\(printf\\("(%[^"]+)",\s*\\{\\}\\),\s*sigil_unit\\(\\)\\)",\s*(\w+)\)',
    r'sigil_concat(sigil_concat(sigil_string("(printf(\\""), sigil_concat(sigil_string("\1"), sigil_concat(sigil_string("\\", "), sigil_concat(\2, sigil_string("), sigil_unit())"))))),',
