# Remove duplicate static inline function definitions (keep first, remove subsequent)
def remove_duplicate_functions(content):
    """Remove duplicate static inline function definitions."""
    seen_functions = set()
    result_lines = []
    lines = content.split('\n')
    skip_until_close = False
    brace_depth = 0

    i = 0
    while i < len(lines):
        line = lines[i]
        # Check if this starts a static inline function
        if line.startswith('static inline SigilValue ') and '(' in line:
            # Extract function name
            match = re.match(r'static inline SigilValue (\w+)\(', line)
            if match:
                func_name = match.group(1)
                if func_name in seen_functions:
                    # Skip this duplicate definition
                    brace_depth = line.count('{') - line.count('}')
                    i += 1
                    while i < len(lines) and brace_depth > 0:
                        brace_depth += lines[i].count('{') - lines[i].count('}')
                        i += 1
                    continue
                else:
                    seen_functions.add(func_name)
        result_lines.append(line)
        i += 1
    return '\n'.join(result_lines)

