    r'SigilValue\* data = \(SigilValue\*\)calloc\(len, sizeof\(SigilValue\)\);\s*'
    r'return \(SigilValue\)\{ \.tag = TAG_ARRAY, \.evidence = SIGIL_KNOWN, \.v\.arr = \{ data, len, len \} \};\s*'
    r'\}',
    r'''static inline SigilValue sigil_array(size_t len) {
    /* Use header format for shared length tracking */
    size_t cap = len < 4 ? 4 : len;
    SigilArrayHeader* header = (SigilArrayHeader*)calloc(1, sizeof(SigilArrayHeader) + cap * sizeof(SigilValue));
    header->len = len;
    header->cap = cap;
    return (SigilValue){ .tag = TAG_ARRAY, .evidence = SIGIL_KNOWN, .v.arr = { (SigilValue*)sigil_array_data(header), len, cap } };
}''',
