# Fix sigil_eq to properly compare all types including tokens/enums
# Tokens use tag values > 20, so we need to handle them as tag-only comparison
content = re.sub(
    r'static inline bool sigil_eq\(SigilValue a, SigilValue b\) \{\s*'
    r'if \(a\.tag != b\.tag\) return false;\s*'
    r'switch \(a\.tag\) \{\s*'
    r'case TAG_BOOL: return a\.v\.b == b\.v\.b;\s*'
    r'case TAG_INT: return a\.v\.i == b\.v\.i;\s*'
    r'case TAG_FLOAT: return a\.v\.f == b\.v\.f;\s*'
    r'case TAG_CHAR: return a\.v\.c == b\.v\.c;\s*'
    r'case TAG_STRING: return strcmp\(a\.v\.s, b\.v\.s\) == 0;\s*'
    r'case TAG_NULL: return true;\s*'
    r'case TAG_UNIT: return true;\s*'
    r'(?:case TAG_ENUM: return a\.v\.e\.enum_id == b\.v\.e\.enum_id && a\.v\.e\.variant == b\.v\.e\.variant;\s*)?'
    r'default: return false;\s*'
    r'\}\s*'
    r'\}',
    '''static inline bool sigil_eq(SigilValue a, SigilValue b) {
    /* Handle TAG_REF by dereferencing */
    if (a.tag == TAG_REF && a.v.ptr) a = *(SigilValue*)a.v.ptr;
    if (b.tag == TAG_REF && b.v.ptr) b = *(SigilValue*)b.v.ptr;

    if (a.tag != b.tag) return false;
    switch (a.tag) {
        case TAG_BOOL: return a.v.b == b.v.b;
        case TAG_INT: return a.v.i == b.v.i;
        case TAG_FLOAT: return a.v.f == b.v.f;
        case TAG_CHAR: return a.v.c == b.v.c;
        case TAG_STRING: return a.v.s && b.v.s && strcmp(a.v.s, b.v.s) == 0;
        case TAG_NULL: return true;
        case TAG_UNIT: return true;
        case TAG_STRUCT:
            /* For structs, compare pointers - same struct instance */
            return a.v.ptr == b.v.ptr;
        case TAG_TUPLE: {
            if (a.v.tup.count != b.v.tup.count) return false;
            for (size_t i = 0; i < a.v.tup.count; i++) {
                if (!sigil_eq(a.v.tup.fields[i], b.v.tup.fields[i])) return false;
            }
            return true;
        }
        case TAG_ARRAY: {
            if (a.v.arr.len != b.v.arr.len) return false;
            for (size_t i = 0; i < a.v.arr.len; i++) {
                if (!sigil_eq(a.v.arr.data[i], b.v.arr.data[i])) return false;
            }
            return true;
        }
        case TAG_ENUM:
            return a.v.e.enum_id == b.v.e.enum_id && a.v.e.variant == b.v.e.variant;
        default:
            /* For unknown tags, compare as opaque values */
            return false;
    }
}''',
    content,
    flags=re.DOTALL)

