# Add helper functions if not present
helpers = '''
/* Helper for AST node kind name */
SigilValue sigil_kind_name(SigilValue node) {
    if (node.tag == TAG_STRUCT) {
        SigilStruct* s = (SigilStruct*)node.v.ptr;
        return sigil_string(s->name ? s->name : "unknown");
    }
    return sigil_string("unknown");
}

/* String to uppercase helper */
SigilValue sigil_String____to_uppercase(SigilValue s) {
    if (s.tag != TAG_STRING || !s.v.s) return sigil_string("");
    size_t len = strlen(s.v.s);
    char* result = (char*)malloc(len + 1);
    for (size_t i = 0; i < len; i++) {
        result[i] = (s.v.s[i] >= 'a' && s.v.s[i] <= 'z') ? s.v.s[i] - 32 : s.v.s[i];
    }
    result[len] = 0;
    return sigil_string(result);
}

/* Vec join helper */
SigilValue sigil_Vec____join(SigilValue arr, SigilValue sep) {
    if (arr.tag != TAG_ARRAY) return sigil_string("");
    if (arr.v.arr.len == 0) return sigil_string("");

    const char* separator = sep.tag == TAG_STRING && sep.v.s ? sep.v.s : "";
    size_t sep_len = strlen(separator);

    // Calculate total length
    size_t total = 0;
    for (size_t i = 0; i < arr.v.arr.len; i++) {
        SigilValue elem = arr.v.arr.data[i];
        SigilValue s = sigil_display(elem);
        if (s.tag == TAG_STRING && s.v.s) total += strlen(s.v.s);
        if (i > 0) total += sep_len;
    }

    char* result = (char*)malloc(total + 1);
    char* p = result;
    for (size_t i = 0; i < arr.v.arr.len; i++) {
        if (i > 0) { memcpy(p, separator, sep_len); p += sep_len; }
        SigilValue elem = arr.v.arr.data[i];
        SigilValue s = sigil_display(elem);
        if (s.tag == TAG_STRING && s.v.s) {
            size_t len = strlen(s.v.s);
            memcpy(p, s.v.s, len);
            p += len;
        }
    }
    *p = 0;
    return sigil_string(result);
}

'''

