)

# Fix character range pattern in mangle_name function
# Pattern: if ((1 || 1 || 1)) { sigil_String____push(result, c) }
# This should check for alphanumeric characters 'a'..'z' | 'A'..'Z' | '0'..'9'
content = re.sub(
    r"if \(\(1 \|\| 1 \|\| 1\)\) \{\s*"
    r"/\* Pattern binding: complex = _t5 \*/\s*"
    r"_t6 = sigil_String____push\(result, c\);",
