# Replace all CALLS to sigil_CodeGen____mangle_name with sigil_mangle_name
# The sigil_mangle_name function in the header correctly handles :: -> ____ conversion
# while the generated sigil_CodeGen____mangle_name has broken String::push semantics
# First, rename the broken function definition to avoid redefinition error
content = re.sub(
    r'/\* Function: CodeGen::mangle_name \*/\s*\nSigilValue sigil_CodeGen____mangle_name\(',
    r'/* Function: CodeGen::mangle_name - BROKEN, use sigil_mangle_name instead */\nSigilValue sigil_CodeGen____mangle_name_broken(',
    content
)
# Now replace all calls to sigil_CodeGen____mangle_name with sigil_mangle_name
content = content.replace('sigil_CodeGen____mangle_name(', 'sigil_mangle_name(')
print("Replaced sigil_CodeGen____mangle_name with sigil_mangle_name (correct implementation)")

# Remove the broken generated Lexer helper functions (we provide fixed versions in runtime)
# Rename the function definitions to _broken so they don't conflict
broken_funcs = [
    'is_digit',
    'is_digit_or_underscore',
    'is_hex_digit',
    'is_hex_or_underscore',
    'is_vigesimal_or_underscore',
    'is_alnum_or_underscore',
    'is_duodecimal_or_underscore',
    'is_alpha',
    'is_unicode_alnum_or_underscore',
]

for func in broken_funcs:
    # Rename the function definition (but not calls) to _broken_codegen
    # Match: /* Function: Lexer::XXX */\nSigilValue sigil_Lexer____XXX(
    pattern = r'(/\* Function: Lexer::' + func + r' \*/\s*\n)(SigilValue sigil_Lexer____' + func + r')\('
    replacement = r'\1SigilValue sigil_Lexer____' + func + r'_broken_codegen('
    content = re.sub(pattern, replacement, content)

print("Fixed character range patterns in next_token and renamed broken helpers")

# Fix CodeGen::line function - the generated code has several bugs:
# 1. Uses sigil_null().v.arr.len OR sigil_struct_field for loop bound (both patterns)
# 2. Uses sigil_Vec____push instead of sigil_String____push for newline
# 3. Doesn't store push_str results back to struct field
# Pattern 1: Uses sigil_null().v.arr.len
content = re.sub(
    r'SigilValue sigil_CodeGen____line\(SigilValue\* self, SigilValue s\) \{\s*'
    r'SigilValue _t0 = sigil_unit\(\);\s*'
    r'for \(size_t _t1 = 0; _t1 < sigil_null\(\)\.v\.arr\.len; _t1\+\+\) \{\s*'
    r'SigilValue _t2 = sigil_struct_field\(\(\*self\), "output"\);\s*'
    r'_t0 = sigil_String____push_str\(_t2, sigil_string\("    "\)\);\s*'
    r'\}\s*'
    r'_t0;\s*'
    r'SigilValue _t3 = sigil_struct_field\(\(\*self\), "output"\);\s*'
    r'sigil_String____push_str\(_t3, s\);\s*'
    r'SigilValue _t4 = sigil_struct_field\(\(\*self\), "output"\);\s*'
    r'return sigil_Vec____push\(_t4, sigil_char\(\'\\n\'\)\);\s*'
    r'\}',
    r'''SigilValue sigil_CodeGen____line(SigilValue* self, SigilValue s) {
    /* FIXED: Use self.indent for loop bound, String::push for newline, store results back */
    SigilValue output = sigil_struct_field((*self), "output");
    SigilValue indent = sigil_struct_field((*self), "indent");
    int64_t indent_count = (indent.tag == TAG_INT) ? indent.v.i : 0;
    for (int64_t _t1 = 0; _t1 < indent_count; _t1++) {
        output = sigil_String____push_str(output, sigil_string("    "));
    }
    output = sigil_String____push_str(output, s);
    output = sigil_String____push(output, sigil_char('\\n'));
    sigil_struct_set_field(&(*self), "output", output);
    return sigil_unit();
}''',
    content)

# Pattern 2: Uses sigil_struct_field for indent (the actual generated pattern)
content = re.sub(
    r'SigilValue sigil_CodeGen____line\(SigilValue\* self, SigilValue s\) \{\s*'
    r'SigilValue _t0 = sigil_unit\(\);\s*'
    r'SigilValue _t1 = sigil_struct_field\(\(\*self\), "indent"\);\s*'
    r'for \(int64_t _t2 = sigil_int\(0LL\)\.v\.i; _t2 < _t1\.v\.i; _t2\+\+\) \{\s*'
    r'SigilValue _t3 = sigil_struct_field\(\(\*self\), "output"\);\s*'
    r'_t0 = sigil_String____push_str\(_t3, sigil_string\("    "\)\);\s*'
    r'\}\s*'
    r'_t0;\s*'
    r'SigilValue _t4 = sigil_struct_field\(\(\*self\), "output"\);\s*'
    r'sigil_String____push_str\(_t4, s\);\s*'
    r'SigilValue _t5 = sigil_struct_field\(\(\*self\), "output"\);\s*'
    r'return sigil_Vec____push\(_t5, sigil_char\(\'\\n\'\)\);\s*'
    r'\}',
    r'''SigilValue sigil_CodeGen____line(SigilValue* self, SigilValue s) {
    /* FIXED: Use self.indent for loop bound, String::push for newline, store results back */
    SigilValue output = sigil_struct_field((*self), "output");
    SigilValue indent = sigil_struct_field((*self), "indent");
    int64_t indent_count = (indent.tag == TAG_INT) ? indent.v.i : 0;
    for (int64_t _t1 = 0; _t1 < indent_count; _t1++) {
        output = sigil_String____push_str(output, sigil_string("    "));
    }
    output = sigil_String____push_str(output, s);
    output = sigil_String____push(output, sigil_char('\\n'));
    sigil_struct_set_field(&(*self), "output", output);
    return sigil_unit();
}''',
    content)

# Also fix CodeGen::emit which has the same issue (ignores return value)
content = re.sub(
    r'SigilValue sigil_CodeGen____emit\(SigilValue\* self, SigilValue s\) \{\s*'
    r'SigilValue _t0 = sigil_struct_field\(\(\*self\), "output"\);\s*'
    r'return sigil_String____push_str\(_t0, s\);\s*'
    r'\}',
    r'''SigilValue sigil_CodeGen____emit(SigilValue* self, SigilValue s) {
    /* FIXED: Store push_str result back into struct field */
    SigilValue output = sigil_struct_field((*self), "output");
    output = sigil_String____push_str(output, s);
    sigil_struct_set_field(&(*self), "output", output);
    return sigil_unit();
}''',
    content)

print("Fixed CodeGen::line and CodeGen::emit to use correct indent loop and store push results")

# Fix CodeGen::generate - push_str calls don't store results back
# Pattern 1: closure buffer push in generate
content = re.sub(
    r'(SigilValue _t14 = sigil_struct_field\(\(\*self\), "output"\);\s*)'
    r'(SigilValue _t15 = sigil_struct_field\(\(\*self\), "closure_buffer"\);\s*)'
    r'sigil_String____push_str\(_t14, sigil_String____as_str\(_t15\)\);',
    r'''\1\2{
            SigilValue new_out = sigil_String____push_str(_t14, sigil_String____as_str(_t15));
            sigil_struct_set_field(&(*self), "output", new_out);
        }''',
    content)

# Pattern 2: func_code push in generate
content = re.sub(
    r'(SigilValue _t16 = sigil_struct_field\(\(\*self\), "output"\);\s*)'
    r'sigil_String____push_str\(_t16, sigil_String____as_str\(func_code\)\);',
    r'''\1{
        SigilValue new_out = sigil_String____push_str(_t16, sigil_String____as_str(func_code));
        sigil_struct_set_field(&(*self), "output", new_out);
    }''',
    content)

print("Fixed CodeGen::generate to store push_str results back")

# Fix sigil_struct_field to handle TAG_REF - dereference references before accessing fields
# This is critical for functions that receive &mut parameters
content = re.sub(
    r'SigilValue sigil_struct_field\(SigilValue v, const char\* field\) \{\s*'
    r'if \(v\.tag != TAG_STRUCT\) return sigil_null\(\);\s*'
    r'SigilStruct\* s = \(SigilStruct\*\)v\.v\.ptr;',
    r'''SigilValue sigil_struct_field(SigilValue v, const char* field) {
    /* FIXED: Dereference TAG_REF before accessing struct fields */
    while (v.tag == TAG_REF && v.v.ptr) {
        v = *((SigilValue*)v.v.ptr);
    }
    if (v.tag != TAG_STRUCT) return sigil_null();
    SigilStruct* s = (SigilStruct*)v.v.ptr;
    if (!s) return sigil_null();
    if (!s->field_names) return sigil_null();
    if (!s->field_values) return sigil_null();''',
    content)

# Also fix sigil_struct_set_field to handle TAG_REF
content = re.sub(
    r'SigilValue sigil_struct_set_field\(SigilValue\* v, const char\* field, SigilValue val\) \{\s*'
    r'if \(v->tag != TAG_STRUCT\) return sigil_unit\(\);\s*'
    r'SigilStruct\* s = \(SigilStruct\*\)v->v\.ptr;',
    r'''SigilValue sigil_struct_set_field(SigilValue* v, const char* field, SigilValue val) {
    /* FIXED: Dereference TAG_REF before setting struct fields */
    SigilValue* target = v;
    while (target->tag == TAG_REF && target->v.ptr) {
        target = (SigilValue*)target->v.ptr;
    }
    if (target->tag != TAG_STRUCT) return sigil_unit();
    SigilStruct* s = (SigilStruct*)target->v.ptr;
    if (!s) return sigil_unit();''',
    content)

print("Fixed sigil_struct_field and sigil_struct_set_field to handle TAG_REF")

# Additional fix: add NULL checks and DEBUG to sigil_struct_field
content = re.sub(
    r'if \(strcmp\(s->field_names\[i\], field\) == 0\) return s->field_values\[i\];',
    r'''if (s->field_names[i] && strcmp(s->field_names[i], field) == 0) return s->field_values[i];''',
    content)

content = re.sub(
    r'if \(strcmp\(s->field_names\[i\], field\) == 0\) \{ s->field_values\[i\] = val;',
    r'''if (s->field_names[i] && strcmp(s->field_names[i], field) == 0) { s->field_values[i] = val;''',
    content)

print("Keeping simple NULL checks in sigil_struct_field")

# CG-101: FIX sigil_struct_field to handle TAG_ENUM values
# When accessing fields on enum variants (like IrOperation::Literal.value),
# the value is TAG_ENUM, not TAG_STRUCT. We need to map field names to indices.
# Match the specific context after TAG_REF dereference to avoid matching string literals
content = re.sub(
    r'(v = \*\(\(SigilValue\*\)v\.v\.ptr\);\s*\}\s*)(if \(v\.tag != TAG_STRUCT\) return sigil_null\(\);)',
    r'''\1/* CG-101: Handle TAG_ENUM values (enum variant field access) */
    if (v.tag == TAG_ENUM && v.v.e.data && v.v.e.field_count > 0) {
        uint32_t eid = v.v.e.enum_id;
        uint32_t var = v.v.e.variant;
        /* IrOperation field mappings - variant(0), value(1), ty(2), evidence(3), etc. */
        if (eid == 2122636273U || eid == 0xDEAD0006U) {  /* IROPERATION_ENUM_ID */
            if (var == 0) { /* Literal: variant, value, ty, evidence */
                if (strcmp(field, "variant") == 0) return v.v.e.data[0];
                if (strcmp(field, "value") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 1) { /* Var: name, id, ty, evidence */
                if (strcmp(field, "name") == 0) return v.v.e.data[0];
                if (strcmp(field, "id") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 2) { /* Let: pattern, type_annotation, init, evidence */
                if (strcmp(field, "pattern") == 0) return v.v.e.data[0];
                if (strcmp(field, "type_annotation") == 0) return v.v.e.data[1];
                if (strcmp(field, "init") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 3) { /* LetElse: pattern, type_annotation, init, else_branch, evidence */
                if (strcmp(field, "pattern") == 0) return v.v.e.data[0];
                if (strcmp(field, "type_annotation") == 0) return v.v.e.data[1];
                if (strcmp(field, "init") == 0) return v.v.e.data[2];
                if (strcmp(field, "else_branch") == 0) return v.v.e.data[3];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[4];
            } else if (var == 4) { /* Binary: operator, left, right, ty, evidence */
                if (strcmp(field, "operator") == 0) return v.v.e.data[0];
                if (strcmp(field, "left") == 0) return v.v.e.data[1];
                if (strcmp(field, "right") == 0) return v.v.e.data[2];
                if (strcmp(field, "ty") == 0) return v.v.e.data[3];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[4];
            } else if (var == 5) { /* Unary: operator, operand, ty, evidence */
                if (strcmp(field, "operator") == 0) return v.v.e.data[0];
                if (strcmp(field, "operand") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 6) { /* Call: function, function_id, args, type_args, ty, evidence */
                if (strcmp(field, "function") == 0) return v.v.e.data[0];
                if (strcmp(field, "function_id") == 0) return v.v.e.data[1];
                if (strcmp(field, "args") == 0) return v.v.e.data[2];
                if (strcmp(field, "type_args") == 0) return v.v.e.data[3];
                if (strcmp(field, "ty") == 0) return v.v.e.data[4];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[5];
            } else if (var == 7) { /* MethodCall: receiver, method, args, type_args, ty, evidence */
                if (strcmp(field, "receiver") == 0) return v.v.e.data[0];
                if (strcmp(field, "method") == 0) return v.v.e.data[1];
                if (strcmp(field, "args") == 0) return v.v.e.data[2];
                if (strcmp(field, "type_args") == 0) return v.v.e.data[3];
                if (strcmp(field, "ty") == 0) return v.v.e.data[4];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[5];
            } else if (var == 8) { /* Closure: params, body, captures, ty, evidence */
                if (strcmp(field, "params") == 0) return v.v.e.data[0];
                if (strcmp(field, "body") == 0) return v.v.e.data[1];
                if (strcmp(field, "captures") == 0) return v.v.e.data[2];
                if (strcmp(field, "ty") == 0) return v.v.e.data[3];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[4];
            } else if (var == 9) { /* If: condition, then_branch, else_branch, ty, evidence */
                if (strcmp(field, "condition") == 0) return v.v.e.data[0];
                if (strcmp(field, "then_branch") == 0) return v.v.e.data[1];
                if (strcmp(field, "else_branch") == 0) return v.v.e.data[2];
                if (strcmp(field, "ty") == 0) return v.v.e.data[3];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[4];
            } else if (var == 10) { /* Match: scrutinee, arms, ty, evidence */
                if (strcmp(field, "scrutinee") == 0) return v.v.e.data[0];
                if (strcmp(field, "arms") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 11) { /* LetMatch: pattern, value, ty, evidence */
                if (strcmp(field, "pattern") == 0) return v.v.e.data[0];
                if (strcmp(field, "value") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 12) { /* Loop: variant, condition, iterator, body, ty, evidence */
                if (strcmp(field, "variant") == 0) return v.v.e.data[0];
                if (strcmp(field, "condition") == 0) return v.v.e.data[1];
                if (strcmp(field, "iterator") == 0) return v.v.e.data[2];
                if (strcmp(field, "body") == 0) return v.v.e.data[3];
                if (strcmp(field, "ty") == 0) return v.v.e.data[4];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[5];
            } else if (var == 13) { /* Break: value, evidence */
                if (strcmp(field, "value") == 0) return v.v.e.data[0];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[1];
            } else if (var == 14) { /* Continue: evidence */
                if (strcmp(field, "evidence") == 0) return v.v.e.data[0];
            } else if (var == 15) { /* Return: value, evidence */
                if (strcmp(field, "value") == 0) return v.v.e.data[0];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[1];
            } else if (var == 16) { /* Block: statements, ty, evidence */
                if (strcmp(field, "statements") == 0) return v.v.e.data[0];
                if (strcmp(field, "ty") == 0) return v.v.e.data[1];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[2];
            } else if (var == 17) { /* Pipeline: input, steps, ty, evidence */
                if (strcmp(field, "input") == 0) return v.v.e.data[0];
                if (strcmp(field, "steps") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 18) { /* Morpheme: morpheme, symbol, input, body, ty, evidence */
                if (strcmp(field, "morpheme") == 0) return v.v.e.data[0];
                if (strcmp(field, "symbol") == 0) return v.v.e.data[1];
                if (strcmp(field, "input") == 0) return v.v.e.data[2];
                if (strcmp(field, "body") == 0) return v.v.e.data[3];
                if (strcmp(field, "ty") == 0) return v.v.e.data[4];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[5];
            } else if (var == 19) { /* Fork: branches, join_strategy, ty, evidence */
                if (strcmp(field, "branches") == 0) return v.v.e.data[0];
                if (strcmp(field, "join_strategy") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 20) { /* Identity: ty, evidence */
                if (strcmp(field, "ty") == 0) return v.v.e.data[0];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[1];
            } else if (var == 21) { /* Array: elements, ty, evidence */
                if (strcmp(field, "elements") == 0) return v.v.e.data[0];
                if (strcmp(field, "ty") == 0) return v.v.e.data[1];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[2];
            } else if (var == 22) { /* Tuple: elements, ty, evidence */
                if (strcmp(field, "elements") == 0) return v.v.e.data[0];
                if (strcmp(field, "ty") == 0) return v.v.e.data[1];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[2];
            } else if (var == 23) { /* StructInit: name, fields, rest, ty, evidence */
                if (strcmp(field, "name") == 0) return v.v.e.data[0];
                if (strcmp(field, "fields") == 0) return v.v.e.data[1];
                if (strcmp(field, "rest") == 0) return v.v.e.data[2];
                if (strcmp(field, "ty") == 0) return v.v.e.data[3];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[4];
            } else if (var == 24) { /* Field: expr, field, ty, evidence */
                if (strcmp(field, "expr") == 0) return v.v.e.data[0];
                if (strcmp(field, "field") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 25) { /* Index: expr, index, ty, evidence */
                if (strcmp(field, "expr") == 0) return v.v.e.data[0];
                if (strcmp(field, "index") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 26) { /* Assign: target, value, evidence */
                if (strcmp(field, "target") == 0) return v.v.e.data[0];
                if (strcmp(field, "value") == 0) return v.v.e.data[1];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[2];
            } else if (var == 27) { /* EvidenceCoerce: operation, expr, from_evidence, to_evidence, ty */
                if (strcmp(field, "operation") == 0) return v.v.e.data[0];
                if (strcmp(field, "expr") == 0) return v.v.e.data[1];
                if (strcmp(field, "from_evidence") == 0) return v.v.e.data[2];
                if (strcmp(field, "to_evidence") == 0) return v.v.e.data[3];
                if (strcmp(field, "ty") == 0) return v.v.e.data[4];
            } else if (var == 28) { /* Incorporation: segments, args, ty, evidence */
                if (strcmp(field, "segments") == 0) return v.v.e.data[0];
                if (strcmp(field, "args") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 29) { /* HttpRequest: method, url, headers, body, timeout_ms, ty, evidence */
                if (strcmp(field, "method") == 0) return v.v.e.data[0];
                if (strcmp(field, "url") == 0) return v.v.e.data[1];
                if (strcmp(field, "headers") == 0) return v.v.e.data[2];
                if (strcmp(field, "body") == 0) return v.v.e.data[3];
                if (strcmp(field, "timeout_ms") == 0) return v.v.e.data[4];
                if (strcmp(field, "ty") == 0) return v.v.e.data[5];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[6];
            } else if (var == 30) { /* WebSocket: operation, url, message, ty, evidence */
                if (strcmp(field, "operation") == 0) return v.v.e.data[0];
                if (strcmp(field, "url") == 0) return v.v.e.data[1];
                if (strcmp(field, "message") == 0) return v.v.e.data[2];
                if (strcmp(field, "ty") == 0) return v.v.e.data[3];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[4];
            } else if (var == 31) { /* Await: expr, ty, evidence */
                if (strcmp(field, "expr") == 0) return v.v.e.data[0];
                if (strcmp(field, "ty") == 0) return v.v.e.data[1];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[2];
            } else if (var == 32) { /* Unsafe: body, ty, evidence */
                if (strcmp(field, "body") == 0) return v.v.e.data[0];
                if (strcmp(field, "ty") == 0) return v.v.e.data[1];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[2];
            } else if (var == 33) { /* Cast: expr, target_type, ty, evidence */
                if (strcmp(field, "expr") == 0) return v.v.e.data[0];
                if (strcmp(field, "target_type") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 34) { /* MacroExpansion: name, tokens, ty, evidence */
                if (strcmp(field, "name") == 0) return v.v.e.data[0];
                if (strcmp(field, "tokens") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 35) { /* FormatCall: format_string, args, ty, evidence */
                if (strcmp(field, "format_string") == 0) return v.v.e.data[0];
                if (strcmp(field, "args") == 0) return v.v.e.data[1];
                if (strcmp(field, "ty") == 0) return v.v.e.data[2];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[3];
            } else if (var == 36) { /* Try: expr, ty, evidence */
                if (strcmp(field, "expr") == 0) return v.v.e.data[0];
                if (strcmp(field, "ty") == 0) return v.v.e.data[1];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[2];
            } else if (var == 37) { /* Range: start, end, inclusive, ty, evidence */
                if (strcmp(field, "start") == 0) return v.v.e.data[0];
                if (strcmp(field, "end") == 0) return v.v.e.data[1];
                if (strcmp(field, "inclusive") == 0) return v.v.e.data[2];
                if (strcmp(field, "ty") == 0) return v.v.e.data[3];
                if (strcmp(field, "evidence") == 0) return v.v.e.data[4];
            }
        } else if (eid == 0xDEAD0002U) {  /* EXPR_ENUM_ID - Expr enum */
            if (var == 47) { /* Macro: path, tokens */
                if (strcmp(field, "path") == 0) return v.v.e.data[0];
                if (strcmp(field, "tokens") == 0) return v.v.e.data[1];
            } else if (var == 1) { /* Path: just the path */
                if (strcmp(field, "path") == 0 || strcmp(field, "0") == 0) return v.v.e.data[0];
            } else if (var == 2) { /* Binary: left, op, right */
                if (strcmp(field, "left") == 0) return v.v.e.data[0];
                if (strcmp(field, "op") == 0) return v.v.e.data[1];
                if (strcmp(field, "right") == 0) return v.v.e.data[2];
            } else if (var == 3) { /* Unary: op, expr */
                if (strcmp(field, "op") == 0) return v.v.e.data[0];
                if (strcmp(field, "expr") == 0) return v.v.e.data[1];
            } else if (var == 7) { /* Call: func, args */
                if (strcmp(field, "func") == 0) return v.v.e.data[0];
                if (strcmp(field, "args") == 0) return v.v.e.data[1];
            } else if (var == 8) { /* MethodCall: receiver, method, type_args, args */
                if (strcmp(field, "receiver") == 0) return v.v.e.data[0];
                if (strcmp(field, "method") == 0) return v.v.e.data[1];
                if (strcmp(field, "type_args") == 0) return v.v.e.data[2];
                if (strcmp(field, "args") == 0) return v.v.e.data[3];
            } else if (var == 9) { /* Field: expr, field */
                if (strcmp(field, "expr") == 0) return v.v.e.data[0];
                if (strcmp(field, "field") == 0) return v.v.e.data[1];
            } else if (var == 10) { /* Index: expr, index */
                if (strcmp(field, "expr") == 0) return v.v.e.data[0];
                if (strcmp(field, "index") == 0) return v.v.e.data[1];
            } else if (var == 13) { /* Struct: path, fields, rest */
                if (strcmp(field, "path") == 0) return v.v.e.data[0];
                if (strcmp(field, "fields") == 0) return v.v.e.data[1];
                if (strcmp(field, "rest") == 0) return v.v.e.data[2];
            }
            /* Fallback for Expr variants: try positional access */
            if (v.v.e.field_count > 0) {
                /* For single-field variants, return data[0] */
                if (v.v.e.field_count == 1) return v.v.e.data[0];
            }
        }
        /* Fallback for any enum: try common field names at typical positions */
        if (strcmp(field, "evidence") == 0 && v.v.e.field_count > 0) return v.v.e.data[v.v.e.field_count - 1];
        if (strcmp(field, "ty") == 0 && v.v.e.field_count > 1) return v.v.e.data[v.v.e.field_count - 2];
        /* For any other enum, try generic positional access */
        return sigil_null();  /* Field not found in enum */
    }
    \2''',
    content)

