# FIX: lower_expr also needs to dereference TAG_REF (Box) before pattern matching
# Also add global call counter to prevent infinite loops
content = re.sub(
    r'(SigilValue sigil_lower_expr\(SigilValue ctx, SigilValue expr\) \{\s*)'
    r'(SigilValue params = sigil_null\(\); /\* function-level params \*/\s*)'
    r'(SigilValue _t0 = expr;)',
    r'''\1/* Global call counter to prevent infinite loops in lowering */
    static int lower_call_count = 0;
    lower_call_count++;
    if (lower_call_count > 1000) {
        lower_call_count = 0;
        return sigil_unit(); /* Bail out - too many recursive calls */
    }
    \2/* Dereference Box (TAG_REF) before pattern matching */
    while (expr.tag == TAG_REF && expr.v.ptr) {
        expr = *((SigilValue*)expr.v.ptr);
    }
    /* Handle Expr::Unsafe specially - variant 30: just lower the inner block */
    /* Expr enum: ... Unsafe(Block) = 30 ... */
    #define EXPR_UNSAFE_VARIANT 30
    if (expr.tag == TAG_ENUM && expr.v.e.variant == EXPR_UNSAFE_VARIANT && expr.v.e.field_count > 0 && expr.v.e.data != NULL) {
        /* Unsafe variant has: data[0] = Block */
        SigilValue inner_block = expr.v.e.data[0];
        return sigil_lower_block(ctx, inner_block);
    }
    \3''',
    content)

