# FIX: emit_operation needs proper IrOperation variant checks
# The match on IrOperation generates if ((1)) instead of proper enum variant checks
# This causes ALL ops to fall into the first (Literal) branch

# First, add TAG_REF dereferencing at the start of emit_operation (body is in a Box)
# Also add explicit Block handling since the pattern matching doesn't work correctly
content = re.sub(
    r'(SigilValue sigil_CodeGen____emit_operation\(SigilValue\* self, SigilValue op\) \{\s*)'
    r'(SigilValue params = sigil_null\(\); /\* function-level params \*/)',
    r'''\1/* Dereference Box (TAG_REF) before pattern matching */
    while (op.tag == TAG_REF && op.v.ptr) {
        op = *((SigilValue*)op.v.ptr);
    }
    fprintf(stderr, "[DEBUG emit_operation] op.tag=%d (TAG_ENUM=%d, TAG_STRUCT=%d)\\n", op.tag, TAG_ENUM, TAG_STRUCT);
    if (op.tag == TAG_STRUCT) {
        SigilStruct* s = (SigilStruct*)op.v.ptr;
        if (s && s->name) fprintf(stderr, "[DEBUG emit_operation] struct name=%s\\n", s->name);
    }
    /* Handle IrOperation::Block specially - pattern matching is broken for enum struct variants */
    if (op.tag == TAG_ENUM && op.v.e.enum_id == IROPERATION_ENUM_ID && op.v.e.variant == IROPERATION_BLOCK) {
        fprintf(stderr, "[DEBUG Block] entering Block handler\\n");
        fflush(stderr);
        /* Enum data: data[0] = statements, data[1] = ty, data[2] = evidence */
        SigilValue statements = op.v.e.data[0];
        SigilValue last_result = sigil_string("sigil_unit()");
        size_t n = sigil_arr_len(statements);
        fprintf(stderr, "[DEBUG Block] n=%zu statements\\n", n);
        fflush(stderr);
        for (size_t i = 0; i < n; i++) {
            SigilValue stmt = statements.v.arr.data[i];
            fprintf(stderr, "[DEBUG Block] processing stmt[%zu], tag=%d\\n", i, stmt.tag);
            fflush(stderr);
            SigilValue result = sigil_CodeGen____emit_operation(self, stmt);
            fprintf(stderr, "[DEBUG Block] stmt[%zu] result.tag=%d\\n", i, result.tag);
            if (result.tag == TAG_STRING && result.v.s) {
                fprintf(stderr, "[DEBUG Block] stmt[%zu] result=%s\\n", i, result.v.s);
            }
            fflush(stderr);
            if (i == n - 1) {
                last_result = result;
            } else {
                /* Emit non-final statements as side effects */
                if (result.tag == TAG_STRING && result.v.s && strlen(result.v.s) > 0 && strcmp(result.v.s, "sigil_unit()") != 0) {
                    sigil_CodeGen____line(self, sigil_format("{};", result));
                }
            }
        }
        fprintf(stderr, "[DEBUG Block] returning last_result.tag=%d\\n", last_result.tag);
        if (last_result.tag == TAG_STRING && last_result.v.s) {
            fprintf(stderr, "[DEBUG Block] returning=%s\\n", last_result.v.s);
        }
        fflush(stderr);
        return last_result;
    }
    \2''',
    content)

print("Fixed emit_operation: Added TAG_REF dereference and Block handling")

# Add IrOperation::StructInit special handling (similar to Block)
# StructInit uses TAG_STRUCT format, not TAG_ENUM, so needs different handling
struct_init_handler = '''
    /* Handle IrOperation::StructInit specially - it uses TAG_STRUCT format */
    if (op.tag == TAG_STRUCT && op.v.ptr) {
        SigilStruct* s = (SigilStruct*)op.v.ptr;
        if (s && s->name && strcmp(s->name, "IrOperation::StructInit") == 0) {
            /* Fields: name, fields, rest, ty, evidence */
            SigilValue name = sigil_struct_field(op, "name");
            SigilValue fields = sigil_struct_field(op, "fields");
            SigilValue evidence = sigil_struct_field(op, "evidence");

            /* Generate struct initialization */
            SigilValue temp = sigil_CodeGen____fresh_temp(self);
            size_t n = sigil_arr_len(fields);

            /* Emit values array */
            sigil_CodeGen____line(self, sigil_format("SigilValue {}__values[{}];", temp, n > 0 ? sigil_int(n) : sigil_int(1)));

            /* Build field names and emit values */
            SigilValue field_names_arr = sigil_array(n);
            for (size_t i = 0; i < n; i++) {
                SigilValue field = fields.v.arr.data[i];
                /* field is a tuple (field_name, field_value) */
                SigilValue field_name = field.v.arr.data[0];
                SigilValue field_value = field.v.arr.data[1];

                /* Quote the field name */
                field_names_arr.v.arr.data[i] = sigil_format("\\"{}\\"", field_name);

                /* Emit the field value */
                SigilValue val = sigil_CodeGen____emit_operation(self, field_value);
                sigil_CodeGen____line(self, sigil_format("{}__values[{}] = {};", temp, sigil_int(i), val));
            }

            /* Join field names */
            SigilValue field_names_str = sigil_join(field_names_arr, sigil_string(", "));

            /* Emit field names array */
            sigil_CodeGen____line(self, sigil_format("static const char* {}__names[{}] = {{ {} }};",
                temp, n > 0 ? sigil_int(n) : sigil_int(1), field_names_str));

            /* Create struct value */
            fprintf(stderr, "[DEBUG StructInit] Creating result with name=%s, temp tag=%d\\n",
                name.tag == TAG_STRING ? name.v.s : "(not string)", temp.tag);
            fflush(stderr);

            SigilValue result = sigil_format("sigil_struct(\\\"{}\\\", {}__names, {}__values, {})",
                name, temp, temp, sigil_int(n));

            fprintf(stderr, "[DEBUG StructInit] result.tag=%d\\n", result.tag);
            if (result.tag == TAG_STRING && result.v.s) {
                fprintf(stderr, "[DEBUG StructInit] result=%s\\n", result.v.s);
            }
            fflush(stderr);

            SigilValue final_result = sigil_CodeGen____with_evidence((*self), result, evidence);
            fprintf(stderr, "[DEBUG StructInit] final_result.tag=%d\\n", final_result.tag);
            if (final_result.tag == TAG_STRING && final_result.v.s) {
                fprintf(stderr, "[DEBUG StructInit] final_result=%s\\n", final_result.v.s);
            }
            fflush(stderr);
            return final_result;
        }
    }
'''
content = content.replace(
    '/* Handle IrOperation::Block specially',
    struct_init_handler + '\n    /* Handle IrOperation::Block specially')

print("Added IrOperation::StructInit special handler")

