# FIX: with_evidence function checks for TAG_ENUM but IrEvidence____Known is TAG_INT
# Update the check to handle both TAG_ENUM and TAG_INT evidence values
content = re.sub(
    r'(/\* Function: CodeGen::with_evidence \*/\s*)'
    r'SigilValue sigil_CodeGen____with_evidence\(SigilValue self, SigilValue expr, SigilValue ev\) \{\s*'
    r'SigilValue _t0 = ev;\s*'
    r'SigilValue _t1;\s*'
    r'if \(\(_t0\.tag == TAG_ENUM && _t0\.v\.e\.enum_id == IREVIDENCE_ENUM_ID && _t0\.v\.e\.variant == IREVIDENCE_KNOWN\)\) \{\s*'
    r'_t1 = sigil_bool\(true\);\s*'
    r'\} else if \(1\) \{\s*'
    r'_t1 = sigil_bool\(false\);\s*'
    r'\} else \{\s*'
    r'_t1 = sigil_unit\(\);\s*'
    r'\}\s*'
    r'SigilValue is_known = _t1;',
    r'''\1SigilValue sigil_CodeGen____with_evidence(SigilValue self, SigilValue expr, SigilValue ev) {
    /* Fixed: Check for both TAG_ENUM and TAG_INT evidence values */
    /* IrEvidence____Known etc. are defined as TAG_INT with v.i = SIGIL_KNOWN/UNCERTAIN/etc. */
    SigilValue _t0 = ev;
    SigilValue _t1;
    if ((_t0.tag == TAG_ENUM && _t0.v.e.enum_id == IREVIDENCE_ENUM_ID && _t0.v.e.variant == IREVIDENCE_KNOWN) ||
        (_t0.tag == TAG_INT && _t0.v.i == SIGIL_KNOWN)) {
        _t1 = sigil_bool(true);
    } else {
        _t1 = sigil_bool(false);
    }
    SigilValue is_known = _t1;''',
    content)

