# Add helper function to check struct variant names
# Must be placed after SigilStruct typedef but before lower_expr
# Insert it right after the SigilStruct typedef line
# NOTE: Only add if not already present (codegen now emits this function)
helper_func = '''
/* Helper function to check if a value is a TAG_STRUCT with a specific name */
/* FIXED: Also handles TAG_REF by dereferencing first */
static inline int sigil_is_struct_variant(SigilValue v, const char* name) {
    /* Dereference TAG_REF if needed */
    while (v.tag == TAG_REF && v.v.ptr) {
        v = *((SigilValue*)v.v.ptr);
    }
    if (v.tag != TAG_STRUCT) return 0;
    SigilStruct* s = (SigilStruct*)v.v.ptr;
    if (!s || !s->name) return 0;
    return strcmp(s->name, name) == 0;
}
'''

# Only add if not already present in the generated code
if 'int sigil_is_struct_variant(SigilValue v, const char* name)' not in content:
    # Insert after the SigilStruct typedef (which is followed by sigil_struct function)
    content = re.sub(
        r'(typedef struct \{ const char\* name; const char\*\* field_names; SigilValue\* field_values; size_t num_fields; \} SigilStruct;)',
        r'\1\n' + helper_func,
        content,
        count=1)
    print("Added sigil_is_struct_variant helper function")
else:
    print("sigil_is_struct_variant already present in generated code (from emit_builtin_impls)")

# FIX: Replace stub sigil_join with proper implementation
# The stub just returns empty string, which breaks all path name joining
sigil_join_impl = '''
#include <signal.h>
#include <setjmp.h>
static sigjmp_buf sigil_join_jmp;
static volatile sig_atomic_t sigil_join_in_strlen = 0;
static void sigil_join_sigsegv_handler(int sig) {
    if (sigil_join_in_strlen) {
        siglongjmp(sigil_join_jmp, 1);
    }
    /* Re-raise for other segfaults */
    signal(SIGSEGV, SIG_DFL);
    raise(SIGSEGV);
}

static inline SigilValue sigil_join(SigilValue v, SigilValue sep) {
    if (v.tag != TAG_ARRAY || !v.v.arr.data) return sigil_string("");
    size_t arr_len = sigil_arr_len(v);
    if (arr_len == 0) return sigil_string("");
    /* Sanity check for unreasonable array lengths */
    if (arr_len > 10000) {
        fprintf(stderr, "[sigil_join] WARNING: arr_len=%zu seems too large\\n", arr_len);
        return sigil_string("");
    }

    /* Install signal handler for safe strlen */
    void (*old_handler)(int) = signal(SIGSEGV, sigil_join_sigsegv_handler);

    /* Calculate total length needed */
    size_t total_len = 0;
    const char* sep_str = (sep.tag == TAG_STRING && sep.v.s) ? sep.v.s : "";
    size_t sep_len = strlen(sep_str);

    for (size_t i = 0; i < arr_len; i++) {
        SigilValue item = v.v.arr.data[i];
        /* Skip non-string items */
        if (item.tag != TAG_STRING) continue;
        if (!item.v.s) continue;
        /* Try strlen with signal handling */
        sigil_join_in_strlen = 1;
        if (sigsetjmp(sigil_join_jmp, 1) == 0) {
            total_len += strlen(item.v.s);
        } else {
            /* Caught segfault - skip this item */
            fprintf(stderr, "[sigil_join] CAUGHT segfault on item[%zu] ptr=%p\\n", i, (void*)item.v.s);
            v.v.arr.data[i].v.s = NULL; /* Mark as invalid */
        }
        sigil_join_in_strlen = 0;
        if (i > 0) total_len += sep_len;
    }

    /* Allocate and build result string */
    char* result = (char*)malloc(total_len + 1);
    if (!result) { signal(SIGSEGV, old_handler); return sigil_string(""); }
    char* p = result;
    int first = 1;
    for (size_t i = 0; i < arr_len; i++) {
        SigilValue item = v.v.arr.data[i];
        if (item.tag != TAG_STRING) continue;
        if (!item.v.s) continue;
        if (!first) {
            memcpy(p, sep_str, sep_len);
            p += sep_len;
        }
        first = 0;
        sigil_join_in_strlen = 1;
        if (sigsetjmp(sigil_join_jmp, 1) == 0) {
            size_t len = strlen(item.v.s);
            memcpy(p, item.v.s, len);
            p += len;
        }
        sigil_join_in_strlen = 0;
    }
    *p = '\\0';
    signal(SIGSEGV, old_handler);
    return sigil_string(result);
}'''
content = re.sub(
    r'static inline SigilValue sigil_join\(SigilValue v, SigilValue sep\) \{ return sigil_string\(""\); \}',
    sigil_join_impl,
    content)
print("Fixed sigil_join implementation")

# FIX: Array iteration pattern - when copying elements from one array to another,
# the generated code uses stale .v.arr.len instead of sigil_arr_len()
# This happens in patterns like: SigilValue _t3 = sigil_array(_t2.v.arr.len);
# We need to replace _t2.v.arr.len with sigil_arr_len(_t2) in sigil_array calls
# that are followed by loops using sigil_arr_len on the same source array

# Fix the specific pattern in lower_expr for Expr::Path segment name extraction
# Pattern: SigilValue _t3 = sigil_array(_t2.v.arr.len);
#          for (size_t _t4 = 0; _t4 < sigil_arr_len(_t2); ...
content = re.sub(
    r'SigilValue _t3 = sigil_array\(_t2\.v\.arr\.len\);',
    r'SigilValue _t3 = sigil_array(sigil_arr_len(_t2));',
    content)
print("Fixed array creation to use sigil_arr_len")

# Fix ALL sigil_array calls that use .v.arr.len - replace with sigil_arr_len
# This is a more general fix for the pattern where generated code uses stale .v.arr.len
content = re.sub(
    r'sigil_array\((_t\d+)\.v\.arr\.len\)',
    r'sigil_array(sigil_arr_len(\1))',
    content)

# Also fix for named variables like 'fields', 'elements', 'gs', etc.
content = re.sub(
    r'sigil_array\((fields|elements|items|args|statements|segments|gs|params|variants|members|stmts)\.v\.arr\.len\)',
    r'sigil_array(sigil_arr_len(\1))',
    content)

# Fix any remaining .v.arr.len direct access in sigil_array calls
content = re.sub(
    r'sigil_array\(([a-zA-Z_][a-zA-Z0-9_]*)\.v\.arr\.len\)',
    r'sigil_array(sigil_arr_len(\1))',
    content)

# Also fix for loop condition patterns like 'for (... < gs.v.arr.len; ...'
content = re.sub(
    r'< ([a-zA-Z_][a-zA-Z0-9_]*)\.v\.arr\.len;',
    r'< sigil_arr_len(\1);',
    content)

print("Fixed all sigil_array and loop length checks to use sigil_arr_len")

# Fix sigil_iter(...).v.arr.len patterns in loop conditions
# These are very common and return arrays with stale .v.arr.len
content = re.sub(
    r'< sigil_iter\(([^)]+)\)\.v\.arr\.len;',
    r'< sigil_arr_len(sigil_iter(\1));',
    content)

# Fix sigil_enumerate(sigil_iter(...)).v.arr.len patterns
content = re.sub(
    r'< sigil_enumerate\(sigil_iter\(([^)]+)\)\)\.v\.arr\.len;',
    r'< sigil_arr_len(sigil_enumerate(sigil_iter(\1)));',
    content)

# Fix sigil_String____iter/chars(...).v.arr.len patterns
content = re.sub(
    r'< sigil_String____iter\(([^)]+)\)\.v\.arr\.len;',
    r'< sigil_arr_len(sigil_String____iter(\1));',
    content)
content = re.sub(
    r'< sigil_String____chars\(([^)]+)\)\.v\.arr\.len;',
    r'< sigil_arr_len(sigil_String____chars(\1));',
    content)

print("Fixed sigil_iter and enumerate patterns in loops")

