# Add struct-based handling for IrOperation::Literal in emit_operation
# The existing code only handles it as TAG_ENUM but it gets created as sigil_struct
content = re.sub(
    r'(\s*SigilValue params = sigil_null\(\); /\* function-level params \*/\s*'
    r'SigilValue _t0 = op;\s*'
    r'SigilValue _t1;\s*)'
    r'if \(\(op\.tag == TAG_ENUM && op\.v\.e\.enum_id == IROPERATION_ENUM_ID && op\.v\.e\.variant == IROPERATION_LITERAL\)\)',
    r'''\1/* Handle IrOperation::Literal as struct variant (sometimes created as sigil_struct) */
    if ((sigil_is_struct_variant(op, "IrOperation::Literal"))) {
        SigilValue value = sigil_struct_field(op, "value");
        SigilValue evidence = sigil_struct_field(op, "evidence");
        fprintf(stderr, "[DEBUG Literal struct] value.tag=%d\\n", value.tag);
        SigilValue val;
        if ((sigil_is_struct_variant(value, "LiteralValue::Int"))) {
            SigilValue n = sigil_struct_field(value, "0");
            val = sigil_format("sigil_int(%sLL)", n);
        } else if ((sigil_is_struct_variant(value, "LiteralValue::Float"))) {
            SigilValue f = sigil_struct_field(value, "0");
            val = sigil_format("sigil_float(%s)", f);
        } else if ((sigil_is_struct_variant(value, "LiteralValue::Bool"))) {
            SigilValue b = sigil_struct_field(value, "0");
            val = sigil_truthy(b) ? sigil_string("sigil_bool(true)") : sigil_string("sigil_bool(false)");
        } else if ((sigil_is_struct_variant(value, "LiteralValue::Char"))) {
            SigilValue c = sigil_struct_field(value, "0");
            val = sigil_format("sigil_char('%s')", sigil_CodeGen____escape_char((*self), c));
        } else if ((sigil_is_struct_variant(value, "LiteralValue::String"))) {
            SigilValue s = sigil_struct_field(value, "0");
            val = sigil_format("sigil_string(\\"%s\\")", sigil_CodeGen____escape_string((*self), s));
        } else if ((sigil_is_struct_variant(value, "LiteralValue::Null"))) {
            val = sigil_string("sigil_null()");
        } else if (value.tag == TAG_ENUM && value.v.e.enum_id == LITERALVALUE_ENUM_ID) {
            /* Handle enum-based LiteralValue */
            if (value.v.e.variant == LITERALVALUE_INT) {
                SigilValue n = sigil_enum_data(value);
                val = sigil_format("sigil_int(%sLL)", n);
            } else if (value.v.e.variant == LITERALVALUE_FLOAT) {
                SigilValue f = sigil_enum_data(value);
                val = sigil_format("sigil_float(%s)", f);
            } else if (value.v.e.variant == LITERALVALUE_BOOL) {
                SigilValue b = sigil_enum_data(value);
                val = sigil_truthy(b) ? sigil_string("sigil_bool(true)") : sigil_string("sigil_bool(false)");
            } else if (value.v.e.variant == LITERALVALUE_CHAR) {
                SigilValue c = sigil_enum_data(value);
                val = sigil_format("sigil_char('%s')", sigil_CodeGen____escape_char((*self), c));
            } else if (value.v.e.variant == LITERALVALUE_STRING) {
                SigilValue s = sigil_enum_data(value);
                val = sigil_format("sigil_string(\\"%s\\")", sigil_CodeGen____escape_string((*self), s));
            } else if (value.v.e.variant == LITERALVALUE_NULL) {
                val = sigil_string("sigil_null()");
            } else {
                val = sigil_string("sigil_unit()");
            }
        } else {
            fprintf(stderr, "[DEBUG Literal] Unknown value type tag=%d\\n", value.tag);
            val = sigil_string("sigil_unit()");
        }
        _t1 = sigil_CodeGen____with_evidence((*self), val, evidence);
    } else if ((op.tag == TAG_ENUM && op.v.e.enum_id == IROPERATION_ENUM_ID && op.v.e.variant == IROPERATION_LITERAL))''',
    content)
print("Added IrOperation::Literal struct variant handling")

