# FIX CRITICAL: sigil_Vec____push returns modified array but result is discarded
# This causes segfaults when the array is reallocated but the original variable isn't updated
# Pattern: standalone sigil_Vec____push(VAR, EXPR); should become VAR = sigil_Vec____push(VAR, EXPR);
# Match lines like:
#   sigil_Vec____push(args, ...)
#   sigil_Vec____push(fields, ...)
# But NOT lines that already have assignment or are function definitions

# List of known variable names used with Vec::push
vec_vars = ['args', 'fields', 'variants', 'trees', 'state', 'params', 'predicates',
            'types', 'segments', 'bounds', 'exprs', 'arms', 'patterns', 'attrs',
            'items', 'stmts', 'modules', 'statements', 'errors', 'members',
            # Added for typeck.sg Vec::push fixes
            'arm_types', 'seen', 'ir_elements', 'file_paths', 'asts', 'conditions',
            'field_names_parts', 'capture_names', 'param_names', 'all_args',
            # Additional variables
            'errs', 'handlers', 'operations',
            # Added for lower.sg find_free_variables
            'result', 'free']

for var in vec_vars:
    # Match: leading whitespace + sigil_Vec____push(VAR, ...) + semicolon
    # This inserts VAR = before the call, creating chained assignment if there's already one
    # e.g., _t0 = sigil_Vec____push(attrs, ...) becomes _t0 = attrs = sigil_Vec____push(attrs, ...)
    pattern = r'(\s+)sigil_Vec____push\(' + var + r',([^;]+);'
    replacement = r'\1' + var + r' = sigil_Vec____push(' + var + r',\2;'
    content = re.sub(pattern, replacement, content)

    # Also fix: _tN = sigil_Vec____push(VAR, ...) -> VAR = sigil_Vec____push(VAR, ...)
    # This handles cases where the push result is assigned to a temp instead of the array
    pattern2 = r'(\s+)_t\d+ = sigil_Vec____push\(' + var + r',([^;]+);'
    replacement2 = r'\1' + var + r' = sigil_Vec____push(' + var + r',\2;'
    content = re.sub(pattern2, replacement2, content)

print("Fixed sigil_Vec____push to assign results back to variables")

# FIX: Vec::push on struct field temporaries using in-place mutation
# Pattern: SigilValue _tN = sigil_struct_field(STRUCT, "FIELD");
#          sigil_Vec____push(_tN, ARGS);
# Transform to:
#          SigilValue _tN = sigil_struct_field(STRUCT, "FIELD");
#          sigil_Vec____push_inplace(&_tN, ARGS);
#          sigil_struct_set_field(&STRUCT, "FIELD", _tN);
def fix_struct_field_vec_push_inplace(content):
    lines = content.split('\n')
    result = []
    i = 0
    fixed_count = 0
    # Build a map of temp vars to their struct field sources
    temp_to_field = {}  # {temp_var: (struct_expr, field_name)}

    while i < len(lines):
        line = lines[i]
        # Track struct_field assignments: SigilValue _tN = sigil_struct_field(STRUCT, "FIELD");
        struct_field_match = re.match(r'^(\s*)SigilValue (_t\d+) = sigil_struct_field\(([^,]+),\s*"([^"]+)"\);', line)
        if struct_field_match:
            temp_var = struct_field_match.group(2)
            struct_expr = struct_field_match.group(3)
            field_name = struct_field_match.group(4)
            temp_to_field[temp_var] = (struct_expr, field_name)
            result.append(line)
            i += 1
            continue

        # Look for standalone Vec::push on tracked temp vars
        push_match = re.match(r'^(\s*)sigil_Vec____push\((_t\d+),([^;]+);', line)
        if push_match:
            push_indent = push_match.group(1)
            temp_var = push_match.group(2)
            push_args = push_match.group(3)

            if temp_var in temp_to_field:
                struct_expr, field_name = temp_to_field[temp_var]
                # Transform to in-place push
                result.append(f'{push_indent}sigil_Vec____push_inplace(&{temp_var},{push_args};')
                # Add set_field call to write back to struct
                # Handle (*self) -> self for pointer
                if struct_expr.startswith('(*') and struct_expr.endswith(')'):
                    struct_ptr = struct_expr[2:-1]  # Extract 'self' from '(*self)'
                else:
                    struct_ptr = '&' + struct_expr
                result.append(f'{push_indent}sigil_struct_set_field({struct_ptr}, "{field_name}", {temp_var});')
                fixed_count += 1
                i += 1
                continue

        # Clear temp_to_field on function boundaries (closing brace at low indent)
        if line.strip() == '}' and len(line) - len(line.lstrip()) <= 4:
            temp_to_field.clear()

        result.append(line)
        i += 1
    print(f"Fixed {fixed_count} struct field Vec::push calls with in-place mutation")
    return '\n'.join(result)

content = fix_struct_field_vec_push_inplace(content)

# FIX: sigil_display buffer overflow for TAG_STRUCT
# The generated code allocates only 32 bytes per field which is not enough for nested structs
# Fix by increasing buffer allocation and using dynamic string building
# There are MANY copies of sigil_display - we need to fix them all
# Use a loop to replace all instances

old_pattern = (
    r'case TAG_STRUCT: \{\s*'
    r'SigilStruct\* s = \(SigilStruct\*\)v\.v\.ptr;\s*'
    r'if \(!s\) return sigil_string\("<null-struct>"\);\s*'
    r'size_t total = strlen\(s->name \? s->name : "\?"\) \+ 4;\s*'
    r'for \(size_t i = 0; i < s->num_fields; i\+\+\) \{\s*'
    r'total \+= strlen\(s->field_names\[i\]\) \+ 32;\s*'
    r'\}\s*'
    r'char\* out = \(char\*\)malloc\(total\);\s*'
    r'char\* p = out;\s*'
    r'p \+= sprintf\(p, "%s \{ ", s->name \? s->name : "\?"\);\s*'
    r'for \(size_t i = 0; i < s->num_fields; i\+\+\) \{\s*'
    r'if \(i > 0\) p \+= sprintf\(p, ", "\);\s*'
    r'SigilValue fv = sigil_display\(s->field_values\[i\]\);\s*'
    r'p \+= sprintf\(p, "%s: %s", s->field_names\[i\], fv\.tag == TAG_STRING && fv\.v\.s \? fv\.v\.s : "\?"\);\s*'
    r'\}\s*'
    r'sprintf\(p, " \}"\);\s*'
    r'return sigil_string\(out\);\s*'
    r'\}'
)

new_code = r'''case TAG_STRUCT: {
            SigilStruct* s = (SigilStruct*)v.v.ptr;
            if (!s) return sigil_string("<null-struct>");
            /* Calculate actual size needed by first getting all field values */
            size_t total = strlen(s->name ? s->name : "?") + 8;
            SigilValue* fvs = (SigilValue*)malloc(s->num_fields * sizeof(SigilValue));
            for (size_t i = 0; i < s->num_fields; i++) {
                fvs[i] = sigil_display_impl(s->field_values[i], depth + 1);
                total += strlen(s->field_names[i]) + 8;
                if (fvs[i].tag == TAG_STRING && fvs[i].v.s) total += strlen(fvs[i].v.s);
            }
            char* out = (char*)malloc(total);
            char* p = out;
            int n = snprintf(p, total, "%s { ", s->name ? s->name : "?");
            p += n; total -= n;
            for (size_t i = 0; i < s->num_fields && total > 4; i++) {
                if (i > 0) { n = snprintf(p, total, ", "); p += n; total -= n; }
                n = snprintf(p, total, "%s: %s", s->field_names[i], fvs[i].tag == TAG_STRING && fvs[i].v.s ? fvs[i].v.s : "?");
                p += n; total -= n;
            }
            snprintf(p, total, " }");
            free(fvs);
            return sigil_string(out);
        }'''

# Replace ALL instances
count = 0
while True:
    new_content, n = re.subn(old_pattern, new_code, content, count=1, flags=re.DOTALL)
    if n == 0:
        break
    content = new_content
    count += 1

print(f"Fixed sigil_display TAG_STRUCT buffer overflow ({count} instances)")

# FIX: sigil_display buffer overflow for TAG_ARRAY too
# Same issue - allocates only 32 bytes per element
old_array_pattern = (
    r'case TAG_ARRAY: \{\s*'
    r'size_t len = v\.v\.arr\.len;\s*'
    r'if \(len == 0\) return sigil_string\("\[\]"\);\s*'
    r'size_t total = 3 \+ len \* 32;\s*'
    r'char\* out = \(char\*\)malloc\(total\);\s*'
    r'char\* p = out;\s*'
    r'\*p\+\+ = \'\[\'\;\s*'
    r'for \(size_t i = 0; i < len; i\+\+\) \{\s*'
    r'if \(i > 0\) \{ \*p\+\+ = \',\'; \*p\+\+ = \' \'; \}\s*'
    r'SigilValue ev = sigil_display\(v\.v\.arr\.data\[i\]\);\s*'
    r'if \(ev\.tag == TAG_STRING && ev\.v\.s\) \{ size_t n = strlen\(ev\.v\.s\); memcpy\(p, ev\.v\.s, n\); p \+= n; \}\s*'
    r'\}\s*'
    r'\*p\+\+ = \'\]\'; \*p = 0;\s*'
    r'return sigil_string\(out\);\s*'
    r'\}'
)

new_array_code = r'''case TAG_ARRAY: {
            size_t len = v.v.arr.len;
            if (len == 0) return sigil_string("[]");
            /* Calculate actual size by getting all element displays first */
            SigilValue* evs = (SigilValue*)malloc(len * sizeof(SigilValue));
            size_t total = 3;
            for (size_t i = 0; i < len; i++) {
                evs[i] = sigil_display_impl(v.v.arr.data[i], depth + 1);
                if (evs[i].tag == TAG_STRING && evs[i].v.s) total += strlen(evs[i].v.s);
                if (i > 0) total += 2; /* ", " */
            }
            char* out = (char*)malloc(total);
            char* p = out;
            *p++ = '[';
            for (size_t i = 0; i < len; i++) {
                if (i > 0) { *p++ = ','; *p++ = ' '; }
                if (evs[i].tag == TAG_STRING && evs[i].v.s) {
                    size_t n = strlen(evs[i].v.s);
                    memcpy(p, evs[i].v.s, n);
                    p += n;
                }
            }
            *p++ = ']'; *p = 0;
            free(evs);
            return sigil_string(out);
        }'''

count2 = 0
while True:
    new_content, n = re.subn(old_array_pattern, new_array_code, content, count=1, flags=re.DOTALL)
    if n == 0:
        break
    content = new_content
    count2 += 1

print(f"Fixed sigil_display TAG_ARRAY buffer overflow ({count2} instances)")

# FIX: convert_type receives TAG_STRUCT when it should receive TAG_ENUM
# This happens when TypeExpr is wrapped in Spanned<TypeExpr> or Box<TypeExpr>
# Add unwrapping logic at the start of convert_type
content = re.sub(
    r'/\* Function: TypeChecker::convert_type \*/\s*'
    r'SigilValue sigil_TypeChecker____convert_type\(SigilValue self, SigilValue ty\) \{\s*'
    r'SigilValue params = sigil_null\(\);',
    r'''/* Function: TypeChecker::convert_type */
SigilValue sigil_TypeChecker____convert_type(SigilValue self, SigilValue ty) {
    static int depth = 0;
    depth++;
    /* Debug output disabled for performance */
    if (depth > 200) { depth--; return sigil_Type____Var(sigil_TypeVar____new(sigil_int(0LL))); }
    /* FIX: Unwrap TAG_STRUCT/TAG_REF to get the actual TypeExpr */
    int unwrap_count = 0;
    while ((ty.tag == TAG_STRUCT || ty.tag == TAG_REF) && unwrap_count < 10) {
        unwrap_count++;
        if (ty.tag == TAG_REF && ty.v.ptr) {
            ty = *(SigilValue*)ty.v.ptr;
        } else if (ty.tag == TAG_STRUCT && ty.v.ptr) {
            SigilStruct* s = (SigilStruct*)ty.v.ptr;
            if (!s || s->num_fields == 0) break;
            /* Check if this is a TypeExpr::* struct - stop unwrapping, keep as struct */
            if (s->name && strncmp(s->name, "TypeExpr::", 10) == 0) {
                fprintf(stderr, "[convert_type] found TypeExpr struct: %s, keeping as-is\\n", s->name);
                break;
            }
            /* For Spanned<T>, the inner value is in "node" field */
            int found_node = 0;
            for (size_t i = 0; i < s->num_fields; i++) {
                if (s->field_names[i] && strcmp(s->field_names[i], "node") == 0) {
                    ty = s->field_values[i];
                    found_node = 1;
                    break;
                }
            }
            if (!found_node) {
                /* Not a Spanned and not TypeExpr - stop unwrapping */
                break;
            }
        } else {
            break;
        }
    }
    /* If we couldn't unwrap to TAG_ENUM or TypeExpr struct, return a fresh type variable */
    int is_typeexpr_struct = 0;
    if (ty.tag == TAG_STRUCT && ty.v.ptr) {
        SigilStruct* s = (SigilStruct*)ty.v.ptr;
        if (s->name && strncmp(s->name, "TypeExpr::", 10) == 0) {
            is_typeexpr_struct = 1;
        }
    }
    if (ty.tag != TAG_ENUM && ty.tag != TAG_NULL && !is_typeexpr_struct) {
        depth--;
        return sigil_Type____Var(sigil_TypeVar____new(sigil_int(0LL)));
    }
    SigilValue params = sigil_null();''',
    content, count=1)
print("Fixed convert_type to unwrap Spanned<TypeExpr> via node field")

# FIX: Add debug and null-check for TYPEEXPR_TUPLE handling in convert_type
content = re.sub(
