# FIX: Add unwrap logic to lower_type (same as convert_type)
content = re.sub(
    r'/\* Function: lower_type \*/\s*'
    r'SigilValue sigil_lower_type\(SigilValue ctx, SigilValue ty\) \{\s*'
    r'fprintf\(stderr, "\[DEBUG lower_type\] ty\.tag=%d\\n", ty\.tag\);\s*'
    r'fflush\(stderr\);\s*'
    r'SigilValue params = sigil_null\(\);',
    r'''/* Function: lower_type */
SigilValue sigil_lower_type(SigilValue ctx, SigilValue ty) {
    fprintf(stderr, "[DEBUG lower_type] ty.tag=%d\\n", ty.tag);
    fflush(stderr);
    /* FIX: Unwrap TAG_STRUCT/TAG_REF to get the actual TypeExpr */
    int unwrap_count = 0;
    while ((ty.tag == TAG_STRUCT || ty.tag == TAG_REF) && unwrap_count < 10) {
        unwrap_count++;
        if (ty.tag == TAG_REF && ty.v.ptr) {
            ty = *(SigilValue*)ty.v.ptr;
        } else if (ty.tag == TAG_STRUCT && ty.v.ptr) {
            SigilStruct* s = (SigilStruct*)ty.v.ptr;
            if (!s || s->num_fields == 0) break;
            /* Check if this is a TypeExpr::* struct - stop unwrapping, keep as struct */
            if (s->name && strncmp(s->name, "TypeExpr::", 10) == 0) {
                fprintf(stderr, "[lower_type] found TypeExpr struct: %s, keeping as-is\\n", s->name);
                break;
            }
            /* For Spanned<T>, the inner value is in "node" field */
            int found_node = 0;
            for (size_t i = 0; i < s->num_fields; i++) {
                if (s->field_names[i] && strcmp(s->field_names[i], "node") == 0) {
                    ty = s->field_values[i];
                    found_node = 1;
                    break;
                }
            }
            if (!found_node) {
                /* Not a Spanned and not TypeExpr - stop unwrapping */
                fprintf(stderr, "[lower_type] struct %s has no node field, stopping\\n", s->name ? s->name : "null");
                break;
            }
        } else {
            break;
        }
    }
    /* If we couldn't unwrap to TAG_ENUM or TypeExpr struct, return a unit type */
    int is_typeexpr_struct = 0;
    if (ty.tag == TAG_STRUCT && ty.v.ptr) {
        SigilStruct* s = (SigilStruct*)ty.v.ptr;
        if (s->name && strncmp(s->name, "TypeExpr::", 10) == 0) {
            is_typeexpr_struct = 1;
        }
    }
    if (ty.tag != TAG_ENUM && ty.tag != TAG_NULL && !is_typeexpr_struct) {
        fprintf(stderr, "[lower_type] couldn't unwrap ty.tag=%d, returning unit\\n", ty.tag);
        return sigil_struct("IrType::Unit", NULL, NULL, 0);
    }
    fprintf(stderr, "[lower_type] about to pattern match tag=%d\\n", ty.tag);
    SigilValue params = sigil_null();''',
    content, count=1)
print("Fixed lower_type: Added unwrap logic for TAG_STRUCT/TAG_REF")

