# FIX: Extend TypeExpr pattern matching to also check for struct variant names
# This handles cases where TypeExpr comes as TAG_STRUCT instead of TAG_ENUM
typeexpr_variants = [
    ("Path", 0), ("Reference", 1), ("Pointer", 2), ("Array", 3), ("Slice", 4),
    ("Tuple", 5), ("Function", 6), ("Evidential", 7), ("Cycle", 8), ("Simd", 9),
    ("Atomic", 10), ("Never", 11), ("Infer", 12)
]
for variant_name, variant_num in typeexpr_variants:
    old_pattern = rf'\(_t0\.tag == TAG_ENUM && _t0\.v\.e\.enum_id == TYPEEXPR_ENUM_ID && _t0\.v\.e\.variant == TYPEEXPR_{variant_name.upper()}\)'
    new_pattern = rf'((_t0.tag == TAG_ENUM && _t0.v.e.enum_id == TYPEEXPR_ENUM_ID && _t0.v.e.variant == TYPEEXPR_{variant_name.upper()}) || sigil_is_struct_variant(_t0, "TypeExpr::{variant_name}"))'
    content = content.replace(old_pattern.replace('\\', ''), new_pattern)
print("Extended TypeExpr pattern matching to check struct variant names")

