/* Helper to safely get inner value - dereferences TAG_REF, returns others directly */
static inline SigilValue sigil_unwrap_ref(SigilValue v) {
    if (v.tag == TAG_REF && v.v.ptr) {
        return *(SigilValue*)v.v.ptr;
    }
    return v;
}
'''
