# Add IrOperation::Field special handling (emit field access)
field_handler = '''
    /* Handle IrOperation::Field specially - emit struct field access */
    if (op.tag == TAG_STRUCT && op.v.ptr) {
        SigilStruct* s = (SigilStruct*)op.v.ptr;
        if (s && s->name && strcmp(s->name, "IrOperation::Field") == 0) {
            SigilValue expr = sigil_struct_field(op, "expr");
            SigilValue field = sigil_struct_field(op, "field");
            SigilValue evidence = sigil_struct_field(op, "evidence");

            /* Dereference Box<IrOperation> for expr */
            SigilValue actual_expr = (expr.tag == TAG_REF && expr.v.ptr) ? *(SigilValue*)expr.v.ptr : expr;

            /* Recursively emit the base expression */
            SigilValue base_code = sigil_CodeGen____emit_operation(self, actual_expr);

            /* Generate field access */
            SigilValue temp = sigil_CodeGen____fresh_temp(self);
            sigil_CodeGen____line(self, sigil_format("SigilValue {} = sigil_struct_field({}, \\\"{}\\\");", temp, base_code, field));

            return sigil_CodeGen____with_evidence((*self), temp, evidence);
        }
    }
'''
content = content.replace(
    '/* Handle IrOperation::StructInit specially',
    field_handler + '\n    /* Handle IrOperation::StructInit specially')
print("Added IrOperation::Field special handler")

# Add IrOperation::MethodCall special handling (emit method call)
methodcall_handler = '''
    /* Handle IrOperation::MethodCall specially - emit method call */
    if (op.tag == TAG_STRUCT && op.v.ptr) {
        SigilStruct* s = (SigilStruct*)op.v.ptr;
        if (s && s->name && strcmp(s->name, "IrOperation::MethodCall") == 0) {
            SigilValue receiver = sigil_struct_field(op, "receiver");
            SigilValue method = sigil_struct_field(op, "method");
            SigilValue args = sigil_struct_field(op, "args");
            SigilValue evidence = sigil_struct_field(op, "evidence");

            /* Dereference Box<IrOperation> for receiver */
            SigilValue actual_receiver = (receiver.tag == TAG_REF && receiver.v.ptr) ? *(SigilValue*)receiver.v.ptr : receiver;

            /* Emit receiver as first argument */
            SigilValue receiver_code = sigil_CodeGen____emit_operation(self, actual_receiver);

            /* Build argument list: receiver first, then args */
            SigilValue arg_codes = sigil_array(sigil_arr_len(args) + 1);
            arg_codes.v.arr.data[0] = receiver_code;

            for (size_t i = 0; i < sigil_arr_len(args); i++) {
                SigilValue arg = args.v.arr.data[i];
                SigilValue actual_arg = (arg.tag == TAG_REF && arg.v.ptr) ? *(SigilValue*)arg.v.ptr : arg;
                SigilValue arg_code = sigil_CodeGen____emit_operation(self, actual_arg);
                arg_codes.v.arr.data[i + 1] = arg_code;
            }

            SigilValue args_str = sigil_join(arg_codes, sigil_string(", "));

            /* Try to get receiver type from the receiver operation's ty field */
            /* NOTE: This often contains IrType::Infer (variant 15) because type resolution
             * during lowering relies on ctx.var_types which may not be fully populated.
             * This matches the source codegen.sg behavior which uses method name heuristics. */
            const char* receiver_type_name = NULL;
            SigilValue recv_ty = sigil_struct_field(actual_receiver, "ty");

            /* Handle TAG_ENUM - IrType is an enum, Named is variant 6 */
            /* IrType enum order: Primitive=0, Unit=1, Never=2, Array=3, Slice=4, Tuple=5, Named=6 */
            #define IRTYPE_NAMED_VARIANT 6
            if (recv_ty.tag == TAG_ENUM && recv_ty.v.e.variant == IRTYPE_NAMED_VARIANT && recv_ty.v.e.field_count > 0 && recv_ty.v.e.data != NULL) {
                /* Named variant has: data[0]=name (String), data[1]=generics (Array) */
                SigilValue name_field = recv_ty.v.e.data[0];
                if (name_field.tag == TAG_STRING && name_field.v.s != NULL) {
                    receiver_type_name = name_field.v.s;
                }
            }
            /* Also handle TAG_STRUCT case (for robustness) */
            else if (recv_ty.tag == TAG_STRUCT && recv_ty.v.ptr) {
                SigilStruct* ty_struct = (SigilStruct*)recv_ty.v.ptr;
                if (ty_struct->name && strcmp(ty_struct->name, "IrType::Named") == 0) {
                    SigilValue name_field = sigil_struct_field(recv_ty, "name");
                    if (name_field.tag == TAG_STRING) {
                        receiver_type_name = name_field.v.s;
                    }
                }
            }

            /* Use method name heuristics for type prefix (like source codegen.sg) */
            const char* method_str = method.tag == TAG_STRING ? method.v.s : "";
            const char* type_prefix = "";

            /* Map methods */
            if (strcmp(method_str, "get") == 0 || strcmp(method_str, "insert") == 0 ||
                strcmp(method_str, "contains_key") == 0 || strcmp(method_str, "remove") == 0) {
                type_prefix = "Map";
            }
            /* Vec methods */
            else if (strcmp(method_str, "push") == 0 || strcmp(method_str, "pop") == 0 ||
                     strcmp(method_str, "first") == 0 || strcmp(method_str, "last") == 0 ||
                     strcmp(method_str, "with_capacity") == 0) {
                type_prefix = "Vec";
            }
            /* String methods */
            else if (strcmp(method_str, "chars") == 0 || strcmp(method_str, "push_str") == 0 ||
                     strcmp(method_str, "as_str") == 0 || strcmp(method_str, "starts_with") == 0 ||
                     strcmp(method_str, "ends_with") == 0 || strcmp(method_str, "trim") == 0 ||
                     strcmp(method_str, "is_empty") == 0 || strcmp(method_str, "new") == 0) {
                type_prefix = "String";
            }
            /* Option methods */
            else if (strcmp(method_str, "is_some") == 0 || strcmp(method_str, "is_none") == 0 ||
                     strcmp(method_str, "unwrap") == 0 || strcmp(method_str, "unwrap_or") == 0) {
                type_prefix = "Option";
            }
            /* Use receiver type if no heuristic match */
            else if (receiver_type_name != NULL && receiver_type_name[0] != '\\0') {
                type_prefix = receiver_type_name;
            }

            SigilValue result;
            SigilValue mangled_method = sigil_mangle_name((*self), method);
            if (type_prefix[0] != '\\0') {
                result = sigil_format("sigil_{}____{}({})", sigil_string(type_prefix), mangled_method, args_str);
            } else {
                /* No type prefix - just call method with receiver */
                result = sigil_format("sigil_{}({})", mangled_method, args_str);
            }

            return sigil_CodeGen____with_evidence((*self), result, evidence);
        }
    }
'''
