# Fix TypeEnv::define to persist bindings back to the TypeEnv struct
# The generated code gets bindings by value, inserts into the copy, but never writes back!
# This causes variable lookups to fail because the binding was never actually stored.
# Pattern:
#   SigilValue _t0 = sigil_struct_field((*self), "bindings");
#   return sigil_Map____insert(_t0, name, sigil_tuple(_t1__fields, 2));
# Should be:
#   SigilValue _t0 = sigil_struct_field((*self), "bindings");
#   sigil_Map____insert(_t0, name, sigil_tuple(_t1__fields, 2));
#   sigil_struct_set_field(self, "bindings", _t0);
#   return sigil_unit();
content = re.sub(
    r'(/\* Function: TypeEnv::define \*/\n'
    r'SigilValue sigil_TypeEnv____define\(SigilValue\* self, SigilValue name, SigilValue ty, SigilValue evidence\) \{\n'
    r'    SigilValue _t0 = sigil_struct_field\(\(\*self\), "bindings"\);\n'
    r'    SigilValue _t1__fields\[2\];\n'
    r'    _t1__fields\[0\] = ty;\n'
    r'    _t1__fields\[1\] = evidence;\n'
    r'    return sigil_Map____insert\(_t0, name, sigil_tuple\(_t1__fields, 2\)\);\n'
    r'\})',
    r'''/* Function: TypeEnv::define */
SigilValue sigil_TypeEnv____define(SigilValue* self, SigilValue name, SigilValue ty, SigilValue evidence) {
    SigilValue _t0 = sigil_struct_field((*self), "bindings");
    SigilValue _t1__fields[2];
    _t1__fields[0] = ty;
    _t1__fields[1] = evidence;
    sigil_Map____insert(_t0, name, sigil_tuple(_t1__fields, 2));
    /* CRITICAL: Write modified bindings Map back to TypeEnv struct */
    sigil_struct_set_field(self, "bindings", _t0);
    return sigil_unit();
}''',
    content)
print("Fixed TypeEnv::define to persist bindings back to struct")

