# This handles patterns like: if (cond) fprintf(stderr, "[DEBUG...]");
content = re_module.sub(r'fprintf\(stderr,\s*"\[DEBUG[^"]*"[^;]*;', '((void)0);', content)
# Also remove [convert_type] and [lower_type] debug messages
