    r'SigilValue _t0 = sigil_struct_field\(\(\*self\), "errors"\);\s*'
    r'return sigil_Vec____push\(_t0, err\);',
    r'''\1/* FIX: Unwrap TAG_REF and check for valid errors field before pushing */
    if (self == NULL) {
        fprintf(stderr, "[LoweringContext::error] self is NULL\\n");
        return sigil_unit();
    }
    /* Unwrap TAG_REF to get the actual struct */
    SigilValue actual = *self;
    while (actual.tag == TAG_REF && actual.v.ptr != NULL) {
        actual = *(SigilValue*)actual.v.ptr;
    }
    if (actual.tag != TAG_STRUCT) {
        fprintf(stderr, "[LoweringContext::error] actual.tag=%d (expected TAG_STRUCT=%d)\\n", actual.tag, TAG_STRUCT);
        return sigil_unit();
    }
    SigilValue _t0 = sigil_struct_field(actual, "errors");
    if (_t0.tag != TAG_ARRAY) {
        fprintf(stderr, "[LoweringContext::error] errors field is not an array\\n");
        return sigil_unit();
    }
    return sigil_Vec____push(_t0, err);''',
    content)
print("Fixed LoweringContext::error null checks")

# Fix TypeChecker::error to handle missing errors field gracefully
content = re.sub(
    r'(SigilValue sigil_TypeChecker____error\(SigilValue\* self, SigilValue err\) \{\s*)'
    r'SigilValue _t0 = sigil_struct_field\(\(\*self\), "errors"\);\s*'
    r'return sigil_Vec____push\(_t0, err\);',
    r'''\1/* FIX: Unwrap TAG_REF and check for valid errors field before pushing */
    if (self == NULL) {
