        return sigil_unit();
    }
    SigilValue _t0 = sigil_struct_field(actual, "errors");
    if (_t0.tag != TAG_ARRAY) {
        fprintf(stderr, "[TypeChecker::error] errors field tag=%d (expected TAG_ARRAY=%d)\\n", _t0.tag, TAG_ARRAY);
        return sigil_unit();
    }
    return sigil_Vec____push(_t0, err);''',
    content)
print("Fixed TypeChecker::error null checks")

# Fix &self vs self issue for methods taking SigilValue* self
# Inside TypeChecker/LoweringContext methods, 'self' is SigilValue*, so &self gives SigilValue** (wrong)
# Closures capture 'self' by value (SigilValue), so &self is correct there - don't change those

# Strategy: Fix calls INSIDE function bodies only, not in closures
# Closures are defined as "static SigilValue sigil_closure_N(...)" and end before "/* Function: TypeChecker"
# We use a targeted approach: find the function definitions and fix calls within them

# Find and fix inside sigil_TypeChecker____unify function body
# The function takes SigilValue* self, so recursive calls should use self, not &self
import re as re_mod

def fix_self_in_function(content, func_pattern, methods_to_fix):
    """Fix &self -> self for specific method calls inside a function body."""
    # Find the function definition
    func_match = re_mod.search(func_pattern, content)
    if not func_match:
        return content

    start = func_match.start()
    # Find the matching closing brace by counting braces
    brace_count = 0
    in_function = False
    end = start
    for i, c in enumerate(content[start:], start):
        if c == '{':
            brace_count += 1
            in_function = True
        elif c == '}':
            brace_count -= 1
            if in_function and brace_count == 0:
                end = i + 1
                break

    if end <= start:
        return content

    # Extract function body
    func_body = content[start:end]

    # Fix method calls in the body
    for method in methods_to_fix:
        func_body = re_mod.sub(rf'{method}\(&self,', rf'{method}(self,', func_body)

    # Replace in content
    return content[:start] + func_body + content[end:]

# Fix &self -> self in non-closure code
# Strategy: Closures have "SigilValue self = __closure_self;" - they need &self
# Method bodies have "SigilValue* self" parameter - they need self (no &)

# Step 1: Global replace &self -> self
ptr_methods = [
    'sigil_TypeChecker____unify',
    'sigil_TypeChecker____error',
    'sigil_TypeChecker____fresh_var',
    'sigil_TypeChecker____freshen',
    'sigil_TypeChecker____push_scope',
    'sigil_TypeChecker____pop_scope',
    'sigil_TypeChecker____check_evidence',
    'sigil_TypeChecker____check_file',
    'sigil_TypeChecker____check_item',
    'sigil_TypeChecker____check_function',
    'sigil_TypeChecker____check_block',
    'sigil_TypeChecker____check_stmt',
    'sigil_TypeChecker____infer_expr',
    'sigil_TypeChecker____infer_binary_op',
    'sigil_TypeChecker____bind_pattern',
    'sigil_LoweringContext____error',
]

for method in ptr_methods:
    content = re.sub(rf'{method}\(&self,', rf'{method}(self,', content)
print(f"Step 1: Changed &self -> self for {len(ptr_methods)} methods globally")

# Step 1.5: Restore &self in wrapper functions
# Wrappers have pattern: static inline SigilValue sigil_XXX(...) { return sigil_Type____XXX(self, ...)
# They receive SigilValue self (value type) and need to pass &self to pointer-expecting functions
wrapper_restore_count = 0
for method in ptr_methods:
    # Match wrapper function pattern and restore &self
    pattern = rf'(static inline SigilValue \w+\([^)]*\) \{{ return {method}\()self,'
    replacement = rf'\1&self,'
    content, n = re.subn(pattern, replacement, content)
    wrapper_restore_count += n
print(f"Step 1.5: Restored &self in {wrapper_restore_count} wrapper functions")

# Step 2: Restore &self in closures (they have "SigilValue self = __closure_self;")
# Find each closure and restore the &self calls inside it
import re as re_mod
closure_count = 0
for match in re_mod.finditer(r'(static SigilValue sigil_closure_\d+\([^)]*\)\s*\{[^}]*SigilValue self = __closure_self;)', content):
    # Find the end of this closure function
    start = match.start()
    brace_count = 0
    in_func = False
    end = start
    for i, c in enumerate(content[start:], start):
        if c == '{':
            brace_count += 1
            in_func = True
        elif c == '}':
            brace_count -= 1
            if in_func and brace_count == 0:
                end = i + 1
                break
    if end > start:
        closure_body = content[start:end]
        # Restore &self in this closure
        for method in ptr_methods:
            closure_body = re_mod.sub(rf'{method}\(self,', rf'{method}(&self,', closure_body)
        content = content[:start] + closure_body + content[end:]
        closure_count += 1

print(f"Step 2: Restored &self in {closure_count} closures")

