# Fix let-else pattern binding scope issue
# The generated code declares bindings INSIDE the if block, but they're used OUTSIDE
# Pattern: if (...) { SigilValue VAR = sigil_enum_data(...); } else { return ...; }
# Should be: SigilValue VAR; if (...) { VAR = sigil_enum_data(...); } else { return ...; }
# We need to pre-declare the binding variable before the if block

# Fix for Item::Function pattern in parse_impl_item - this specific pattern
# Look for the full pattern including else { return to ensure we're fixing let-else, not if-else
def fix_letelse_with_enum_data(content_str):
    # Pattern: if ((sigil_is_struct_variant(_tN, "Type::Variant") || ...)) {\n                SigilValue VAR = sigil_enum_data(_tN);\n            } else {\n                return
    # This is the let-else pattern that needs fixing
    import re as re_mod

    # Match the full let-else pattern to ensure correct context
    pattern = (
        r'(if \(\(sigil_is_struct_variant\((_t\d+), "([^"]+)"\) \|\| [^)]+\)\)\) \{\s*)'
        r'SigilValue (\w+) = sigil_enum_data\(\2\);'
        r'(\s*\} else \{\s*return)'
    )

    def replacer(m):
        if_part = m.group(1)
        temp_var = m.group(2)
        variant = m.group(3)
        binding_var = m.group(4)
        else_part = m.group(5)
        return f'SigilValue {binding_var};\n        {if_part}{binding_var} = sigil_enum_data({temp_var});{else_part}'

    return re_mod.sub(pattern, replacer, content_str)

content = fix_letelse_with_enum_data(content)
print("Fixed let-else scope for enum data extraction patterns")

# Fix sigil_format to handle {{ -> { escape sequence (literal braces)
# The current implementation just copies {{ as-is, but it should output single {
# Pattern: "} else { *out++ = *p++; remaining--; }" should become
# "} else if (*p == '{' && *(p+1) == '{') { *out++ = '{'; p += 2; remaining--; } else if (*p == '}' && *(p+1) == '}') { *out++ = '}'; p += 2; remaining--; } else { *out++ = *p++; remaining--; }"
content = re.sub(
    r'(\} else \{\s*\*out\+\+ = \*p\+\+;\s*remaining--;\s*\})',
    r'''} else if (*p == '{' && *(p+1) == '{') {
            /* {{ -> { (literal brace) */
            *out++ = '{';
            p += 2;
            remaining--;
        } else if (*p == '}' && *(p+1) == '}') {
            /* }} -> } (literal brace) */
            *out++ = '}';
            p += 2;
            remaining--;
        } else {
            *out++ = *p++;
            remaining--;
        }''',
    content)
print("Fixed sigil_format to handle {{ -> { escape sequence")

