    r'sigil_is_struct_variant(_t0, "UnaryOp::Not") || (_t0.tag == TAG_ENUM && _t0.v.e.enum_id == UNARYOP_ENUM_ID && _t0.v.e.variant == UNARYOP_NOT)',
    content)
