    r'sigil_is_struct_variant(_t0, "UnaryOp::Ref") || (_t0.tag == TAG_ENUM && _t0.v.e.enum_id == UNARYOP_ENUM_ID && _t0.v.e.variant == UNARYOP_REF)',
    content)
content = re.sub(
    r'sigil_is_struct_variant\(_t0, "ast::UnaryOp::RefMut"\) \|\| \(_t0\.tag == TAG_ENUM && _t0\.v\.e\.enum_id == AST_ENUM_ID && _t0\.v\.e\.variant == AST_REFMUT\)',
    r'sigil_is_struct_variant(_t0, "UnaryOp::RefMut") || (_t0.tag == TAG_ENUM && _t0.v.e.enum_id == UNARYOP_ENUM_ID && _t0.v.e.variant == UNARYOP_REFMUT)',
    content)
content = re.sub(
