# WORKAROUND: Add closure captures for self when not present
# Closures that call methods on self need `SigilValue self = __closure_self;`
# Pattern: static SigilValue sigil_closure_N(params) { body using self... }
# If body uses 'self' but doesn't have 'SigilValue self = __closure_self;', add it
import re as re2
def fix_closure_captures(content):
    # Find all closure definitions
    closure_pattern = r'(static SigilValue sigil_closure_\d+\([^)]*\) \{\n)'

    def fix_closure(match):
        closure_start = match.group(1)
        # Find the full closure body by counting braces
        start_pos = match.end()
        brace_count = 1
        end_pos = start_pos
        while brace_count > 0 and end_pos < len(content):
            if content[end_pos] == '{':
                brace_count += 1
            elif content[end_pos] == '}':
                brace_count -= 1
            end_pos += 1

        body = content[match.start():end_pos]

        # Check if body uses 'self' (as identifier, not substring)
        # Look for patterns like (self, or self. or self) or ,self, etc
        uses_self = re2.search(r'[^a-zA-Z_]self[^a-zA-Z_0-9]', body) is not None
        has_capture = '__closure_self' in body

        if uses_self and not has_capture:
            # Insert capture declaration after opening brace
            return closure_start + '    SigilValue self = __closure_self;\n'
        return closure_start

    return re2.sub(closure_pattern, fix_closure, content)

content = fix_closure_captures(content)
print("Fixed closure captures for self")

