import os
import re

unified_path = os.environ.get('UNIFIED', './build/sigil_bootstrap.c')
with open(unified_path, 'r') as f:
    content = f.read()

# First pass: find all functions that have static inline definitions
# We'll remove forward declarations for these since they conflict
static_inline_funcs = set()
for match in re.finditer(r'^static\s+inline\s+\w+\s+(\w+)\s*\(', content, re.MULTILINE):
    static_inline_funcs.add(match.group(1))
