lines = content.split('\n')
output_lines = []
seen_defs = set()  # Track function definitions we've seen

# Patterns for function definitions
func_def_pattern = re.compile(r'^(static\s+inline\s+)?(SigilValue|bool|void|int|size_t|long long)\s+(\w+)\s*\([^)]*\)\s*\{')
static_var_pattern = re.compile(r'^static\s+(long long|int|void\s*\*)\s+(\w+)\s*=')
inline_oneliner = re.compile(r'^static\s+inline\s+\w+\s+(\w+)\s*\([^)]*\)\s*\{[^}]+\}')
fwd_decl_pattern = re.compile(r'^(SigilValue|void|bool|int|size_t)\s+(\w+)\s*\([^)]*\)\s*;')

