while i < len(lines):
    line = lines[i]

    # Handle forward declarations - skip if function has static inline definition
    fwd_decl = fwd_decl_pattern.match(line)
    if fwd_decl:
        func_name = fwd_decl.group(2)
        if func_name in static_inline_funcs:
            # Skip - this forward decl conflicts with static inline
            i += 1
            continue
        decl_key = f"decl_{func_name}"
        if decl_key not in seen_defs:
            seen_defs.add(decl_key)
            output_lines.append(line)
        i += 1
        continue

    # Handle one-liner inline functions (entire definition on one line)
    oneliner = inline_oneliner.match(line)
    if oneliner:
        func_name = oneliner.group(1)
        if func_name not in seen_defs:
            seen_defs.add(func_name)
            output_lines.append(line)
        # else skip the duplicate
        i += 1
        continue

    # Handle static variable definitions
    static_var = static_var_pattern.match(line)
    if static_var:
        var_name = static_var.group(2)
        if var_name not in seen_defs:
            seen_defs.add(var_name)
            output_lines.append(line)
        i += 1
        continue

    # Handle multi-line function definitions
    func_def = func_def_pattern.match(line)
    if func_def:
        func_name = func_def.group(3)
        if func_name in seen_defs:
            # Skip this duplicate definition until closing brace
            brace_depth = line.count('{') - line.count('}')
            i += 1
            while i < len(lines) and brace_depth > 0:
                brace_depth += lines[i].count('{') - lines[i].count('}')
                i += 1
            continue
        else:
            seen_defs.add(func_name)
            output_lines.append(line)
            i += 1
            continue

    output_lines.append(line)
    i += 1

# Count how many lines were removed
removed = len(lines) - len(output_lines)
print(f"Removed {removed} duplicate lines")

# Rejoin content for additional fixes
