# Helper function: Fix native-generated C code
# Usage: fix_native_c <input.c> [output.c]
# Called after native compiler generates C to fix known codegen bugs
fix_native_c() {
    local input="$1"
    local output="${2:-$1}"

    python3 << NATIVE_FIX
import re

with open("$input", 'r') as f:
    content = f.read()

# Fix 1: Double braces in .v.e enum initializers
# Pattern: ".v.e = {{ " should be ".v.e = { "
# Pattern: " }} };" should be " } };"
content = re.sub(r'\.v\.e = \{\{ ', r'.v.e = { ', content)
content = re.sub(r' \}\} \};', r' } };', content)

# Fix 2: Remove standalone break statements outside switch/loop
lines = content.split('\n')
fixed_lines = [line for line in lines if line.strip() != 'break;']

# Fix 3: Remove duplicate sigil__unknown declarations (keep first)
decl_count = 0
new_lines = []
for line in fixed_lines:
    if 'SigilValue sigil__unknown(void);' in line:
        decl_count += 1
        if decl_count == 1:
            new_lines.append(line)
    else:
        new_lines.append(line)

# Fix 4: Box dereference (*boxed_value) produces empty output
# When the Sigil source has: let code = self.emit_operation(*init);
# The native compiler generates: emit_operation(self, ); with empty 2nd arg
# We need to find the variable that should be passed and fill it in
# Pattern: "SigilValue VAR = sigil_struct_field(..., "FIELD");" then "emit_operation(self, );" should use VAR
import re as regex_module

def fix_box_deref(text):
    lines = text.split('\n')
    result = []
    pending_vars = []  # Stack of (varname, fieldname) tuples

    for i, line in enumerate(lines):
        # Track struct field assignments: SigilValue VAR = _tN; or SigilValue VAR = sigil_struct_field(...)
        # Pattern 1: SigilValue init = _t12;
        m = regex_module.match(r'\s*SigilValue\s+(\w+)\s*=\s*(_t\d+)\s*;', line)
        if m:
            varname = m.group(1)
            if varname in ['init', 'operand', 'receiver', 'left', 'right', 'value', 'arr', 'idx',
                          'cond', 'then_branch', 'else_branch', 'body', 'pattern', 'condition',
                          'collection', 'element', 'iter_var', 'ops']:
                pending_vars.append(varname)

        # Pattern 2: SigilValue _tN = sigil_struct_field(op, "FIELD");
        m = regex_module.match(r'\s*SigilValue\s+(_t\d+)\s*=\s*sigil_struct_field\([^,]+,\s*"(\w+)"\)\s*;', line)
        if m:
            fieldname = m.group(2)
            if fieldname in ['init', 'operand', 'receiver', 'left', 'right', 'value', 'arr', 'idx',
                            'cond', 'then_branch', 'else_branch', 'body', 'pattern', 'condition',
                            'collection', 'element', 'iter_var', 'ops']:
                # Look at next line to see if it assigns this to a named var
                pass

        # Fix empty emit_operation calls
        if 'emit_operation(self, )' in line or 'emit_operation((*self), )' in line:
            if pending_vars:
                # Use the most recent variable that matches the context
                varname = pending_vars[-1] if pending_vars else 'sigil_unit()'
                line = line.replace('emit_operation(self, )', f'emit_operation(self, {varname})')
                line = line.replace('emit_operation((*self), )', f'emit_operation((*self), {varname})')
                pending_vars.pop()  # Consume this variable

        # Clear pending vars when we hit a closing brace (end of block)
        if line.strip() == '}':
            pending_vars = []

        result.append(line)

    return '\n'.join(result)

content = '\n'.join(new_lines)
content = fix_box_deref(content)
print("Fixed box dereference: emit_operation(self, ) -> emit_operation(self, VAR)")

# Fix 5: typedef is a C reserved keyword - rename it
