# Fix 20: Escape embedded newlines in C string literals
# The native compiler emits literal newlines inside format strings instead of \n
# We use a regex to match C strings and escape any embedded newlines
def escape_string_newlines(content):
    """Find C string literals and escape embedded newlines."""
    result = []
    i = 0
    n = len(content)

    while i < n:
        # Look for start of a string literal
        if content[i] == '"':
            # Check if this quote is part of a char literal like '"'
            if i >= 1 and content[i-1] == "'" and i + 1 < n and content[i+1] == "'":
                result.append(content[i])
                i += 1
                continue

            # Start of string literal - collect until closing quote
            string_start = i
            i += 1  # skip opening quote
            string_content = ['"']

            while i < n:
                c = content[i]

                if c == '\\\\' and i + 1 < n:
                    # Escape sequence - keep as is
                    string_content.append(c)
                    string_content.append(content[i+1])
                    i += 2
                    continue

                if c == '"':
                    # End of string
                    string_content.append(c)
                    i += 1
                    break

                if c == '\\n':
                    # Embedded newline - escape it
                    string_content.append('\\\\n')
                    i += 1
                    continue

                if c == '\\r':
                    # Embedded carriage return - escape it
                    string_content.append('\\\\r')
                    i += 1
                    continue

                string_content.append(c)
                i += 1

            result.append(''.join(string_content))
        else:
            result.append(content[i])
            i += 1

    return ''.join(result)

# Fix 21: Convert pattern binding comments to actual variable declarations
# The native compiler produces:
#   SigilValue _tN = sigil_struct_field(obj, "fieldname");
#   /* Pattern binding: complex = _tN */
# Should be:
#   SigilValue _tN = sigil_struct_field(obj, "fieldname");
#   SigilValue fieldname = _tN;

def fix_pattern_bindings(content):
    """Convert pattern binding comments to actual variable declarations."""
    import re

    lines = content.split('\n')
    result = []
    i = 0
    fixed_count = 0

    # Track already-declared variable names per scope (simplified: per function)
    declared_vars = set()
    in_function = False

    while i < len(lines):
        line = lines[i]

        # Track function boundaries for scope (simplified)
        if re.match(r'^(SigilValue|void|int|bool|char\*|size_t)\s+sigil_\w+\(', line):
            declared_vars = set()
            in_function = True

        # Look for struct field extraction pattern
        struct_field_match = re.match(
            r'^(\s*)SigilValue\s+(_t\d+)\s*=\s*sigil_struct_field\([^,]+,\s*"(\w+)"\);',
            line
        )

        if struct_field_match and i + 1 < len(lines):
            indent = struct_field_match.group(1)
            temp_var = struct_field_match.group(2)
            field_name = struct_field_match.group(3)
            next_line = lines[i + 1]

            # Check if next line is a pattern binding comment for this temp
            pattern_comment_match = re.match(
                r'^\s*/\*\s*Pattern binding:\s*complex\s*=\s*' + re.escape(temp_var) + r'\s*\*/',
                next_line
            )

            if pattern_comment_match:
                # Output the struct field line
                result.append(line)

                # Replace comment with actual declaration (if not already declared)
                if field_name not in declared_vars:
                    result.append(f'{indent}SigilValue {field_name} = {temp_var};')
                    declared_vars.add(field_name)
                    fixed_count += 1
                else:
                    # Variable already declared, just assign
                    result.append(f'{indent}{field_name} = {temp_var};')
                    fixed_count += 1

                i += 2  # Skip both lines (we've processed them)
                continue

        # Also handle sigil_clone pattern:
        # SigilValue _tN = sigil_struct_field(obj, "fieldname");
        # /* Pattern binding: complex = sigil_clone(_tN) */
        clone_match = re.match(
            r'^(\s*)SigilValue\s+(_t\d+)\s*=\s*sigil_struct_field\([^,]+,\s*"(\w+)"\);',
            line
        )

        if clone_match and i + 1 < len(lines):
            indent = clone_match.group(1)
            temp_var = clone_match.group(2)
            field_name = clone_match.group(3)
            next_line = lines[i + 1]

            # Check if next line is a pattern binding with sigil_clone
            clone_comment_match = re.match(
                r'^\s*/\*\s*Pattern binding:\s*complex\s*=\s*sigil_clone\(' + re.escape(temp_var) + r'\)\s*\*/',
                next_line
            )

            if clone_comment_match:
                result.append(line)
                if field_name not in declared_vars:
                    result.append(f'{indent}SigilValue {field_name} = sigil_clone({temp_var});')
                    declared_vars.add(field_name)
                    fixed_count += 1
                else:
                    result.append(f'{indent}{field_name} = sigil_clone({temp_var});')
                    fixed_count += 1
                i += 2
                continue

        # Handle method call results pattern:
        # /* Pattern binding: complex = sigil_Method____call(...) */
        # These need variable names from context - we'll use result_N
        method_binding_match = re.match(
            r'^(\s*)/\*\s*Pattern binding:\s*complex\s*=\s*(sigil_\w+____\w+\([^)]*\))\s*\*/',
            line
        )

        if method_binding_match:
            indent = method_binding_match.group(1)
            method_call = method_binding_match.group(2)

            # Generate unique variable name based on method
            method_name = re.match(r'sigil_\w+____(\w+)', method_call)
            if method_name:
                var_name = method_name.group(1) + '_result'
                counter = 0
                base_name = var_name
                while var_name in declared_vars:
                    counter += 1
                    var_name = f'{base_name}_{counter}'

                result.append(f'{indent}SigilValue {var_name} = {method_call};')
                declared_vars.add(var_name)
                fixed_count += 1
                i += 1
                continue

        # Handle array access in loops:
        # for (size_t _tN = 0; _tN < X.v.arr.len; _tN++) {
        #     /* Pattern binding: complex = X.v.arr.data[_tN] */
        # -> Generate: SigilValue item = X.v.arr.data[_tN];
        arr_binding_match = re.match(
            r'^(\s*)/\*\s*Pattern binding:\s*complex\s*=\s*([\w.]+\.v\.arr\.data\[_t\d+\](?:\.v\.tup\.fields\[\d+\])?)\s*\*/',
            line
        )

        if arr_binding_match:
            indent = arr_binding_match.group(1)
            arr_access = arr_binding_match.group(2)

            # Determine variable name from previous for loop context or generate one
            var_name = 'it'
            counter = 0
            base_name = var_name
            while var_name in declared_vars:
                counter += 1
                var_name = f'{base_name}_{counter}'

            result.append(f'{indent}SigilValue {var_name} = {arr_access};')
            declared_vars.add(var_name)
            fixed_count += 1
            i += 1
            continue

        result.append(line)
        i += 1

    print(f"Fixed {fixed_count} pattern binding comments")
    return '\n'.join(result)

content = fix_pattern_bindings(content)

content = escape_string_newlines(content)
print("Fixed embedded newlines in C string literals")

# CG-100: Fix sigil_Vec____push to sigil_String____push for string variables
# In translate_format_tokens, result.push(chars[i]) should use String::push not Vec::push
# Pattern: sigil_Vec____push(result, chars.v.arr.data[ -> sigil_String____push(result, chars.v.arr.data[
content = re.sub(
    r'sigil_Vec____push\(result, (sigil_with_evidence\()?chars\.v\.arr\.data\[',
    r'sigil_String____push(result, \1chars.v.arr.data[',
    content)
print("Fixed sigil_Vec____push to sigil_String____push for result variable")

# CG-102: Fix sigil_String____push_str for tokens variable in parse_macro_tokens
# The issue is that push_str returns a new SigilValue when realloc happens,
# but the caller doesn't assign the result back to tokens.
# Pattern: sigil_String____push_str(tokens, -> tokens = sigil_String____push_str(tokens,
# But avoid lines that already assign to something
push_count = 0
def fix_tokens_push_str(m):
    global push_count
    # If line starts with whitespace and then sigil_String____push_str(tokens
    # and NOT preceded by = or , on same line (assignment)
    push_count += 1
    return m.group(1) + 'tokens = sigil_String____push_str(tokens,'
content = re.sub(
    r'^(\s+)sigil_String____push_str\(tokens,',
    fix_tokens_push_str,
    content, flags=re.MULTILINE)
print(f"CG-102: Fixed {push_count} sigil_String____push_str(tokens, ...) calls to assign result back")

# Also fix cases like: _t9 = sigil_String____push_str(tokens, ...)
# These need tokens updated too: tokens = _t9 = sigil_String____push_str(tokens, ...)
content = re.sub(
    r'^(\s+)(_t\d+) = sigil_String____push_str\(tokens,',
    r'\1\2 = tokens = sigil_String____push_str(tokens,',
    content, flags=re.MULTILINE)
print("CG-102: Fixed _t* = sigil_String____push_str(tokens, ...) to also update tokens")

# Same fix for sigil_String____push (single character)
content = re.sub(
    r'^(\s+)sigil_String____push\(tokens,',
    r'\1tokens = sigil_String____push(tokens,',
    content, flags=re.MULTILINE)
print("CG-102: Fixed sigil_String____push(tokens, ...) calls")

# Fix for _t* = sigil_String____push(tokens, ...) - need to also update tokens
content = re.sub(
    r'^(\s+)(_t\d+) = sigil_String____push\(tokens,',
    r'\1\2 = tokens = sigil_String____push(tokens,',
    content, flags=re.MULTILINE)
print("CG-102: Fixed _t* = sigil_String____push(tokens, ...) to also update tokens")

# CG-102b: Same fix for 'result' variable in translate_format_tokens and other functions
result_push_str_count = 0
def fix_result_push_str(m):
    global result_push_str_count
    result_push_str_count += 1
    return m.group(1) + 'result = sigil_String____push_str(result,'
content = re.sub(
    r'^(\s+)sigil_String____push_str\(result,',
    fix_result_push_str,
    content, flags=re.MULTILINE)
print(f"CG-102b: Fixed {result_push_str_count} sigil_String____push_str(result, ...) calls")

result_push_count = 0
def fix_result_push(m):
    global result_push_count
    result_push_count += 1
    return m.group(1) + 'result = sigil_String____push(result,'
content = re.sub(
    r'^(\s+)sigil_String____push\(result,',
    fix_result_push,
    content, flags=re.MULTILINE)
print(f"CG-102b: Fixed {result_push_count} sigil_String____push(result, ...) calls")

content = re.sub(
    r'^(\s+)(_t\d+) = sigil_String____push_str\(result,',
    r'\1\2 = result = sigil_String____push_str(result,',
    content, flags=re.MULTILINE)
print("CG-102b: Fixed _t* = sigil_String____push_str(result, ...) calls")

content = re.sub(
    r'^(\s+)(_t\d+) = sigil_String____push\(result,',
    r'\1\2 = result = sigil_String____push(result,',
    content, flags=re.MULTILINE)
print("CG-102b: Fixed _t* = sigil_String____push(result, ...) calls")

# CG-103a: Fix truncated identifiers from line-length overflow
# When lines exceed 65535 chars, identifiers get truncated mid-word
# Fix known truncations: sigil_with_evide -> sigil_with_evidence
truncated_fixes = [
    ('sigil_with_evide\\n', 'sigil_with_evidence\\n'),
    ('sigil_with_evide)', 'sigil_with_evidence)'),
    ('sigil_with_evide,', 'sigil_with_evidence,'),
    ('sigil_with_evide;', 'sigil_with_evidence;'),
    ('sigil_with_evide ', 'sigil_with_evidence '),
]
for old, new in truncated_fixes:
    content = content.replace(old, new)
print("CG-103a: Fixed truncated identifiers (sigil_with_evide -> sigil_with_evidence)")

# CG-103b: Break lines that exceed 65535 character limit
# GCC has a line length limit, so we need to break very long lines
MAX_LINE_LENGTH = 60000  # Safe limit below 65535
lines = content.split('\n')
fixed_lines = []
long_line_count = 0
for line in lines:
    if len(line) > MAX_LINE_LENGTH:
        long_line_count += 1
        # Break the line at safe positions (after ", " or "), ")
        result = []
        current = []
        current_len = 0
        i = 0
        while i < len(line):
            current.append(line[i])
            current_len += 1
            # Check for safe break points when we're past a reasonable length
            if current_len > 50000:
                # Look for break points
                if i + 1 < len(line) and line[i:i+2] == ', ':
                    result.append(''.join(current) + ' ')
                    current = ['    ']  # Indent continuation
                    current_len = 4
                    i += 1  # Skip the comma
                elif i + 2 < len(line) and line[i:i+3] == '), ':
                    current.append(line[i+1])  # Include the space
                    result.append(''.join(current) + ' ')
                    current = ['    ']
                    current_len = 4
                    i += 2
            i += 1
        if current:
            result.append(''.join(current))
        fixed_lines.append(' \\\\\\n'.join(result) if len(result) > 1 else ''.join(current))
    else:
        fixed_lines.append(line)
content = '\\n'.join(fixed_lines)
if long_line_count > 0:
    print(f"CG-103b: Broke {long_line_count} lines exceeding {MAX_LINE_LENGTH} chars")

# CG-104: Remove Sigil's ? operator from C code
# The ? operator (try/unwrap) is emitted literally but has no meaning in C
# Patterns like "expr?)" should become "expr)"
import re
qmark_count = len(re.findall(r'\\?\\)', content))
content = re.sub(r'\\?\\)', ')', content)
if qmark_count > 0:
    print(f"CG-104: Removed {qmark_count} invalid ? operators")

# CG-105: Fix corrupted self.field patterns
# ssigil_struct_field(elf -> sigil_struct_field((*self)
elf_count = content.count('ssigil_struct_field(elf')
content = content.replace('ssigil_struct_field(elf', 'sigil_struct_field((*self)')
if elf_count > 0:
    print(f"CG-105: Fixed {elf_count} corrupted self.field patterns")

# CG-106a: Fix chained .name field access after sigil_struct_field
# sigil_struct_field(x, "y").name) -> sigil_struct_field(sigil_struct_field(x, "y"), "name"))
name_chain_count = len(re.findall(r'sigil_struct_field\\([^)]+, "[^"]+"\\.name\\)', content))
content = re.sub(r'(sigil_struct_field\\([^)]+, "[^"]+"\\))\\.name\\)', r'sigil_struct_field(\\1, "name"))', content)
if name_chain_count > 0:
    print(f"CG-106a: Fixed {name_chain_count} chained .name field accesses")

# CG-106b: Fix .to_uppercase() method calls
# expr.to_uppercase() -> sigil_to_uppercase(expr)
toup_count = len(re.findall(r'[a-z_][a-z0-9_]*\\.to_uppercase\\(\\)', content))
content = re.sub(r'([a-z_][a-z0-9_]*)\\.to_uppercase\\(\\)', r'sigil_to_uppercase(\\1)', content)
if toup_count > 0:
    print(f"CG-106b: Fixed {toup_count} .to_uppercase() method calls")

# CG-106c: Fix .len() method calls
# expr.len() -> sigil_len(expr)
len_count = len(re.findall(r'[a-z_][a-z0-9_]*\\.len\\(\\)', content))
content = re.sub(r'([a-z_][a-z0-9_]*)\\.len\\(\\)', r'sigil_len(\\1)', content)
if len_count > 0:
    print(f"CG-106c: Fixed {len_count} .len() method calls")

# CG-107a: Fix truncated emit_binary_add format string
correct_add = '    return sigil_format("({}.tag == TAG_INT && {}.tag == TAG_INT ? sigil_int({}.v.i + {}.v.i) : {}.tag == TAG_STRING || {}.tag == TAG_STRING ? sigil_concat({}, {}) : sigil_float(({}.tag == TAG_INT ? (double){}.v.i : {}.v.f) + ({}.tag == TAG_INT ? (double){}.v.i : {}.v.f)))",  l,  r,  l,  r,  l,  r,  l,  r,  l,  l,  l,  r,  r,  r);'
truncated_pattern = r'    return sigil_format\\( : \\{\\}\\.v\\.f\\)\\)\\)",  l,  r,  l,  r,  l,  r,  l,  r,  l,  l,  l,  r,  r,  r\\);'
add_count = len(re.findall(truncated_pattern, content))
content = re.sub(truncated_pattern, correct_add, content)
if add_count > 0:
    print(f"CG-107a: Fixed {add_count} truncated emit_binary_add")

# CG-107b: Fix unescaped quotes in format strings
# sigil_struct_field(it, "tag") inside format -> sigil_struct_field(it, \\"tag\\")
old_quote = 'sigil_struct_field(it, "tag") == TAG_INT ? (double)sigil_struct_field(it, "v").i : sigil_struct_field(it, "v").f'
new_quote = 'sigil_struct_field(it, \\\\"tag\\\\") == TAG_INT ? (double)sigil_struct_field(it, \\\\"v\\\\").i : sigil_struct_field(it, \\\\"v\\\\").f'
quote_count = content.count(old_quote)
content = content.replace(old_quote, new_quote)
if quote_count > 0:
    print(f"CG-107b: Fixed {quote_count} unescaped quotes in format strings")

# CG-107c: Fix emit_pattern_condition calls with unnecessary &
# emit_pattern_condition(&_t... -> emit_pattern_condition(_t...
pattern_cond_count = len(re.findall(r'sigil_CodeGen____emit_pattern_condition\\(&(_t\\d+),', content))
content = re.sub(r'sigil_CodeGen____emit_pattern_condition\\(&(_t\\d+),', r'sigil_CodeGen____emit_pattern_condition(\\1,', content)
if pattern_cond_count > 0:
    print(f"CG-107c: Fixed {pattern_cond_count} unnecessary & in emit_pattern_condition")

# CG-107d: Break lines over 60000 chars to avoid GCC truncation
MAX_LINE = 60000
lines = content.split('\\n')
fixed_lines = 0
new_lines = []
for line in lines:
    if len(line) > MAX_LINE:
        result = ""
        current = line
        while len(current) > MAX_LINE:
            break_pos = -1
            for pos in range(MAX_LINE - 1, MAX_LINE // 2, -1):
                if current[pos:pos+2] in [', ', ') ', '; ']:
                    break_pos = pos + 2
                    break
            if break_pos == -1:
                break_pos = MAX_LINE
            result += current[:break_pos] + '\\n'
            current = '    ' + current[break_pos:]
        result += current
        new_lines.append(result)
        fixed_lines += 1
    else:
        new_lines.append(line)
content = '\\n'.join(new_lines)
if fixed_lines > 0:
    print(f"CG-107d: Broke {fixed_lines} lines over 60000 chars")

with open("$output", 'w') as f:
    f.write(content)

print(f"Fixed native codegen issues in: $input")
NATIVE_FIX
}

# Export the function for use
export -f fix_native_c 2>/dev/null || true
